@layer foundation, appearance;
@layer foundation {
:root {  --bg:#edf2ee;  --ink:#203f43;  --muted:#718380;  --green:#225b55;  --gold:#b48e4e;  --line:#d6e0d9;}
* {  box-sizing: border-box;}
body {  margin: 0;  background: var(--bg);  color: var(--ink);  font-family:
    Manrope,
    system-ui,
    sans-serif;  font-size: 14px;}
button,
a,
input {  -webkit-tap-highlight-color: transparent;}
button {  font: inherit;  cursor: pointer;  min-height: 46px;  border: 1px solid var(--line);  border-radius: 12px;  background: #fafbf7;  color: var(--ink);  padding: 11px 18px;  font-weight: 700;}
button:hover {  filter: brightness(.96);}
button:disabled {  opacity: .45;  cursor: default;}
a {  color: inherit;  text-decoration: none;}
header {  height: 92px;  display: flex;  align-items: center;  justify-content: space-between;  gap: 16px;  padding: 0 4%;  background: #f8faf6;  border-bottom: 1px solid var(--line);}
.brand {  display: flex;  align-items: center;  gap: 12px;  font-size: 17px;  letter-spacing: 3px;  font-weight: 800;}
.brand small {  font-size: 8px;  letter-spacing: 2px;  display: block;  color: var(--muted);  margin-top: 5px;}
.crest {  font-family: serif;  font-size: 44px;  color: var(--gold);}
.wallet {  display: flex;  gap: 10px;}
.wallet span {  background: #eef2eb;  border: 1px solid #dfe5d8;  padding: 10px 13px;  border-radius: 12px;  font-size: 13px;  font-weight: 800;}
.wallet i {  font-style: normal;  color: var(--gold);  margin-right: 7px;}
.app {  max-width: 1600px;  margin: auto;}
main {  padding: 30px 4% 22px;  min-height: calc(100vh - 200px);}
.eyebrow {  font-size: 10px;  font-weight: 800;  letter-spacing: 3px;  text-transform: uppercase;  color: var(--gold);  margin: 0 0 9px;}
h1,
h2,
h3,
p {  margin-top: 0;}
h1,
h2,
h3 {  font-family:
    "Cormorant Garamond",
    Georgia,
    serif;}
h1 {  font-size: 42px;  line-height: 1.05;  margin-bottom: 12px;}
h2 {  font-size: 30px;  margin-bottom: 12px;}
h3 {  font-size: 25px;  margin-bottom: 6px;}
p {  line-height: 1.7;  color: var(--muted);}
.topline {  display: flex;  justify-content: space-between;  align-items: center;  margin-bottom: 20px;}
.badge {  font-size: 10px;  letter-spacing: 1px;  text-transform: uppercase;  padding: 8px 12px;  border: 1px solid #d7e0d5;  border-radius: 20px;  color: var(--green);}
.hero {  position: relative;  min-height: 465px;  border-radius: 22px;  overflow: hidden;  background:
    linear-gradient(
      115deg,
      #acc8bb,
      #d9c9de);  box-shadow: 0 16px 38px #234d4315;}
.hero-bg {  position: absolute;  inset: 0;  background: url(assets/sunny-garden.webp) center 58%/cover;}
.hero:after {  content: "";  position: absolute;  inset: 0;  background:
    linear-gradient(
      90deg,
      #153e38dc 0%,
      #153e3865 36%,
      transparent 70%);}
.hero-copy {  position: relative;  z-index: 1;  padding: 45px 36px;  width: 44%;  color: #fff;}
.hero-copy h1 {  font-size: 54px;}
.hero-copy p {  color: #e1eee4;  font-size: 13px;}
.hero-copy .eyebrow {  color: #e4ce92;}
.primary {  background: var(--green);  color: white;  border-color: var(--green);}
.hero .primary {  background: #eff3e4;  color: #234c40;  border-color: transparent;}
.ghost {  background: transparent;  border-color: #ccd7cc;}
.row {  display: flex;  align-items: center;  gap: 10px;  flex-wrap: wrap;}
.section-title {  display: flex;  align-items: end;  justify-content: space-between;  margin: 26px 0 14px;}
.section-title h2 {  margin: 0;}
.grid {  display: grid;  grid-template-columns: repeat(3, 1fr);  gap: 18px;}
.panel,
.card {  border: 1px solid var(--line);  background: #f8faf6;  border-radius: 18px;  padding: 22px;}
.card {  position: relative;  overflow: hidden;}
.card p {  font-size: 12px;}
.feature {  display: grid;  grid-template-columns: 1fr 110px;  align-items: center;  min-height: 164px;}
.feature button {  font-size: 12px;  min-height: 38px;  padding: 7px 15px;}
.feature .art {  height: 100px;}
.art {  width: 100%;  height: 190px;  display: flex;  align-items: center;  justify-content: center;  background:
    radial-gradient(
      ellipse at center,
      #c5e9e05c,
      transparent 70%);  position: relative;}
.art svg {  height: 100%;  width: 100%;  max-width: 280px;  filter: drop-shadow(0 9px 8px #21433322);}
.rarity {  font-size: 9px;  letter-spacing: 2px;  color: var(--gold);  font-weight: 800;}
.item-footer {  display: flex;  justify-content: space-between;  align-items: center;  margin-top: 14px;  gap: 6px;}
.item-footer button {  padding: 9px 12px;  font-size: 12px;}
.selected {  border-color: var(--gold);  box-shadow: 0 0 0 1px #b48e4e40;}
.equipped {  position: absolute;  top: 15px;  right: 16px;  color: var(--green);  font-size: 10px;}
.tabs {  display: flex;  gap: 8px;  margin: 20px 0;}
.tabs button.active {  background: var(--green);  color: white;}
nav {  position: sticky;  bottom: 0;  z-index: 10;  background: #f9fbf7ed;  backdrop-filter: blur(15px);  border-top: 1px solid var(--line);  display: flex;  justify-content: center;  gap: 8px;  padding: 9px 3%;  padding-bottom: max(9px, env(safe-area-inset-bottom));}
nav button {  min-width: 110px;  border: none;  background: transparent;  border-radius: 12px;  font-size: 12px;  color: var(--muted);  padding: 8px 15px;}
nav button.active {  background: #e5eee5;  color: var(--green);}
nav .navico {  display: block;  font-size: 20px;  margin-bottom: 3px;}
footer {  text-align: center;  font-size: 9px;  letter-spacing: .4px;  color: var(--muted);  padding: 10px 15px;}
.toast {  position: fixed;  bottom: 100px;  left: 50%;  transform: translateX(-50%);  background: #163b34;  color: white;  border-radius: 13px;  padding: 15px 24px;  z-index: 50;  opacity: 0;  pointer-events: none;  transition: .2s;  max-width: 90vw;}
.toast.show {  opacity: 1;}
dialog {  border: 1px solid #c1d5c7;  border-radius: 24px;  background: #f5f8ef;  max-width: 600px;  width: 90%;  text-align: center;  color: var(--ink);  padding: 30px;  max-height: 90vh;  overflow: auto;}
dialog::backdrop {  background: #102a2c99;  backdrop-filter: blur(7px);}
.split {  display: grid;  grid-template-columns: 1.2fr 1fr;  gap: 22px;}
.summon {  min-height: 405px;  background:
    radial-gradient(
      ellipse at center,
      #e3d7ee,
      #c2d9ce);  text-align: center;  display: flex;  flex-direction: column;  align-items: center;  justify-content: center;  position: relative;  overflow: hidden;}
.summon .orb {  font-size: 110px;  color: #f8f3d8;  text-shadow: 0 0 40px #e9e0ff, 0 0 80px #a48dce;  animation: float 4s ease-in-out infinite;}
.summon p {  max-width: 300px;}
.progress {  height: 6px;  background: #dce5dc;  border-radius: 8px;  overflow: hidden;  margin: 12px 0;}
.progress b {  display: block;  height: 100%;  background: var(--gold);}
.milestone {  display: flex;  justify-content: space-between;  padding: 11px 0;  border-bottom: 1px solid var(--line);  font-size: 12px;}
.milestone.done {  color: #3e8774;}
.rules {  font-size: 11px;  line-height: 1.8;  color: var(--muted);}
.rewards {  display: flex;  gap: 8px;  flex-wrap: wrap;  justify-content: center;  margin: 20px 0;}
.reward {  background: #e5eddf;  border-radius: 10px;  padding: 10px;  font-size: 12px;}
.game-layout {  display: grid;  grid-template-columns: minmax(0, 1fr) 280px;  gap: 20px;}
.canvas-wrap {  background: #1c353c;  border: 6px solid #f8faf3;  border-radius: 20px;  overflow: hidden;  box-shadow: 0 12px 28px #1d454318;  position: relative;}
canvas {  display: block;  width: 100%;  touch-action: none;  aspect-ratio: 720/520;}
.game-hud {  display: flex;  gap: 8px;  justify-content: space-between;  margin-bottom: 14px;  flex-wrap: wrap;}
.game-hud > span {  padding: 7px 12px;  background: #e6eddf;  border-radius: 10px;  font-size: 12px;}
.controls {  display: grid;  gap: 10px;}
.controls button {  width: 100%;  text-align: left;}
.controls small {  display: block;  font-weight: 400;  margin-top: 3px;  color: var(--muted);}
.settings {  max-width: 720px;  margin: auto;}
.settings .panel {  margin-bottom: 15px;}
.hero-equip {  position: absolute;  right: 16px;  bottom: 16px;  z-index: 2;  padding: 12px 18px;  background: #f8faf1e6;  backdrop-filter: blur(12px);  border-radius: 16px;  display: flex;  gap: 12px;  align-items: center;  max-width: 45%;}
.hero-equip .mini {  width: 75px;  height: 66px;}
.hero-equip small {  display: block;  font-size: 9px;  color: var(--muted);}
.hero-equip strong {  font-family: Georgia, serif;  font-size: 17px;}
.hero-equip .mini svg {  width: 100%;  height: 100%;}
.inventory-count {  color: var(--muted);  font-size: 12px;}
@keyframes float {
  50% {    transform: translateY(-12px);}}
@media (min-width: 1300px) {
  .hero {    min-height: 530px;}}
@media (max-width: 900px) {
  header {    height: 80px;}
  .brand {    font-size: 14px;    letter-spacing: 1.5px;}
  .wallet {    gap: 5px;}
  .wallet span {    padding: 8px;    font-size: 11px;}
  .grid {    gap: 12px;}
  .card {    padding: 17px;}
  .hero-copy {    width: 50%;    padding: 30px 24px;}
  .hero-copy h1 {    font-size: 46px;}
  .game-layout {    grid-template-columns: 1fr;}
  .controls {    grid-template-columns: repeat(3, 1fr);}
  .split {    grid-template-columns: 1fr 1fr;}
  .feature {    grid-template-columns: 1fr 75px;}
  .feature .art {    height: 80px;}
  nav button {    min-width: 90px;}
  .hero {    min-height: 430px;}}
@media (max-width: 600px) {
  header {    padding: 12px 4%;    height: auto;    flex-wrap: wrap;}
  .wallet {    width: 100%;    justify-content: space-between;}
  .wallet span {    flex: 1;    text-align: center;}
  .brand small {    font-size: 7px;}
  main {    padding-top: 20px;}
  .topline {    align-items: start;}
  h1 {    font-size: 34px;}
  .topline .badge {    font-size: 8px;    padding: 6px;}
  .hero {    min-height: 485px;}
  .hero-copy {    width: 85%;    padding: 28px 23px;}
  .hero-copy h1 {    font-size: 44px;}
  .hero:after {    background:
      linear-gradient(
        180deg,
        #153e38cf,
        transparent 85%);}
  .hero-bg {    background-position: 60% center;}
  .hero-copy p {    max-width: 240px;}
  .hero-equip {    max-width: 90%;    left: 16px;    right: auto;}
  .grid {    grid-template-columns: 1fr 1fr;}
  .grid.features {    grid-template-columns: 1fr;}
  .feature {    min-height: 130px;    grid-template-columns: 1fr 130px;}
  .split {    grid-template-columns: 1fr;}
  .art {    height: 145px;}
  .card h3 {    font-size: 22px;}
  nav {    gap: 0;    padding-left: 0;    padding-right: 0;}
  nav button {    min-width: 0;    width: 20%;    padding: 7px 3px;    font-size: 9px;}
  .controls {    grid-template-columns: 1fr 1fr;}
  .section-title h2 {    font-size: 26px;}
  .item-footer {    flex-wrap: wrap;}
  .item-footer button {    width: 100%;}
  .hero-equip strong {    font-size: 15px;}}
.profile {  min-height: 515px;  display: grid;  grid-template-columns: 225px minmax(290px, 1fr) 260px;  gap: 18px;  padding: 24px;  border-radius: 22px;  overflow: hidden;  position: relative;  isolation: isolate;  background: #9cb9b0;}
.profile-bg {  position: absolute;  inset: 0;  z-index: -2;  background:
    linear-gradient(
      90deg,
      #1e494b80,
      #e2f1e020 50%,
      #28464470),
    url(assets/sunny-garden.webp) center 42%/cover;  filter: saturate(.65);}
.profile:after {  content: "";  position: absolute;  inset: 0;  z-index: -1;  background:
    linear-gradient(
      0deg,
      #1b403b80,
      transparent 55%);}
.profile-panel {  background: #f6faf1e8;  border: 1px solid #fff9;  border-radius: 16px;  backdrop-filter: blur(20px);  padding: 22px;}
.profile-panel h2 {  font-size: 35px;  margin-bottom: 8px;}
.level-pill {  font-size: 9px;  letter-spacing: 1px;  font-weight: 800;  color: var(--green);}
.xp {  font-size: 9px;  color: var(--muted);  display: block;  text-align: right;  margin-top: -6px;}
.power {  margin: 20px 0;  border-bottom: 1px solid #c7d4c4;  padding-bottom: 14px;}
.power small {  display: block;  font-size: 8px;  font-weight: 700;  letter-spacing: 2px;  color: var(--muted);}
.power strong {  display: block;  font-size: 30px;  font-family: Georgia, serif;  margin-top: 5px;  color: #8c733d;}
.stat {  display: flex;  justify-content: space-between;  padding: 8px 0;  font-size: 12px;  border-bottom: 1px solid #d6dfd144;}
.profile-note {  font-size: 9px;  line-height: 1.7;  margin: 15px 0 0;}
.hero-stage {  position: relative;  min-height: 450px;  display: flex;  justify-content: center;  align-items: center;}
.stage-halo {  position: absolute;  bottom: 60px;  width: 85%;  height: 45px;  border: 1px solid #f5e6bbaa;  border-radius: 50%;  box-shadow: 0 0 30px #f4efc580, inset 0 0 35px #f2ebc444;}
.avatar {  height: 430px;  max-width: 100%;  object-fit: contain;  position: relative;  z-index: 2;  filter: drop-shadow(0 13px 8px #203f3844);  pointer-events: none;}
.avatar-wings {  position: absolute;  width: 140%;  max-width: 530px;  height: 330px;  top: 0;  left: 50%;  transform: translateX(-50%);  filter: drop-shadow(0 0 20px #f0eddb55);  animation: wingfloat 6s ease-in-out infinite;}
.avatar-wings svg {  width: 100%;  height: 100%;}
.companion {  position: absolute;  z-index: 3;  bottom: 44px;  right: -25px;  width: 170px;  text-align: center;}
.companion svg {  width: 100%;  filter: drop-shadow(0 10px 8px #1e3e3a33);}
.companion span:not(.animated-dragon) {  font-size: 10px;  letter-spacing: 2px;  color: #fff0ce;  background: #1a453ab0;  padding: 5px 12px;  border-radius: 20px;}
.character-label {  position: absolute;  bottom: -5px;  text-align: center;  z-index: 4;  color: #fff5d8;  text-shadow: 0 2px 8px #183c3a;}
.character-label span {  display: block;  font-size: 8px;  letter-spacing: 2px;}
.character-label strong {  font-size: 30px;  font-family: Georgia, serif;  display: block;  font-weight: 400;  margin: 4px;}
.character-label small {  font-size: 10px;}
.equipment-panel {  padding: 19px;}
.equipment-panel h3 {  font-size: 26px;  margin-bottom: 14px;}
.gear-grid {  display: grid;  grid-template-columns: 1fr 1fr;  gap: 8px;}
.gear {  display: flex;  align-items: center;  flex-direction: column;  text-align: center;  padding: 9px 5px;  font-size: 9px;  border-color: #cbd9c7;  background: #f7faedb3;  min-height: 75px;}
.gear-icon {  font-size: 23px;  color: #a58650;  margin-bottom: 3px;}
.gear small {  display: block;  font-size: 8px;  color: var(--muted);  margin-top: 4px;}
.equip-special {  width: 100%;  display: flex;  align-items: center;  gap: 7px;  text-align: left;  font-size: 11px;  min-height: 60px;  padding: 5px;  margin-top: 9px;  background: #eff4e7;}
.equip-special small {  display: block;  font-size: 9px;  font-weight: 400;  color: var(--muted);  margin-top: 4px;}
.equip-special b {  margin-left: auto;  margin-right: 6px;}
.tiny-art {  display: inline-flex;  width: 64px;  height: 52px;  align-items: center;  justify-content: center;  flex-shrink: 0;}
.tiny-art svg {  width: 100%;  height: 100%;}
.feature-emblem {  font-size: 90px;  color: #a6bda5;  text-align: center;  text-shadow: 0 5px 0 #526f6c17;}
.reward-choices {  display: grid;  grid-template-columns: 1fr 1fr;  gap: 8px;  margin: 18px 0;}
.reward-choices button {  display: flex;  align-items: center;  font-size: 12px;  padding: 6px;}
.adventure-visual {  height: 180px;  border-radius: 12px;  margin-bottom: 22px;  display: flex;  justify-content: center;  align-items: center;}
.castle-art {  background:
    radial-gradient(
      ellipse at bottom,
      #9fb8a6,
      #254c4d);  position: relative;}
.castle-art span {  font-size: 130px;  color: #e5d9ae;  text-shadow: 0 8px 0 #16393355;}
.castle-art i {  position: absolute;  right: 20%;  top: 25px;  font-size: 50px;  color: #f5d7a2;}
.merge-art {  background:
    radial-gradient(
      ellipse at center,
      #d2c1e4,
      #c4dbd0);}
.egg-preview {  display: flex;  align-items: center;  justify-content: center;  border-radius: 50%;  height: 55px;  width: 55px;  color: #526b61;  border: 2px solid #fff7;  font-size: 25px;  box-shadow: inset 6px 7px 12px #fff7;}
.controls p {  font-size: 11px;  margin: 7px 0;}
.controls .eyebrow {  margin: 0 0 8px;}
input:not([type=file]) {  display: block;  width: 100%;  min-height: 46px;  padding: 10px 12px;  background: #fffdf4;  border: 1px solid var(--line);  border-radius: 10px;  color: var(--ink);  font: inherit;  margin: 8px 0 12px;}
label {  font-size: 12px;}
.collection-grid {  grid-template-columns: repeat(4, 1fr);}
hr {  border: 0;  border-top: 1px solid var(--line);  margin: 20px 0;}
.portrait-tip {  display: none;}
@media (max-width: 1100px) {
  .profile {    grid-template-columns: 190px minmax(230px, 1fr) 220px;    padding: 18px;    gap: 10px;}
  .profile-panel {    padding: 17px;}
  .avatar {    height: 400px;}
  .hero-stage {    min-height: 430px;}
  .companion {    width: 140px;    right: -12px;    bottom: 60px;}
  .collection-grid {    grid-template-columns: repeat(2, 1fr);}}
@media (orientation: landscape) and (max-height: 850px) {
  header {    height: 70px;}
  main {    padding-top: 20px;}
  .topline {    margin-bottom: 15px;}
  .topline h1 {    font-size: 34px;}
  .profile {    min-height: 420px;}
  .hero-stage {    min-height: 395px;}
  .avatar {    height: 375px;}
  .profile-panel {    padding: 16px;}
  .profile-note {    display: none;}
  .power {    margin: 12px 0;    padding-bottom: 10px;}
  .stat {    padding: 6px 0;}
  .gear {    min-height: 62px;}
  .avatar-wings {    height: 290px;}
  .character-label {    bottom: 0;}
  .companion {    bottom: 50px;}
  .gear-grid {    gap: 6px;}
  .profile-panel h2 {    font-size: 29px;}}
@media (orientation: portrait) {
  .portrait-tip {    display: block;    text-align: center;    background: #dce8d7;    border: 1px solid #cbd8c4;    padding: 10px;    font-size: 11px;    color: var(--green);    margin-bottom: 14px;    border-radius: 12px;}}
@media (max-width: 750px) {
  .profile {    grid-template-columns: 150px minmax(200px, 1fr) 180px;    overflow-x: auto;    gap: 8px;    padding: 12px;}
  .profile-panel {    padding: 12px;}
  .profile h2 {    font-size: 25px;}
  .profile .eyebrow {    font-size: 8px;    letter-spacing: 1px;}
  .hero-stage {    min-height: 410px;}
  .avatar {    height: 360px;}
  .gear {    font-size: 8px;}
  .companion {    width: 120px;    right: -8px;}
  .profile-panel h3 {    font-size: 23px;}
  .stat {    font-size: 10px;}
  .profile-note {    display: none;}
  .avatar-wings {    width: 150%;}
  .equip-special {    font-size: 9px;}
  .equip-special .tiny-art {    width: 45px;}
  .power strong {    font-size: 25px;}}
@keyframes wingfloat {
  0%, 100% {    transform: translateX(-50%) translateY(0);}
  50% {    transform: translateX(-50%) translateY(-9px);}}
:root {  --ink:#f3e9d4;  --muted:#b5c9c7;  --green:#327b78;  --gold:#dfc28a;  --line:#b99e694f;  --bg:#102c38;}
html,
body {  height: 100%;  overflow: hidden;}
body {  background: #17333e url(assets/sunny-garden.webp) center/cover fixed;  font-size: 13px;}
body:before {  content: "";  position: fixed;  inset: 0;  background:
    linear-gradient(
      90deg,
      #061c37b0,
      #15324c15 47%,
      #061c37a0),
    linear-gradient(
      0deg,
      #061d38bb,
      transparent 40%,
      #061c3899);  pointer-events: none;}
.app {  max-width: none;  height: 100dvh;  position: relative;  isolation: isolate;}
header {  height: 69px;  position: absolute;  inset: 0 0 auto;  z-index: 20;  background:
    linear-gradient(
      180deg,
      #071e32ed,
      #0b253933,
      transparent);  border: 0;  padding: 6px 28px;  gap: 8px;}
.brand {  font-family: Georgia, serif;  letter-spacing: 2px;  font-size: 18px;  font-weight: 400;  color: #f4dfae;  text-shadow: 0 2px 9px #000;}
.brand small {  font-family: Manrope, sans-serif;  font-size: 6px;  letter-spacing: 2px;  color: #e4d6b2;  opacity: .8;}
.crest {  font-size: 42px;  color: #e1c080;  filter: drop-shadow(0 0 10px #d2b77855);}
.wallet {  gap: 13px;}
.wallet span {  border-radius: 5px;  background:
    linear-gradient(
      160deg,
      #173f4be6,
      #081c33e6);  border: 1px solid #bca16d80;  padding: 8px 13px;  color: #f6e9cc;  font-size: 12px;  box-shadow: inset 0 1px #ffe2a41c, 0 3px 8px #0003;  min-width: 110px;  text-align: center;}
.wallet i {  color: #efcd8b;}
.wallet small {  font-size: 9px;  font-weight: 500;  color: #bbc9c5;}
main {  position: absolute;  inset: 70px 0 84px;  min-height: 0;  padding: 18px 36px;  overflow-y: auto;  scrollbar-width: thin;  scrollbar-color: #cbb17d88 transparent;}
