/* Phase 1: viewport scenes. Lists scroll only inside named, framed windows. */
#stage {
  --menu-header: 82px;
  --menu-nav: 86px;
  --menu-gap: clamp(8px, 1.2vmin, 18px);
  --menu-pad: clamp(10px, 1.5vmin, 24px);
  --menu-title: clamp(24px, 3.2vmin, 38px);
  --menu-copy: clamp(15px, 1.7vmin, 20px);
  width: 100%;
  max-width: none;
  height: 100dvh;
  min-height: 0;
  margin: 0;
  overflow: hidden;
  isolation: isolate;
}
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
#stage *, #stage *::before, #stage *::after { box-sizing: border-box; }
body:not([data-playing]) #stage > header {
  position: absolute;
  inset: env(safe-area-inset-top) 0 auto;
  height: var(--menu-header);
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: var(--menu-gap);
  padding: 5px max(var(--menu-pad), env(safe-area-inset-right)) 5px max(var(--menu-pad), env(safe-area-inset-left));
}
body:not([data-playing]) #stage .brand { width: clamp(125px, 20vw, 230px); max-width: 34%; min-width: 0; height: 70px; min-height: 0; padding: 0; flex: 0 1 auto; }
body:not([data-playing]) #stage .generated-logo { display: block; width: 100%; height: 100%; object-fit: contain; }
body:not([data-playing]) #stage .wallet { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); width: min(55%, 430px); min-width: 0; flex: 0 1 430px; padding: 0; gap: clamp(3px, 1vw, 14px); }
body:not([data-playing]) #stage .wallet > span { display: flex; align-items: center; justify-content: center; gap: 4px; width: auto; min-width: 0; max-width: none; margin: 0; padding: 5px 0; font-size: clamp(16px, 2.3vmin, 25px); line-height: 1.1; white-space: nowrap; }
body:not([data-playing]) #stage .wallet > span > .gpt-icon { display: inline-block; flex: 0 0 clamp(22px, 3vmin, 32px); width: clamp(22px, 3vmin, 32px); height: clamp(22px, 3vmin, 32px); min-width: 0; max-width: none; padding: 0; }
body:not([data-playing]) #stage .wallet small { display: none; }
body:not([data-playing]) #stage > #main {
  position: absolute;
  inset: calc(var(--menu-header) + env(safe-area-inset-top)) max(var(--menu-pad), env(safe-area-inset-right)) calc(var(--menu-nav) + env(safe-area-inset-bottom)) max(var(--menu-pad), env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  gap: var(--menu-gap);
  width: auto;
  height: auto;
  min-height: 0;
  min-width: 0;
