body:not([data-playing]) #stage > nav .nav-label { display: block; font-size: clamp(12px, 1.8vmin, 18px); line-height: 1.1; white-space: nowrap; }
body:not([data-playing]) #stage > nav .navico, body:not([data-playing]) #stage > nav .navico > .gpt-icon { width: clamp(30px, 4.5vmin, 43px); height: clamp(30px, 4.5vmin, 43px); min-width: 0; margin: 0; }
#stage > footer { display: none; }
#stage .topline, #stage .bag-top, #stage .game-section-title { flex: 0 0 auto; height: auto; min-height: 42px; margin: 0; padding: 0; gap: 8px; }
#stage .topline h1, #stage .bag-top h1, #stage .game-section-title h1 { font-size: var(--menu-title); line-height: 1.1; margin: 0; }
#stage .topline .eyebrow, #stage .bag-top .eyebrow, #stage .topline::after, #stage .topline > div::after, #stage .bag-top > div::after, #stage .game-section-title::after { display: none; }
