/* A scene may own several independent windows, but never a scrolling page. */
#stage :is(.scene-window, .menu-scroll-window, .inventory-scroll, .boss-selection-grid, .quest-list, .collection-grid, .bot-roster, .ranking-panel, .exp-ally-grid, .settings-window, .journal-window) { min-height: 0; min-width: 0; overflow: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; scrollbar-width: none; touch-action: pan-y; }
