#stage button:not(:disabled,.equipment-cell,.material-cell,.material-summary,.storage-slot,.boss-gate-portrait,.hero-attribute,.party-member)::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  padding: 1.5px;
  background: conic-gradient(from var(--button-light-angle),transparent 0 68%,#f2c56880 78%,#fff7ce 86%,#f6cc7266 92%,transparent 100%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  animation: button-edge-light 2.8s linear infinite;
}
#stage button:not(:disabled,.equipment-cell,.material-cell,.material-summary,.storage-slot,.boss-gate-portrait,.hero-attribute,.party-member)::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  border: 0;
  background-image: linear-gradient(115deg,transparent 42%,#fff2b800 44%,#fff5cb66 50%,#fff2b800 56%,transparent 58%);
  background-size: 300% 100%;
  background-repeat: no-repeat;
  mix-blend-mode: screen;
  pointer-events: none;
  animation: button-face-light 2.8s ease-in-out infinite;
}
@keyframes button-edge-light { to { --button-light-angle: 360deg; } }
@keyframes button-face-light { 0% { background-position: 150% 0; opacity: 0; } 14% { opacity:.8; } 82% { background-position: -50% 0; opacity:.8; } 95%,100% { background-position:-50% 0; opacity:0; } }
