#main .dungeon-lobby .lobby-card[aria-pressed="true"]{border:2px solid #fff3b8;background:linear-gradient(#3aa0de,#2a6fb6);box-shadow:0 0 12px #7fd0ffaa}
.lobby-card-art{width:100%;height:clamp(3rem,13cqw,5.2rem);display:grid;place-items:center;border-radius:.4rem;background:radial-gradient(circle,color-mix(in srgb,var(--portal-color) 55%,transparent) 0,transparent 70%)}
