.lobby-card strong{font-size:clamp(.66rem,2.5cqw,.9rem);line-height:1.1;color:#ffd98a;min-height:2.2em;display:grid;align-items:center}
.lobby-card small{font-size:clamp(.62rem,2.2cqw,.8rem);opacity:.85}
.lobby-card em{font-style:normal;font-weight:700;font-size:clamp(.62rem,2.3cqw,.82rem);display:flex;align-items:center;gap:.15rem}
.lobby-card em .gpt-icon{width:1em;height:1em}.lobby-card em.open{color:#8dff8a}.lobby-card em.cleared{color:#bfe4ff}.lobby-card em.locked{color:#ffb3a6}
.lobby-go{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;justify-items:center;row-gap:.15rem;padding:.2rem .6rem .5rem}
#main .dungeon-lobby .lobby-enter{grid-column:2;min-width:min(15rem,56cqw);min-height:3.3rem;font-size:clamp(1.2rem,5cqw,1.6rem);border-radius:1.8rem}
#main .dungeon-lobby .lobby-help{grid-column:3;justify-self:start;margin-left:.6rem;width:2.6rem;height:2.6rem;min-width:0;min-height:0;padding:0;border-radius:50%;font-size:1.4rem;font-weight:700}
.lobby-go small{grid-column:1/-1;font-size:clamp(.7rem,2.5cqw,.85rem);opacity:.85}
#main .dungeon-lobby button::before,#main .dungeon-lobby button::after{content:none!important;display:none!important}
.lobby-title{position:relative;z-index:2}.lobby-tiers{position:relative}
#main .dungeon-lobby button{outline:0!important;border-image:none!important}
#main .dungeon-lobby button:focus-visible{outline:2px solid #fff3b8!important;outline-offset:1px}
.lobby-tiers .action-art-icon,.lobby-help .action-art-icon{display:none!important}
#main .dungeon-lobby .lobby-tiers button[aria-pressed="true"]{opacity:1;box-shadow:0 0 10px #7fd0ffcc,inset 0 0 0 1px #fff}
.lobby-card-art{overflow:hidden}
#main .dungeon-lobby .lobby-card-art img{display:block;width:100%!important;height:100%!important;max-height:100%;object-fit:contain;filter:none}
.lobby-card strong{position:relative}
/* Small screens: the lobby may scroll, and the stage keeps a workable height. */
