.dungeon-lobby{height:auto;min-height:100%;grid-template-rows:auto minmax(19rem,1fr) auto auto auto}
.lobby-left{gap:clamp(.15rem,1.2cqw,.5rem)}
@container (max-width:520px){
 .lobby-disc{width:2.2rem;height:2.2rem}
