@container (max-width:520px){.dungeon-lobby{grid-template-rows:auto minmax(15rem,1fr) auto auto auto}}

/* Companion room: preview, appearance cards, stats/action, modes, slot tabs */
body[data-screen="cityCompanion"] #main{padding:0!important;overflow:hidden!important}
.comp-room{height:100%;min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr) auto auto auto auto;color:#f1f6ff;background:radial-gradient(120% 70% at 50% 30%,#3d5fa3 0,#274774 48%,#1e2f5a 100%);container-type:inline-size;overflow:hidden}
.comp-top{display:flex;align-items:center;gap:.6rem;padding:.45rem .8rem;font-size:clamp(.85rem,3cqw,1.1rem)}
.comp-top strong{margin-right:auto;font-size:clamp(1.05rem,4cqw,1.5rem)}.comp-top span{display:flex;align-items:center;gap:.2rem}.comp-top .gpt-icon{width:1.4em;height:1.4em}
.comp-stage{position:relative;min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr);justify-items:center}
.comp-stage h2{margin:0;font-size:clamp(1.1rem,4.6cqw,1.8rem);color:#ffe27a;text-shadow:0 2px 0 #3a2a10}
.comp-figure{min-height:0;height:100%;max-width:96%;object-fit:contain;filter:drop-shadow(0 10px 12px #0b153088)}
.comp-float{height:70%;align-self:center;animation:comp-bob 2.4s ease-in-out infinite alternate}
@keyframes comp-bob{to{transform:translateY(-5%)}}
.comp-steps{position:absolute;left:50%;bottom:1%;width:34%;transform:translateX(-12%);pointer-events:none}
.comp-cards{display:flex;gap:.4rem;padding:.4rem .6rem;overflow-x:auto;scrollbar-width:thin;-webkit-overflow-scrolling:touch;background:#16284ecc;border-block:1px solid #7194c7}
#main .comp-room .comp-card{position:relative;flex:0 0 clamp(4.6rem,19cqw,6.6rem);min-width:0;min-height:0;padding:.25rem .15rem .3rem;display:grid;justify-items:center;gap:.1rem;border-radius:.5rem;border:1px solid #5f86c4;background:linear-gradient(#27477f,#1d3663);color:#fff7dc;box-shadow:none}
#main .comp-room .comp-card[aria-pressed="true"]{border:2px solid #fff3b8;background:linear-gradient(#3aa0de,#2a6fb6)}
.comp-card img{width:100%;height:clamp(3.4rem,14cqw,5rem);object-fit:contain}
.comp-card span{font-size:clamp(.62rem,2.3cqw,.82rem);line-height:1.1;min-height:2.2em;display:grid;align-items:center;text-align:center}
.comp-card em{font-style:normal;font-weight:700;font-size:clamp(.6rem,2.1cqw,.76rem);color:#8dff8a}.comp-card em.price{color:#ffe27a}
.comp-panel{display:grid;grid-template-columns:1.2fr 1fr;align-items:center;gap:.5rem;padding:.4rem .8rem;background:#1b3158e6}
.comp-stats>div{display:grid;grid-template-columns:1.5fr 1fr 1fr;padding:.12em 0;font-size:clamp(.78rem,2.8cqw,1rem)}.comp-stats em{color:#bade76;font-style:normal}
.comp-action{display:grid;justify-items:center;gap:.2rem;padding-left:.5rem;border-left:1px dashed #7894af;text-align:center}
.comp-action strong{font-size:clamp(.9rem,3.2cqw,1.15rem)}.comp-action small{font-size:clamp(.72rem,2.5cqw,.9rem);opacity:.9}.comp-action progress{width:85%;height:.5em;accent-color:#b5d978}
#main .comp-room .comp-action button{min-width:min(9rem,34cqw);min-height:2.5rem;font-size:clamp(.95rem,3.4cqw,1.2rem)}
.comp-modes{display:flex;gap:.3rem;padding:.3rem .6rem;background:#16284e}
#main .comp-room .comp-modes button{flex:1;min-width:0;min-height:2.2rem;padding:.15rem;border-radius:.4rem;border:1px solid #5f86c4;background:#2b4b86;color:#dbe9ff;font-size:clamp(.85rem,3.1cqw,1.1rem);box-shadow:none}
#main .comp-room .comp-modes button[aria-pressed="true"]{background:linear-gradient(#3ea6e6,#2b7fc9);border-color:#e9f6ff;color:#fff}
.comp-nav{display:flex;align-items:stretch;background:#132445;border-top:1px solid #8798b1}
#main .comp-room .comp-nav button{flex:1;min-width:0;min-height:0;padding:.25rem .1rem .35rem;display:grid;justify-items:center;gap:.05rem;border:0;border-radius:0;background:none;color:#e6efff;font-size:clamp(.62rem,2.3cqw,.82rem);line-height:1.05;box-shadow:none}
#main .comp-room .comp-nav button[aria-pressed="true"]{background:#8a5a2ecc;color:#ffe9b5}
.comp-nav img{width:clamp(2rem,8cqw,2.8rem);height:clamp(2rem,8cqw,2.8rem);object-fit:contain}
#main .comp-room .comp-nav .comp-back{flex:0 0 12%;font-size:1.6rem}
#main .comp-room button::before,#main .comp-room button::after{content:none!important;display:none!important}
#main .comp-room button{outline:0!important;border-image:none!important}
.comp-room .action-art-icon{display:none!important}
/* Home screen: fairy and footsteps */
.fx-elf{left:60%;top:35%;width:15%;height:13%;z-index:3;animation:comp-bob 2.2s ease-in-out infinite alternate}
.fx-footprint{left:40%;top:60.5%;width:16%;height:6%;z-index:0;transform:none;display:block}
.fx-elf img,.fx-footprint img{width:100%;height:100%;object-fit:contain}
@media (prefers-reduced-motion:reduce){.comp-float,.fx-elf{animation:none}}
.comp-top{padding-left:5.2rem}
.comp-nav img{width:clamp(2.2rem,9cqw,3.1rem);height:clamp(2.2rem,9cqw,3.1rem)}

/* Mounted Reina on the home screen: smaller, so the mount does not cover the buttons around her */
.city-hud .city-hero.riding{left:32.5%;top:41%;width:35%;height:24%}
.city-hud .city-wings.riding{left:25%;top:37%;width:50%;height:20%}
/* Footsteps trail away behind her, starting at her feet */
.fx-footprint{left:33%;top:59.5%;width:18%;height:6.5%;transform:scaleX(-1)}
.comp-steps{left:auto;right:47%;bottom:3%;width:36%;transform:scaleX(-1)}
/* Cards: picture, two-line name, price, never overlapping */
#main .comp-room .comp-card{grid-template-rows:auto 2.3em 1.15em;align-items:center;overflow:hidden}
.comp-card span{font-size:clamp(.6rem,2.2cqw,.8rem);line-height:1.12;max-height:2.3em;overflow:hidden}
.comp-card em{line-height:1.15}
.comp-card img{height:clamp(3.8rem,15cqw,5.4rem)}
.fashion-card img{object-fit:contain}
.fx-footprint{left:29.5%}
.comp-steps{right:54%}
.trek-buffs{bottom:13%;gap:1.6cqw}.trek-buffs span{display:none}.trek-buffs span.on{display:grid}.trek-buffs b{right:-6px;font-size:max(12px,2.9cqw)}

/* Mini Games cards: title with one readable line under it (best score, best time). */
body[data-screen=games] #stage .portal-game-info .booth-title{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0}
body[data-screen=games] #stage .portal-game-info .booth-title span{display:block;font-size:14px;line-height:1.2;font-weight:700;color:#ffe9ac!important;-webkit-text-fill-color:#ffe9ac;opacity:1;text-shadow:0 1px 3px #06140f,0 0 6px #06140f;white-space:nowrap}
body[data-screen=games] #stage .portal-illustration{background:#244a3c}
.trek-top small,.trek-top strong,.trek-rank{color:#fff4d7;-webkit-text-fill-color:currentColor}
.trek-top #trekLives{display:inline-block;transform-origin:70% 50%}
.trek-top #trekLives.hit{animation:trekHit .5s ease-out}
@keyframes trekHit{0%{transform:scale(1.55);filter:brightness(2.2)}60%{transform:scale(.94)}100%{transform:none;filter:none}}
/* Footsteps: a flat track on the ground behind her heels, drawn behind her (never across her legs). */
.comp-stage .comp-figure{position:relative;z-index:1}
.comp-steps{z-index:0;right:47%;bottom:4%;width:40%;transform-origin:50% 100%;transform:scaleX(-1) scaleY(.8)}
/* The track lies BEHIND Reina: it starts under her heels and recedes up-left into the distance, getting smaller,
   and is drawn before the pets and before her (markup order: footsteps, pets, hero). */
.fx-footprint{left:31%;top:55.2%;width:17%;height:9.4%;z-index:1;transform-origin:50% 100%;transform:scaleX(-1) scaleY(.85)}

/* Footsteps as the user sketched them on a screenshot: the nearest mark between her feet, the next ones beside her
   left leg and on back-left into the distance, one small mark between her legs. The box is 2 x 1.4 "stances" (the
   distance between her boots), with the midpoint between her feet at 70% / 93% of it. */
.step-track{position:absolute;pointer-events:none;z-index:1}
.step-track img{position:absolute;height:auto;transform:translate(-50%,-50%) scaleY(.82)}
.step-track .step-0{left:68%;top:67.9%;width:30%}
.step-track .step-1{left:38%;top:52.1%;width:24.5%;opacity:.97}
.step-track .step-2{left:39.5%;top:25%;width:18%;opacity:.9}
.step-track .step-3{left:28.5%;top:26.4%;width:16.5%;opacity:.86}
.step-track .step-4{left:20%;top:16.4%;width:13%;opacity:.74}
.step-track .step-5{left:72.5%;top:37.1%;width:16%;opacity:.9}
.home-steps{left:34.1%;top:54.7%;width:18.8%;height:9.15%}
.room-steps{left:19.3%;bottom:2%;width:36%;aspect-ratio:2/1.4;z-index:0}

/* ===== Pets (rebuilt after the user's reference photos). Root: .spirit-room.den ===== */
#main .den{grid-template-rows:auto minmax(0,1fr) 8.5%;background:radial-gradient(1px 1px at 12% 9%,#fff 50%,transparent 51%),radial-gradient(1px 1px at 78% 14%,#fff 50%,transparent 51%),radial-gradient(1.5px 1.5px at 32% 24%,#cfe6ff 50%,transparent 51%),radial-gradient(1px 1px at 88% 31%,#fff 50%,transparent 51%),radial-gradient(1.5px 1.5px at 8% 36%,#cfe6ff 50%,transparent 51%),radial-gradient(ellipse at 50% 27%,#4a66d6 0,transparent 52%),linear-gradient(#131c4a,#1d3f86 44%,#1c6c9c);overflow:hidden}
#main .den button::before,#main .den button::after{content:none!important;display:none!important}
#main .den button{border-image:none!important;outline:0!important;min-width:0;min-height:0}
.den .den-x{display:none}
.den-top{position:relative;display:flex;align-items:flex-start;justify-content:space-between;min-height:10.5cqh;padding:1cqh 2cqw 0}
.den-ribbon{padding:.38em 1.7em .38em 1em;background:linear-gradient(90deg,#3f8fd0,#2a5fae);clip-path:polygon(0 0,100% 0,92% 100%,0 100%);font-size:3.6cqw;letter-spacing:.02em;text-shadow:0 1px 2px #0b1a44}
.den-power{position:absolute;left:50%;top:5.4cqh;transform:translateX(-50%);padding:.2em 1.1em;border-radius:99px;background:#0c173fb8;border:1px solid #7fb4ff66;font-size:4.4cqw;color:#ffd98a;white-space:nowrap}.den-power b{color:#fff3c9}
#main .den .den-rec{display:grid;justify-items:center;gap:.2em;padding:.2em .5em;background:transparent;border:0;font-size:2.5cqw;line-height:1.1;color:#eaf4ff;text-shadow:0 1px 2px #0b1a44}
.den-rec i{display:grid;place-items:center;width:2.3em;height:2.3em;font-size:1.5em;font-style:normal;color:#fff;background:radial-gradient(#7fd4ff,#2a5fae);border:1px solid #cfe6ff;clip-path:polygon(50% 0,93% 25%,93% 75%,50% 100%,7% 75%,7% 25%)}
.den-body{display:flex;flex-direction:column;gap:.9cqh;min-height:0;padding:0 3.5cqw 1cqh;overflow:hidden}
.den-stage{position:relative;flex:1;min-height:0}
.den-stage img{position:absolute;object-fit:contain;pointer-events:none;-webkit-user-drag:none}
.den-main{left:50%;bottom:3%;height:94%;max-width:74%;transform:translateX(-50%);filter:drop-shadow(0 1.2cqh 1.4cqh #050b2a99);z-index:2}
.den-flank{bottom:20%;height:60%;max-width:42%;filter:brightness(.78) saturate(.85) drop-shadow(0 .8cqh 1cqh #050b2a99);z-index:1}
.den-flank-0{left:-3%}.den-flank-1{right:-3%}
.den-glow{position:absolute;left:14%;right:14%;bottom:-2%;height:20%;background:radial-gradient(ellipse,#bfe6ff77 0,#7fb4ff33 40%,transparent 70%);z-index:0}
.den-dim{filter:drop-shadow(0 1.2cqh 1.4cqh #050b2a99)}   /* not collected yet: shown in full colour, marked by a badge, never greyed out */
.den-name{position:absolute;left:0;right:0;bottom:0;z-index:3;margin:0!important;display:flex;align-items:center;justify-content:center;gap:.5em;font-size:4.2cqw!important;text-shadow:0 2px 3px #050b2a,0 0 8px #050b2a}
.den em{font-style:normal}
.den-name em,.den-rarity{padding:.12em .6em;border-radius:.3em;font-size:.62em;color:#1a1438;background:var(--edge);text-shadow:none}
.den-c{--edge:#a6e3b3;--bg:linear-gradient(#4f8f74,#1f4c46)}.den-r{--edge:#86cbff;--bg:linear-gradient(#3f78cc,#1b3a80)}.den-e{--edge:#d0adff;--bg:linear-gradient(#8355d8,#3a2784)}.den-s{--edge:#ffd884;--bg:linear-gradient(#d09434,#74441a)}.den-l{--edge:#ffa8cc;--bg:linear-gradient(#d84c92,#64205c)}
/* skills */
.den-skills{display:grid;grid-template-columns:1fr 1fr;gap:2cqw}
.den-skills>div{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:1fr 1fr;column-gap:1.6cqw;row-gap:.5cqh;align-items:center;padding:.5cqh 1.6cqw .5cqh .6cqw;background:linear-gradient(90deg,#17377ccc,#17377c55);border-radius:6cqw 1.2cqw 1.2cqw 6cqw}
.den-skills small{position:absolute;left:1cqw;top:-.5em;font-size:.82em;text-shadow:0 1px 2px #050b2a}
.den-orb{position:relative;grid-row:1/3;display:grid;place-items:center;width:11cqw;aspect-ratio:1;border-radius:50%;border:2px solid #cfe6ff;background:radial-gradient(#6a4bc4,#161a4e);overflow:visible}
.den-orb img{position:static;width:92%;height:92%;object-fit:contain;border-radius:50%}
.den-orb u{position:absolute;right:-.2em;bottom:-.2em;min-width:1.5em;padding:.05em .2em;border-radius:99px;background:#0c173f;border:1px solid #cfe6ff;text-decoration:none;font-size:.8em}
.den-aura{font-size:5cqw;color:#fff;background:radial-gradient(var(--edge),#161a4e 78%)}
.den-tag{display:block;padding:.32em .8em;border-radius:99px;font-size:.84em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 1px 1px #0006}
.den-tag.o{background:linear-gradient(#f5b25a,#d9822b);border:1px solid #ffdca6}.den-tag.v{background:linear-gradient(#a06bf5,#6f3fcf);border:1px solid #d3bbff}
/* level, bar, stats */
.den-level{display:flex;align-items:center;gap:2cqw;font-size:1.12em}
.den-level::before,.den-level::after{content:"";flex:1;height:1px;background:linear-gradient(90deg,transparent,#9fd0ff)}.den-level::after{transform:scaleX(-1)}
.den-level span{padding:0 .4em}
.den-exp{display:grid;grid-template-columns:auto minmax(0,1fr);gap:2cqw;align-items:center;padding:0 5cqw}
.den-exp>span{position:relative;height:1.25em;border-radius:99px;background:#0c173f;border:1px solid #5d8fd6;overflow:hidden}
.den-exp i{position:absolute;inset:0 auto 0 0;background:linear-gradient(#c6f56a,#6fc43a);border-radius:99px}
.den-exp b{position:absolute;inset:0;display:grid;place-items:center;font-size:.86em;text-shadow:0 1px 2px #0b1a44}
.den-stats{display:grid;grid-template-columns:1fr 1fr;gap:.45cqh 4cqw;padding:0 6cqw;text-align:left}
.den-stats b{color:#fff}.den-up{margin-left:.9em;font-style:normal;color:#8dff7a}
.den-cost{display:flex;align-items:center;justify-content:center;gap:.4em;min-height:1.5em}.den-cost .low{color:#ff8a8a}
.den-gem{color:#8fe3ff;text-shadow:0 0 6px #4ab8ff}
#main .den .den-gold{align-self:center;padding:.5em 2.6em;border:0;background:linear-gradient(#ffe89a,#f0b548 60%,#d9942e);color:#5a3a12;font-size:1.25em;clip-path:polygon(7% 0,93% 0,100% 50%,93% 100%,7% 100%,0 50%);filter:drop-shadow(0 2px 2px #0006)}
#main .den .den-gold:disabled{filter:grayscale(.7) brightness(.8);opacity:.75}
.den-modes{display:grid;grid-template-columns:repeat(3,1fr);gap:1cqw}
#main .den .den-modes button{padding:.45em .2em;border:0;border-bottom:2px solid transparent;background:linear-gradient(#22478f99,#17336c99);color:#cfe1ff;font-size:1.02em;clip-path:polygon(4% 0,100% 0,96% 100%,0 100%)}
#main .den .den-modes button[aria-pressed=true]{background:linear-gradient(#3f8fd0,#2a5fae);color:#fff;border-bottom-color:#ffe27a}
/* cards */
.den-lineup{display:flex;justify-content:center;gap:2.4cqw}.den-lineup>div{width:20cqw;display:grid;gap:.3cqh}
#main .den .den-card,#modalBody .den-card{position:relative;display:block;width:100%;aspect-ratio:3/4;padding:0;border:2px solid var(--edge,#86cbff);border-radius:.6em;background:var(--bg,linear-gradient(#3f78cc,#1b3a80));color:#fff;overflow:hidden;box-shadow:0 2px 6px #0007;font:inherit}
.den-card img{position:absolute;left:5%;top:9%;width:90%;height:62%;object-fit:contain;filter:drop-shadow(0 2px 2px #0008)}
.den-card em{position:absolute;left:0;top:0;z-index:1;padding:.1em .5em .12em;border-radius:0 0 .5em 0;background:var(--edge);color:#1a1438;font-size:.72em;font-style:normal}
.den-card .den-stars{position:absolute;left:0;right:0;bottom:25%;color:#ffd84a;font-size:.78em;letter-spacing:-.08em;text-shadow:0 1px 1px #000,0 0 3px #000}
