#modalBody .den-congrats{width:100%;box-sizing:border-box}

/* Pets not collected yet: full colour, with a padlock chip on the card and a ribbon on the stage */
.den-card .den-lockchip{position:absolute;right:3%;top:3%;z-index:2;display:grid;place-items:center;width:1.7em;height:1.7em;border-radius:50%;background:#0c173fd9;border:1px solid #ffd98a;font-size:.8em;font-style:normal;line-height:1}
.den-stage .den-notyet{position:absolute;left:50%;top:3%;z-index:3;transform:translateX(-50%);padding:.3em 1.2em;border-radius:99px;background:#0c173fd9;border:1px solid #ffd98a;color:#ffe9b8;white-space:nowrap;font-size:1.02em}

/* ===== Pets: gear, talents, talent shop ===== */
.den-ico{display:block;width:100%;aspect-ratio:1;background-repeat:no-repeat;font-style:normal;flex:none}
.den-chips .den-ico,.den-cost .den-ico,.den-ware em .den-ico,.den-check .den-ico{display:inline-block;width:1.5em;vertical-align:middle}
.den-chips{display:flex;gap:1.2cqw;margin-left:auto;align-items:center}
.den-chips>span{display:flex;align-items:center;gap:.3em;padding:.15em .7em .15em .3em;border-radius:99px;background:#0c173fb8;border:1px solid #7fb4ff66;font-size:.95em}
.den-chips .gpt-icon{width:1.5em;height:1.5em}
#main .den .den-plain{padding:.45em 1.2em;border:1px solid #9fd0ff;border-radius:99px;background:#16306a;color:#eaf4ff;font-size:1em}
/* gear */
.den-gearstage .den-main{max-width:56%;height:88%}
.den-gearcol{position:absolute;left:0;top:1%;bottom:10%;z-index:3;width:15.5cqw;display:grid;grid-template-rows:repeat(4,minmax(0,1fr));gap:.9cqh;justify-items:center}
.den-gearcol.den-right{left:auto;right:0}
#main .den .den-gear{position:relative;height:100%;aspect-ratio:1;max-width:100%;padding:6%;border:2px solid #c98bff;border-radius:.6em;background:linear-gradient(#6a2f9a,#2a1b5c);box-shadow:0 2px 6px #0007}
