.den-gear b{position:absolute;right:5%;bottom:2%;font-size:.86em;color:#ffe9a0;text-shadow:0 1px 2px #000,0 0 3px #000}
.den-gearinfo p u,.den-hint u{color:#ffe27a;cursor:pointer;margin-left:.6em}
/* talents */
.den-hexes{display:grid;grid-template-columns:repeat(5,13.2cqw);justify-content:center;gap:1cqh 3.4cqw;padding-top:1.4cqh}
#main .den .den-hex{position:relative;aspect-ratio:1;padding:0;border:0;background:transparent;display:grid;place-content:center;justify-items:center;color:#fff;opacity:1}
#main .den .den-hex .den-ico{width:13.2cqw}
#main .den .den-hex[aria-pressed=true]{filter:drop-shadow(0 0 5px #ffe27a) drop-shadow(0 0 2px #fff);transform:scale(1.1)}
#main .den .den-free,#main .den .den-shut{clip-path:polygon(50% 2%,93% 26%,93% 74%,50% 98%,7% 74%,7% 26%)}
#main .den .den-free{background:linear-gradient(#27468f,#182c66);box-shadow:inset 0 0 0 2px #5d8fd6}
#main .den .den-shut{background:linear-gradient(#162257,#0e163d)}
.den-hex i{font-style:normal;font-size:1.25em;line-height:1}
.den-hex small{font-size:.8em;color:#ffe9a0}.den-hex small.low{color:#ff8a8a}
.den-hex u{position:absolute;right:-6%;top:-6%;display:grid;place-items:center;width:1.6em;height:1.6em;border-radius:50%;background:#0c173f;border:1px solid #ffd98a;text-decoration:none;font-size:.72em}
.den-rounds{display:flex;justify-content:space-between}.den-rounds span{display:flex;gap:3cqw}
#main .den .den-rounds button{display:grid;justify-items:center;gap:.15em;padding:0;border:0;background:transparent;color:#eaf4ff;font-size:.86em;text-shadow:0 1px 2px #0b1a44}
