.den-modes.den-two{grid-template-columns:repeat(2,1fr);padding:0 8cqw}
.den-tpanel{display:flex;flex-direction:column;justify-content:center;gap:.8cqh;overflow:auto}
.den-trow{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:.9em;align-items:center;text-align:left}
