.den-hint{margin:0!important;color:#d9e6ff}.den-kind{color:#ffd98a}
.den-learn{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:2cqw}.den-learn .den-cost{justify-content:flex-start;padding-left:1cqw}
