.den-check[aria-pressed=true]>i{background:#ffe27a;box-shadow:inset 0 0 0 .22em #17336c}
.den-check small{display:flex;align-items:center;color:#d9c3ff}
.den-slots{display:flex;justify-content:center;gap:2.4cqw}
