#main .den .den-slots button[aria-pressed=true]{border-color:#ffe27a;background:#2a5fae}
.den-slots img,.den-slots i{width:8.4cqw;height:8.4cqw;border-radius:50%;object-fit:contain;background:radial-gradient(#6a4bc4,#161a4e);border:2px solid #d0adff;display:grid;place-items:center;font-style:normal}
/* talent shop */
#main .den[data-page=TalentShop]{background:radial-gradient(ellipse at 50% 0,#c98a4a 0,transparent 60%),linear-gradient(#7a4a26,#3f2412)}
.den-shophead{display:grid;grid-template-columns:24cqw minmax(0,1fr);gap:2.4cqw;align-items:center;padding:.6cqh 2cqw;text-align:left}
