.den-wares{flex:1;min-height:0;overflow:auto;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.6cqw;align-content:start;grid-auto-rows:max-content;padding:.4cqw;scrollbar-width:none}
