#main .den .den-ware b{color:#b01e3a;text-shadow:none}#main .den .den-ware small{color:#7a5a3a}#main .den .den-ware em{color:#5a3a12;font-style:normal}
/* Home: the three Primary Pets stand around Reina: slot 1 at her left, slot 2 at her right, slot 3 in front of her
   on the stone circle (the sides are taken by menu icons). */
.city-hud .city-pet-2{left:51%;bottom:27.5%;width:17%;height:11.5%;z-index:2}
/* Home: pets larger and closer to Reina (user request) */
.city-hud .city-pet{width:21%;height:14.5%;bottom:34%}
.city-hud .city-pet-0{left:20.5%}.city-hud .city-pet-1{left:58.5%}
.city-hud .city-pet-2{left:47%;bottom:22.5%;width:22%;height:15%}

/* Pets: pop-up cards instead of full-screen dialogs */
#stage #modal.den-pop{width:min(430px,calc(100vw - 48px));max-width:calc(100vw - 48px);max-height:min(74dvh,640px);padding:14px 14px 12px;border-radius:18px;box-shadow:0 18px 60px #050b2acc}
#stage #modal.den-pop::backdrop{background:#0a1030a6;backdrop-filter:blur(2px)}
#stage #modal.den-pop .dialog-menu-exit{display:none}
#stage #modal.den-pop #modalBody{font:700 14px/1.35 Arial,sans-serif;text-align:center}
#stage #modal.den-pop h2{font-size:22px;margin:2px 36px 8px}
#stage #modal.den-pop #modalBody>p{font-size:14px;line-height:1.4;font-weight:400;margin:6px 0}
#stage #modal.den-pop .den-tlist{max-height:none;font-size:13px;gap:9px}
#stage #modal.den-pop .den-trow .den-ico{width:44px}
#stage #modal.den-pop .den-trow b{font-size:15px}#stage #modal.den-pop .den-trow small{font-size:12px}#stage #modal.den-pop .den-trow p{font-size:13px}
#stage #modal.den-pop button{font-size:14px;min-height:36px;padding:6px 14px}
#stage #modal.den-pop>.dialog-dismiss{display:grid;place-items:center;width:44px;min-width:44px;height:44px;min-height:44px;padding:0;margin:0;border:0;background:transparent;box-shadow:none}
#stage #modal.den-pop>.dialog-dismiss::before,#stage #modal.den-pop>.dialog-dismiss::after{display:none}
#stage #modal.den-pop>.dialog-dismiss .gpt-icon{width:35px;height:35px;margin:0}
#stage #modal.den-pop .den-picker{max-height:none}
#stage #modal.den-pop .den-burst{width:min(52vw,220px)}
#stage #modal.den-pop #modalBody{outline:0}
#stage #modal.den-pop h2+p{margin-right:6px;margin-left:6px}
#stage #modal.den-pop .den-x{display:none}
#stage #modal.den-pop .den-card b{bottom:15%;font-size:11px;line-height:1}
#stage #modal.den-pop .den-card small{bottom:3%;font-size:10px;line-height:1}
#stage #modal.den-pop .den-card em{font-size:9px}
#stage #modal.den-pop .den-summoned .den-card b{font-size:9.5px;bottom:16%}
#stage #modal.den-pop .den-summoned .den-card small{font-size:9px}
#stage #modal.den-pop .den-card img{height:58%}
#stage #modal.den-pop .den-congrats small{font-size:12px}

/* ===== Back buttons: one painted icon everywhere (ui-back.webp), never a thin "<" glyph, never smaller than 52 px ===== */
html body #stage button[data-back][data-back]{outline:0!important;border-image:none!important;font-size:0!important;line-height:0!important;color:transparent!important;text-shadow:none!important;border:0!important;border-radius:0!important;box-shadow:none!important;box-sizing:border-box;padding:5px!important;min-width:52px!important;min-height:52px!important;background:url(assets/generated/ui-back.webp) center/contain no-repeat content-box!important;filter:drop-shadow(0 2px 3px #0009);cursor:pointer;opacity:1!important}
html body #stage button[data-back][data-back]::before,html body #stage button[data-back][data-back]::after{content:none!important;display:none!important}
html body #stage button[data-back][data-back]:active{transform:scale(.9)}
#stage .spirit-nav button[data-back]{flex:0 0 17%!important;padding:4px!important;background-color:transparent!important}
#main .comp-room .comp-nav .comp-back[data-back]{flex:0 0 17%!important}
#main .pairs-exit[data-back]{width:3.6rem;height:3.6rem;background-color:transparent!important}
#main .pairs-screen .pairs-foot .pairs-exit[data-back]{width:3.4rem;height:3.4rem}
#stage .trek-controls button[data-back]{width:58px;height:58px;pointer-events:auto}
/* the same icon inside text buttons ("Back", "Back to Mini Games") */
.gpt-icon.back-ico{background:url(assets/generated/ui-back.webp) center/contain no-repeat!important}
/* "Menu" (return to the city from any screen): the icon and the word in one pill */
#stage .return-to-menu{min-height:48px;padding:3px 16px 3px 50px;border-radius:99px;font-size:16px;background:url(assets/generated/ui-back.webp) 4px center/40px 40px no-repeat,#332b40f2}
#stage>.return-to-menu{right:auto;left:max(6px,env(safe-area-inset-left))}
/* A screen with its own Back icon does not also need the Menu pill (it used to cover the screen's title). */
body:has(#main button[data-back]) #stage>.return-to-menu{display:none}

/* Item card: what a shop ware is, before buying */
#stage #modal.den-pop:has(.den-item){width:min(360px,calc(100vw - 48px));padding:0;overflow:hidden;background:#1d2f66;border:1px solid #9fb6ff}
#stage #modal.den-pop:has(.den-item) #modalBody{text-align:left}
.den-item-head{display:grid;grid-template-columns:64px minmax(0,1fr);gap:12px;align-items:center;padding:12px 46px 12px 14px;background:linear-gradient(135deg,#ff7a8a,#e2485f)}
.den-item-head .den-ico{width:64px;filter:drop-shadow(0 2px 2px #0006)}
.den-item-head b{display:block;font-size:19px;color:#fff}.den-item-head small{display:block;font-size:13px;color:#ffe9ec}.den-item-head u{text-decoration:none;color:#c9ff9e}
#stage #modal.den-pop .den-item h3{margin:12px 14px 4px;font:700 15px Arial,sans-serif;color:#ffe9a0}
#stage #modal.den-pop .den-item p{margin:0 14px 8px;font-size:14px;line-height:1.4;font-weight:400}
#stage #modal.den-pop .den-item .den-why{color:#ffb0b8;font-weight:700}
.den-item .den-actions{display:flex;justify-content:center;padding:4px 0 14px}
#stage #modal.den-pop .den-gold{display:inline-flex;align-items:center;gap:.3em;padding:8px 26px;border:0;background:linear-gradient(#ffe89a,#f0b548 60%,#d9942e);color:#5a3a12;font:700 16px Arial,sans-serif;clip-path:polygon(7% 0,93% 0,100% 50%,93% 100%,7% 100%,0 50%)}
#stage #modal.den-pop .den-gold:disabled{filter:grayscale(.7) brightness(.8);opacity:.75}
#stage #modal.den-pop .den-gold .den-ico{display:inline-block;width:1.4em}

/* Talent Shop: Top wares stand out; small star chip on their art */
.den-wareart{position:relative;display:block;width:42%}.den-wareart>.den-ico{width:100%}
.den-kindchip{position:absolute;left:-14%;top:-8%;font-style:normal;font-size:1.1em;color:#ffd84a;text-shadow:0 1px 2px #5a2a00,0 0 4px #5a2a00}
#main .den .den-topware{background:linear-gradient(#fff6d6,#ffd98a);box-shadow:0 0 0 2px #ffb93c,0 2px 6px #0007}
#main .den .den-ware small{font-size:.8em!important;line-height:1.15!important;font-weight:400}
#main .den .den-ware b{font-size:.95em;line-height:1.1}
#main .den .den-trow small{font-size:.85em!important;line-height:1.2!important}
#main .den .den-trow p{font-size:.95em}
#main .den .den-topware b{color:#8a4a00}
/* Pets room: a small note at the top instead of a big banner over the buttons */
body:is([data-screen=cityPet],[data-screen=cityBag],[data-screen=cityVault],[data-screen=cityDevour],[data-screen=cityCraft],[data-screen=citySummon],[data-screen=cityContest],[data-screen=citySocial],[data-screen=cityGuild],[data-screen=citySupreme],[data-screen=cascade]) #stage .toast{top:5.2%!important;bottom:auto!important;left:50%!important;right:auto!important;transform:translateX(-50%)!important;width:auto!important;max-width:72%!important;min-height:0!important;padding:7px 16px!important;border-radius:99px!important;font:700 14px/1.25 Arial,sans-serif!important;text-align:center}
#main .den .den-check small{font-size:.8em!important}

/* Bag contents, warehouse and Devour (2026-11-20). Tiles share .satchel-stack; --rarity colours frame and plate. */
body:is([data-screen=cityVault],[data-screen=cityDevour]) #stage{width:min(100%,55dvh);margin-inline:auto}
body:is([data-screen=cityVault],[data-screen=cityDevour]) #stage>:is(header,nav,footer){display:none!important}
body:is([data-screen=cityVault],[data-screen=cityDevour]) #stage>#main{inset:0!important;width:100%;height:100%;padding:0!important;display:block;overflow:auto}
.bag-ico{display:block;width:84%;aspect-ratio:1;background:var(--bag-items) no-repeat;background-size:400% 400%;font-style:normal;flex:none}
#stage #main .satchel .bag-tile{background:linear-gradient(160deg,color-mix(in srgb,var(--rarity) 62%,#1c2244),color-mix(in srgb,var(--rarity) 24%,#1c2244));border-width:3px}
#stage #main .satchel .bag-tile b{right:5%;bottom:2%;font:700 2.5cqw/1 Arial,sans-serif;color:#fff;text-shadow:0 1px 0 #000,0 0 3px #000,0 0 3px #000}
#stage #main .satchel .bag-tile .den-ico{width:80%}
#stage #main .satchel .bag-tile>img{width:100%;height:100%;object-fit:cover;object-position:50% 20%}
#stage #main .satchel .bag-tile .gpt-icon{width:70%;height:70%}
.bag-bar{position:absolute;left:4%;right:4%;bottom:3%;height:17%;border-radius:1em;background:#101832d9;overflow:hidden;font-style:normal}
.bag-bar u{position:absolute;inset:0 auto 0 0;background:linear-gradient(#b8ff8a,#4fc24c)}
.bag-bar span{position:absolute;inset:0;display:grid;place-items:center;font:700 2cqw/1 Arial,sans-serif;color:#fff;text-shadow:0 1px 1px #000}
.bag-empty{aspect-ratio:1;border-radius:5%;background:#1b2f4d8c;border:1px solid #ffffff17;box-sizing:border-box}
#stage #main .satchel :is(.satchel-stack,.equipment-cell)[aria-pressed=true]{outline:3px solid #ffe27a;outline-offset:-1px;box-shadow:0 0 0 2px #2b1c08,0 0 10px #ffd95a}
#stage #main .satchel-foot button:disabled{filter:grayscale(.8);opacity:.6}
.vault{grid-template-rows:5.6% minmax(0,1fr) 8% 4.5% minmax(0,1fr) 7% 8%}
.vault-hint{display:flex;align-items:center;gap:2%;padding:0 1.5%;background:#264563b3;border:1px solid #7392a4;border-top:0;font-size:2.8cqw}
.vault-hint span{margin-right:auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#stage #main .vault-hint button{background:#d7b270;color:#352c31;border-radius:8px;padding:.42em .7em;white-space:nowrap}
.maw-room{grid-template-rows:5.6% 34% minmax(0,1fr) 7% 8%}
.maw-stage{position:relative;display:grid;grid-template-columns:42% minmax(0,1fr);align-items:center;gap:2%;padding:0 3%;min-height:0;background:radial-gradient(ellipse at 24% 55%,#a56bff55,transparent 55%)}
.maw-pic{width:100%;height:100%;max-height:30cqh;object-fit:contain;filter:drop-shadow(0 6px 8px #0008);animation:maw-idle 3.2s ease-in-out infinite}
.maw-pic.chomp{animation:maw-chomp .7s ease-out}
@keyframes maw-idle{50%{transform:translateY(-2.5%) scale(1.02)}}
@keyframes maw-chomp{0%{transform:scale(1)}25%{transform:scale(1.14,.86)}55%{transform:scale(.93,1.1)}100%{transform:scale(1)}}
.maw-info{display:grid;gap:1.4cqh;min-width:0}
.maw-info h2{margin:0;font:700 4.4cqw/1.1 Arial,sans-serif;color:#fff2cf}.maw-info h2 b{display:block;color:#ffd86b;font-size:1.15em}
.maw-bar{position:relative;height:3.4cqh;border-radius:2em;background:#101832d9;border:1px solid #8fa6d8;overflow:hidden}
.maw-bar i,.maw-bar u{position:absolute;inset:0 auto 0 0}.maw-bar u{background:#fff3a6aa}.maw-bar i{background:linear-gradient(#d9a5ff,#8b4be0);z-index:1}
.maw-bar span{position:absolute;inset:0;z-index:2;display:grid;place-items:center;font:700 2.6cqw/1 Arial,sans-serif;color:#fff;text-shadow:0 1px 1px #000}
.maw-stats{display:grid;gap:.6cqh;font:700 2.9cqw/1.2 Arial,sans-serif}.maw-stats span{display:flex;align-items:center;gap:.4em}.maw-stats b{color:#fff}.maw-stats em{font-style:normal;color:#9dff8a}
#stage #main .satchel .maw-help{position:absolute;top:4%;right:3%;width:7cqw;height:7cqw;border-radius:50%;background:#ffffff26;border:1px solid #ffffff66;font:700 4cqw/1 Arial,sans-serif;color:#fff}
.maw-none{margin:8% 6%;text-align:center;font:400 3.2cqw/1.4 Arial,sans-serif;color:#d7e4ff}
.satchel-nav button[aria-current] img{filter:drop-shadow(0 0 4px #ffd86b)}
/* Item card and the "You received" list in the pop-up */
.den-item-head.bag-head{background:linear-gradient(135deg,color-mix(in srgb,var(--rarity) 85%,#fff),color-mix(in srgb,var(--rarity) 70%,#1c2244))}
.den-item-head :is(.bag-ico,.equipment-art,img,.gpt-icon){width:64px;height:64px;object-fit:contain;filter:drop-shadow(0 2px 2px #0006)}
.den-item-head .bag-ico{aspect-ratio:auto}
#stage #modal.den-pop .den-item .den-actions{gap:10px}
.bag-gains{display:grid;grid-template-columns:repeat(auto-fill,minmax(84px,1fr));gap:8px;margin:8px 2px 12px}
.bag-gain{position:relative;display:grid;justify-items:center;gap:2px;padding:6px 4px;border-radius:10px;border:2px solid var(--rarity);background:linear-gradient(160deg,color-mix(in srgb,var(--rarity) 45%,#1c2244),#1c2244)}
.bag-gain :is(.bag-ico,.den-ico,.equipment-art,img,.gpt-icon){width:52px;height:52px;object-fit:contain;aspect-ratio:auto}
.satchel .den-x{display:none}
#stage #modal .bag-gain :is(img,.gear-illustration){width:52px;height:52px}
.bag-gain{align-content:start}
.bag-gain b{font:700 14px/1 Arial,sans-serif;color:#fff}.bag-gain small{font:400 11px/1.15 Arial,sans-serif!important;color:#dfe8ff;text-align:center}
/* Gear Crafting: the three families (Equipment, Necklace & Amulet, Rings) are a clear tab bar above the bottom bar */
#stage #main .loom .loom-kinds{gap:0;align-items:stretch;background:#1d3550;border-top:2px solid #6f93ad}
#stage #main .loom .loom-kinds button{flex:1 1 0;width:auto;height:100%;border:0;border-right:1px solid #ffffff22;border-radius:0;background:transparent;color:#a9c6d8;font:700 3.1cqw/1.1 Arial,sans-serif}
#stage #main .loom .loom-kinds button[aria-pressed=true]{background:linear-gradient(#3f86b8,#2a5f8a);color:#fff;box-shadow:inset 0 3px 0 #9fe3ff}

/* Quality ladder (gearRanks, 2026-11-21): the frame and the plate of a piece follow --rarity; the finest shimmer. */
#stage #main .satchel .equipment-cell,.loom-face,.boss-drop-row .equipment-cell,#stage #modal.den-pop .loom-pick .equipment-cell{background:linear-gradient(160deg,color-mix(in srgb,var(--rarity) 60%,#1c2244),color-mix(in srgb,var(--rarity) 24%,#1c2244))}
#stage #main .satchel .equipment-cell.q-relic5,.loom-face.q-relic5{background:linear-gradient(160deg,#ff8fc4,#b3246f);border-color:#ffe08a}
#stage #main .satchel .equipment-cell:is(.q-rainbow,.q-god),.loom-face:is(.q-rainbow,.q-god),#stage #modal .equipment-cell:is(.q-rainbow,.q-god){background:linear-gradient(135deg,#ff8ad1,#9b8cff 34%,#6fd8ff 66%,#9dffb4);border-color:#fff}
#stage #main .satchel .equipment-cell.q-god,.loom-face.q-god{border-color:#ffe27a;box-shadow:0 0 8px #ffe27a}
/* Gear Crafting work area */
.loom .loom-work{position:relative;padding:1cqh 1cqw 2cqh}
#stage #main .satchel.loom .maw-help{top:1%;right:1%}
.loom-face{position:relative;display:grid;place-items:center;aspect-ratio:1;width:100%;border:3px solid var(--rarity);border-radius:7%;box-sizing:border-box;overflow:hidden}
.loom-face img{width:88%;height:88%;object-fit:contain}
.loom-face b{position:absolute;top:0;right:0;padding:0 .25em;background:#101832c9;border-radius:0 0 0 .4em;font:700 2.3cqw/1.3 Arial,sans-serif;color:#fff}
.loom-face small{position:absolute;left:2%;top:2%;width:1em;font:700 2.1cqw/.95 Arial,sans-serif!important;color:#ffe45c;text-shadow:0 1px 1px #000;word-break:break-all;text-align:center}
.loom .loom-orbit{width:min(60%,19cqh)}
.loom .loom-orbit .loom-face{width:54%}
.loom .loom-orbit .loom-face b{font-size:2.8cqw}.loom .loom-orbit .loom-face small{font-size:2.6cqw!important}
.loom .loom-work h2{margin:.5em 0 .2em;font-size:3.9cqw}
.loom-rate{display:block;font:700 3.5cqw/1.3 Arial,sans-serif;color:#fff}.loom-rate.low{color:#ff8089}
.loom-row{display:flex;justify-content:center;gap:1.4cqw;margin:1.6cqh 0 0}
#stage #main .loom .loom-row>*{width:15.5%;flex:none}
#stage #main .loom .loom-plus{aspect-ratio:1;border:2px dashed #7fa6c4;border-radius:7%;background:#1d3550b3;color:#cfe6f5;font:700 5cqw/1 Arial,sans-serif}
#stage #main .satchel .bag-tile b.low,.loom-slot em.low{color:#ff8089}
.loom .loom-work p{margin:.9cqh 0 0;font:600 2.7cqw/1.35 Arial,sans-serif}
.loom .loom-buttons{margin:1.6cqh 0}
#stage #main .loom-buttons button{flex:1 1 0;width:auto;max-width:34%;font:700 3cqw/1 Arial,sans-serif;border-radius:2em;padding:.75em .2em}
.loom-slots{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1.4cqw 1.6cqw}
#stage #main .loom .loom-slot{display:grid;gap:.3cqh;padding:0 0 .2cqh;border-radius:7%}
#stage #main .loom .loom-slot[aria-pressed=true]{outline:3px solid #ffe27a;outline-offset:1px;background:#ffe27a2e}
.loom-slot em{font:700 2.9cqw/1 Arial,sans-serif;font-style:normal;color:#8dff9a}
#stage #main .loom-body aside button{font:700 2.75cqw/1.15 Arial,sans-serif;padding:.7em .2em}
#stage #modal.den-pop .loom-pick{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin:8px 0}
#stage #modal.den-pop .loom-pick .equipment-cell{position:relative;width:100%;height:auto;min-height:0;aspect-ratio:1;padding:0;border:3px solid var(--rarity);border-radius:7%;display:grid;place-items:center;overflow:hidden}
#stage #modal.den-pop .loom-pick .gear-illustration{width:86%;height:86%;object-fit:contain}
#stage #modal.den-pop .loom-pick :is(.gear-tier,.gear-stars,.gear-enhance,.gear-gems){font-size:10px}
#stage #modal.den-pop .loom-ladder p{margin:0;text-align:left;font-size:13px}
/* Guardian drops in the victory window */
.boss-drop-row{display:flex;justify-content:center;gap:10px;margin:6px 0 10px}
#stage #modal .boss-drop-row .equipment-cell{position:relative;width:76px;height:76px;min-height:0;padding:0;border:3px solid var(--rarity);border-radius:8px;display:grid;place-items:center;overflow:hidden}
#stage #modal .boss-drop-row .gear-illustration{width:86%;height:86%;object-fit:contain}
/* Auto devour switch */
#stage #main .satchel .maw-auto{display:flex;align-items:center;gap:.5em;justify-self:start;font:700 2.9cqw/1 Arial,sans-serif;color:#fff2cf}
.maw-auto i{width:1.25em;height:1.25em;border:2px solid #cfe0ff;border-radius:.25em;background:#101832b3;box-sizing:border-box}
.maw-auto[aria-pressed=true] i{background:#6fe07f;border-color:#eaffea;box-shadow:inset 0 0 0 2px #17401f}
#stage #main .loom .loom-row>*{width:17.5%}
.loom .loom-row .gear-tier{display:none}
#stage #main .satchel .maw-auto::before{display:none}
/* Guardian drop list (dungeon lobby -> Rare drops) */
#stage #main .lobby-rewards .lobby-rare{position:static;width:100%;min-width:0;min-height:0;margin:.3rem 0 0;padding:.3rem .1rem;border:1px solid #ffd98a;border-radius:.5rem;background:linear-gradient(#7a4fd0,#4b2c94);color:#fff;font:700 clamp(.62rem,2.3cqw,.8rem)/1.1 Arial,sans-serif}
#stage #main .lobby-rewards .lobby-rare::before,#stage #main .lobby-rewards .lobby-rare::after{display:none}
.loot-list{display:grid;gap:6px;margin:8px 0 4px}
.loot-row{display:grid;grid-template-columns:44px minmax(0,1fr) auto;align-items:center;gap:10px;padding:4px 10px 4px 4px;border-radius:10px;background:#ffffff14;text-align:left}
.loot-row span{display:grid;place-items:center;width:44px;height:44px;border:2px solid var(--rarity);border-radius:8px;background:linear-gradient(160deg,color-mix(in srgb,var(--rarity) 60%,#1c2244),color-mix(in srgb,var(--rarity) 24%,#1c2244));overflow:hidden}
#stage #modal .loot-row span :is(img,.bag-ico){width:38px;height:38px;object-fit:contain;aspect-ratio:auto}
.loot-row b{font:700 14px/1.2 Arial,sans-serif;color:#fff}.loot-row em{font:700 13px/1 Arial,sans-serif;font-style:normal;color:#ffe08a}
.boss-rare{color:#ffe08a;font-weight:700}

/* Summon room (citySummon, 2026-11-21): Basic and Advanced wells, Mark Shop, Summon Festival. Root .satchel.well */
body:is([data-screen=citySummon],[data-screen=cityContest],[data-screen=citySocial],[data-screen=cityGuild],[data-screen=citySupreme]) #stage{width:min(100%,55dvh);margin-inline:auto}
body:is([data-screen=citySummon],[data-screen=cityContest],[data-screen=citySocial],[data-screen=cityGuild],[data-screen=citySupreme],[data-screen=cascade]) #stage>:is(header,nav,footer){display:none!important}
body:is([data-screen=citySummon],[data-screen=cityContest],[data-screen=citySocial],[data-screen=cityGuild],[data-screen=citySupreme],[data-screen=cascade]) #stage>#main{inset:0!important;width:100%;height:100%;padding:0!important;display:block;overflow:auto}
.satchel.well{grid-template-rows:5.6% minmax(0,1fr) auto auto 8%;background-size:cover;background-position:50% 0;background-color:#27407a}
.sum-ico{display:inline-block;width:1.5em;aspect-ratio:1;background:var(--sum-icons) no-repeat;background-size:300% 200%;font-style:normal;flex:none;vertical-align:middle}
.well .satchel-top span :is(.sum-ico,.bag-ico,.gpt-icon){width:1.45em;height:1.45em;aspect-ratio:auto}
.well .satchel-top>span{background:#141a3ad9}
.well-stage{position:relative;min-height:0;text-align:center}
#stage #main .satchel.well .maw-help{top:1.5%;left:2%;right:auto}
.well-title{margin:1.6cqh 0 0;font:900 8cqw/1 Georgia,serif;font-style:italic;color:#ffe9a0;text-shadow:0 2px 0 #b3421c,0 0 12px #ff8a2a,0 3px 6px #0008;letter-spacing:.01em}
.well-ribbon{display:inline-block;margin:1.2cqh 0 0;padding:.45em 2.2em;background:linear-gradient(#e2613a,#b9391f);color:#fff3d6;font:700 3.1cqw/1.1 Arial,sans-serif;clip-path:polygon(0 0,100% 0,96% 50%,100% 100%,0 100%,4% 50%)}
.well-ribbon b{color:#ffe27a;font-size:1.15em}
.well-crowd{position:absolute;inset:22% 0 0}
.well-crowd img{position:absolute;object-fit:contain;filter:drop-shadow(0 .8cqh .6cqh #0007)}
.crowd-0{left:22%;top:2%;width:56%;z-index:2;animation:maw-idle 3.4s ease-in-out infinite}
.crowd-1{left:1%;top:16%;width:30%}.crowd-2{right:1%;top:20%;width:30%}
.crowd-3{left:6%;bottom:2%;width:30%;z-index:3}.crowd-4{right:5%;bottom:0;width:32%;z-index:3}.crowd-5{left:35%;bottom:-2%;width:28%;z-index:4}
.well-draw{display:grid;grid-template-columns:1fr 1fr;justify-items:center;gap:.6cqh 4cqw;padding:1cqh 6cqw 0}
#stage #main .well-draw>button:not(.well-skip){width:100%;display:grid;gap:.25em;padding:.55em .4em;border-radius:1.4em;font:700 3.9cqw/1 Arial,sans-serif;color:#1f4a86;background:linear-gradient(#e2f6ff,#9fd4f5 60%,#6fb2e6);border:2px solid #f4fbff;box-shadow:0 .4cqh .8cqh #0007}
#stage #main .well-draw>.well-draw-10{color:#6a3c08;background:linear-gradient(#fff0a8,#f6c24c 60%,#e39a25);border-color:#fff6cf}
#stage #main .well-draw>button:disabled{filter:grayscale(.75) brightness(.85)}
.well-draw small{display:flex;align-items:center;justify-content:center;gap:.2em;font:700 2.8cqw/1 Arial,sans-serif!important;color:inherit!important}
.well-draw small :is(.sum-ico,.bag-ico,.gpt-icon){width:1.5em;height:1.5em;aspect-ratio:auto}
#stage #main .well-draw .well-skip{grid-column:2;display:flex;align-items:center;gap:.4em;font:700 3cqw/1 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000}
.well-skip i{width:1.2em;height:1.2em;border:2px solid #fff;border-radius:.25em;background:#101832b3;box-sizing:border-box}
.well-skip[aria-pressed=true] i{background:#6fe07f;box-shadow:inset 0 0 0 2px #17401f}
.well-banners{display:grid;grid-template-columns:1fr 1fr;gap:5cqw;padding:.8cqh 9cqw 1.4cqh}
#stage #main .well-banners button{padding:.7em .8em;text-align:left;font:700 3.9cqw/1.15 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000a;border:2px solid transparent;border-radius:.4em}
#stage #main .well-banners .ban-adv{background:linear-gradient(120deg,#e0672f,#a3331c)}#stage #main .well-banners .ban-basic{background:linear-gradient(120deg,#4a82d8,#274b9c)}
#stage #main .well-banners button[aria-pressed=true]{border-color:#ffe27a;box-shadow:0 0 10px #ffd95a}
.satchel-nav.well-nav{background:linear-gradient(#a8572a,#7a3a1a)}
#stage #main .well-nav button:not([data-back]){display:grid;justify-items:center;gap:.15em;width:21%;font:700 2.7cqw/1.05 Arial,sans-serif!important;color:#f3d9b8}
.well-nav .sum-ico{width:6.4cqw}
#stage #main .well-nav button[aria-current]{color:#ffe27a!important;background:#ffffff1f;border-radius:.6em .6em 0 0}
/* Advanced */
.well-advanced .well-title{margin-top:1cqh}
#stage #main .satchel .well-shop{position:absolute;top:17%;right:2%;display:grid;justify-items:center;gap:.1em;font:700 2.7cqw/1.05 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000,0 0 4px #000}
.well-shop .sum-ico{width:9cqw;filter:drop-shadow(0 2px 3px #0008)}
.well-orbs{position:absolute;inset:0;pointer-events:none}
#stage #main .well-draw>button b{color:inherit}
#stage #main .satchel.well .maw-help{z-index:6}
.well-orbs span{position:absolute;width:21%;aspect-ratio:1;border-radius:50%;overflow:hidden;border:.7cqw solid #fff4c9;background:radial-gradient(#fff8dc,#f1b25a);box-shadow:0 0 3cqw #ffe9a0,inset 0 0 2cqw #fff}
.well-orbs img{width:100%;height:100%;object-fit:cover;object-position:50% 18%}
.orb-0{left:39.5%;top:50%;width:25%!important}.orb-1{left:9%;top:43%}.orb-2{right:9%;top:43%}
.well-level{position:absolute;left:5%;right:5%;bottom:0;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:.4cqh 2cqw;padding:1cqh 3cqw;border-radius:.8em;background:#141a3ad1;color:#fff;font:700 3cqw/1.2 Arial,sans-serif}
.well-level>span b{color:#ffe27a;font-size:1.2em}
.well-level>i{position:relative;height:2.4cqh;border-radius:2em;background:#0c1228;border:1px solid #8fa6d8;overflow:hidden}
.well-level>i u{position:absolute;inset:0 auto 0 0;background:linear-gradient(#a6f08a,#3fb64a)}
.well-level>i em{position:absolute;inset:0;display:grid;place-items:center;font:700 2.4cqw/1 Arial,sans-serif;font-style:normal;text-shadow:0 1px 1px #000}
.well-card{position:relative;display:grid;place-items:center;width:9cqw}.well-card .sum-ico{width:100%}
.well-card b{position:absolute;font:900 3.8cqw/1 Arial,sans-serif;color:#7a3c08!important;text-shadow:0 1px 0 #fff8}
.well-level p{grid-column:1/-1;margin:0;font:700 3.1cqw/1.2 Arial,sans-serif;text-align:center}
.well-level .hot{color:#ff7a9a}.well-level .warm{color:#d9b3ff}
/* Mark Shop */
.satchel.well-mart{grid-template-rows:5.6% 24% minmax(0,1fr) auto 8%;background:linear-gradient(#3b2a6b,#6a4526 30%,#7d5230)}
.mart-banner{position:relative;display:grid;align-content:start;justify-items:center;gap:.5cqh;padding-top:1cqh;background-size:cover;background-position:50% 62%;text-align:center}
.mart-banner h2{margin:0;font:900 7cqw/1 Georgia,serif;font-style:italic;color:#fff3d6;text-shadow:0 2px 0 #b3421c,0 0 10px #ff8a2a,0 3px 6px #000a}
.mart-banner p{margin:0;padding:.35em 1.6em;background:#b9391fe6;color:#fff3d6;font:700 2.9cqw/1.15 Arial,sans-serif;clip-path:polygon(0 0,100% 0,97% 50%,100% 100%,0 100%,3% 50%)}
.mart-banner em{position:absolute;right:3%;bottom:6%;padding:.35em .8em;border-radius:.4em;background:#f6e3b0;color:#5a3a12;font:700 2.5cqw/1.1 Arial,sans-serif;font-style:normal}
.well-mart .satchel-scroll{background:#5b3a1cd9;border-color:#c79a5a}
.mart-note{margin:0 0 1cqh;font:700 2.7cqw/1.25 Arial,sans-serif;color:#fff3d6}.mart-note b{color:#9dff8a}
.mart-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.6cqw}
#stage #main .satchel .shop-card{display:grid;justify-items:center;gap:.3cqh;padding:.8cqh .6cqw 0;border-radius:.5em;background:#fbf3e3;border:2px solid var(--edge,#c79a5a);color:#5a3a12;overflow:hidden}
.shop-card small{font:700 2.6cqw/1 Arial,sans-serif!important;color:#3b7a3b!important}
.shop-card img{width:62%;aspect-ratio:1;object-fit:cover;object-position:50% 18%;border-radius:.4em;border:2px solid var(--edge);background:var(--bg)}
.shop-card b{font:700 2.6cqw/1.1 Arial,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.shop-card em{font:400 2.3cqw/1.1 Arial,sans-serif;font-style:normal;color:#7a5a3a}
.shop-card.shut em{color:#b0382c;font-weight:700}
.shop-card>span{display:flex;align-items:center;justify-content:center;gap:.25em;width:calc(100% + 1.2cqw);margin-top:.3cqh;padding:.25em 0;background:linear-gradient(#f6cf6a,#e2a738);font:700 3.4cqw/1 Arial,sans-serif;color:#5a3a12}
.shop-card.shut>span{filter:grayscale(.6)}
.mart-filters{display:flex;justify-content:center;gap:2.5cqw;padding:1cqh 2cqw}
#stage #main .mart-filters button{flex:1 1 0;padding:.55em 0;font:700 3.1cqw/1 Arial,sans-serif;color:#fff3d6;background:linear-gradient(#e0672f,#b1421f);clip-path:polygon(8% 0,92% 0,100% 50%,92% 100%,8% 100%,0 50%)}
#stage #main .mart-filters button[aria-pressed=true]{background:linear-gradient(#ffe89a,#f0b548);color:#5a3a12}
/* Summon Festival */
.satchel.well-gala{grid-template-rows:5.6% 23% auto minmax(0,1fr) auto 8%}
.gala-head{position:relative;min-height:0;text-align:center;overflow:hidden}
.gala-head>em{position:absolute;left:2%;top:4%;padding:.3em .8em;border-radius:2em;background:#141a3ad9;color:#8dff9a;font:700 2.6cqw/1 Arial,sans-serif;font-style:normal;z-index:5}
.gala-head h2{position:relative;z-index:5;margin:.6cqh 0 0;font:900 6.6cqw/1 Georgia,serif;font-style:italic;color:#ffe9a0;text-shadow:0 2px 0 #b3421c,0 0 12px #ff8a2a,0 3px 6px #000a}
.gala-head p{position:relative;z-index:5;margin:.3cqh 0 0;font:700 3cqw/1.1 Arial,sans-serif;color:#fff;text-shadow:0 1px 3px #000,0 0 6px #000}.gala-head p b{color:#ff9db5}
.gala-head .well-crowd{inset:30% 0 -30%}
.gala-0{left:2%;width:27%;top:6%}.gala-1{left:25%;width:27%;top:0;z-index:2}.gala-2{left:48%;width:27%;top:4%;z-index:2}.gala-3{right:1%;width:27%;top:8%}
.gala-track{display:flex;align-items:end;gap:1.5cqw;padding:1cqh 2cqw;background:linear-gradient(#d2553a,#a8321f);border-block:2px solid #f6c98a}
.gala-tokens{display:grid;justify-items:center;width:15%;flex:none}.gala-tokens .sum-ico{width:10cqw}
.gala-tokens b{margin-top:-.4em;padding:.15em .7em;border-radius:1em;background:#fff3d6;color:#7a3c08;font:700 3.2cqw/1 Arial,sans-serif}
#stage #main .satchel .mile{flex:1 1 0;display:grid;justify-items:center;gap:.3cqh}
.mile span{position:relative;display:grid;place-items:center;width:10.5cqw;aspect-ratio:1;border-radius:.4em;border:2px solid #f6c98a;background:#5a1d14;overflow:hidden}
.mile span :is(img,.bag-ico){width:100%;height:100%;object-fit:cover;object-position:50% 18%;aspect-ratio:auto}
.mile small{position:absolute;inset:auto 0 0;padding:.1em 0;background:#141a3ad9;font:700 1.9cqw/1 Arial,sans-serif!important;color:#fff!important;text-align:center}
.mile b{padding:.12em .6em;border-radius:1em;background:#7a2417;font:700 2.6cqw/1 Arial,sans-serif;color:#ffe7b0}
.mile.ready span{border-color:#fff;box-shadow:0 0 10px #ffe27a;animation:maw-idle 1.2s ease-in-out infinite}.mile.ready b{background:#ffe27a;color:#5a3a12}
.mile.got span{filter:grayscale(.8) brightness(.7)}.mile.got b::after{content:" ✓"}
.well-gala .gala-list{display:grid;align-content:start;gap:1cqh;background:#6a4526d9;border-color:#c79a5a}
.gala-row{border-radius:.5em;overflow:hidden;background:#fbf3e3}
.gala-row h3{margin:0;padding:.45em .8em;background:linear-gradient(#b98a52,#96693a);font:700 3cqw/1.1 Arial,sans-serif;color:#fff}
.gala-row h3 .ok{color:#a8ff9a}.gala-row h3 .low{color:#ffb0a0}
.gala-row>div{display:flex;align-items:center;gap:2cqw;padding:.8cqh 3cqw}
.gala-prize{position:relative;display:grid;place-items:center;width:10cqw;aspect-ratio:1;border-radius:.4em;border:2px solid #b35a3a;background:linear-gradient(#7a2a3a,#3b1a3a)}
.gala-prize .sum-ico{width:84%}.gala-prize b{position:absolute;right:6%;bottom:2%;font:700 2.6cqw/1 Arial,sans-serif;color:#fff;text-shadow:0 1px 0 #000,0 0 3px #000}
#stage #main .gala-row button{margin-left:auto;padding:.55em 1.5em;border-radius:1.4em;font:700 3.3cqw/1 Arial,sans-serif}
#stage #main .gala-row .gala-claim{background:linear-gradient(#fff0a8,#f0b548);color:#6a3c08;border:2px solid #fff6cf}
#stage #main .gala-row .gala-go{background:linear-gradient(#e2f6ff,#8cc6f0);color:#1f4a86;border:2px solid #f4fbff}
.gala-row em{margin-left:auto;padding:.4em 1em;border-radius:.4em;background:#58b96a;color:#fff;font:700 3cqw/1 Arial,sans-serif;font-style:normal;transform:rotate(-6deg)}
.gala-row.done{filter:brightness(.72)}
.gala-foot{margin:0;padding:.6cqh 2cqw;text-align:center;font:700 2.5cqw/1.2 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000}
/* Result cards turn up one after another */
.sum-card{display:block}.sum-reveal .sum-card{opacity:0;animation:sum-in .35s ease-out forwards}
@keyframes sum-in{from{opacity:0;transform:scale(.4) rotate(-12deg)}to{opacity:1;transform:none}}
#stage #modal.den-pop .sum-odds{display:flex;justify-content:center;gap:8px;margin:8px 0}
.well-gala .gala-list{grid-auto-rows:max-content}
#stage #main .satchel.well :is(.mile,.shop-card,.well-shop,.well-skip)::before{display:none}
#stage #main .satchel .shop-card b{color:#5a3a12}
#stage #modal.den-pop .den-congrats p{margin:0;font:700 13px/1.35 Arial,sans-serif;color:#ffe9a0}

/* Sky Contest: mode list in Gameplay, Totem War lobby and fight (cityContest, 2026-11-21) */
.war-ico{display:inline-block;width:1.5em;aspect-ratio:1;background:var(--war-icons) no-repeat;background-size:400% 200%;font-style:normal;flex:none;vertical-align:middle}
.satchel-top>span .war-ico{width:1.45em}
.sky-list{display:grid;gap:1.2cqh;flex:1;grid-auto-rows:minmax(0,1fr)}
#stage #main .gp-room .sky-mode{position:relative;display:grid;align-content:center;justify-items:start;gap:.3em;padding:0 44% 0 5%;min-height:0;text-align:left;border:2px solid #ffffff55;border-radius:.6em;overflow:hidden;background:linear-gradient(100deg,var(--tone),color-mix(in srgb,var(--tone) 55%,#fff) 70%,color-mix(in srgb,var(--tone) 35%,#fff));color:#fff}
.sky-mode b{font:900 5cqw/1 Georgia,serif;font-style:italic;color:#fff6c9;text-shadow:0 2px 0 #0006,0 0 8px #0006}
.sky-mode small{font:700 2.8cqw/1.1 Arial,sans-serif!important;color:#fff!important;text-shadow:0 1px 2px #0008}
.sky-mode em{font:700 2.5cqw/1.1 Arial,sans-serif;font-style:normal;color:#d8ffcf;text-shadow:0 1px 2px #000a}
.sky-mode img{position:absolute;right:-2%;top:-12%;height:130%;width:46%;object-fit:contain;object-position:50% 0;filter:drop-shadow(0 2px 4px #0008)}
#stage #main .gp-room .sky-mode::before{display:none}
.sky-mode.soon{filter:saturate(.55)}.sky-mode.soon em{color:#ffe7b0}
.satchel.tw{grid-template-rows:5.6% minmax(0,1fr) auto auto auto 8%;background-size:cover;background-position:50% 0;background-color:#232a66}
.tw-stage{position:relative;min-height:0}
.tw-when{margin:1cqh 0 0;text-align:center;font:700 2.9cqw/1.2 Arial,sans-serif;color:#fff;text-shadow:0 1px 3px #000,0 0 6px #000}.tw-when b{color:#8dff9a}
#stage #main .satchel.tw .maw-help{top:auto;bottom:3%;left:3%;right:auto}
#stage #main .satchel .tw-side{position:absolute;right:2%;bottom:3%;display:grid;justify-items:center;font:700 2.6cqw/1.05 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000,0 0 4px #000}
.tw-side .war-ico{width:9cqw;filter:drop-shadow(0 2px 3px #0008)}
.tw-best{position:absolute;left:14%;right:22%;bottom:3%;margin:0;text-align:center;font:700 2.7cqw/1.2 Arial,sans-serif;color:#fff;text-shadow:0 1px 3px #000,0 0 6px #000}.tw-best b{color:#ffe27a}
.tw-preview{margin:0 4%;padding:.6cqh 0 1cqh;border:1px solid #6f93d8;border-radius:.4em;background:#141a3ad9;text-align:center}
.tw-preview h3{margin:0 0 .6cqh;font:700 3.2cqw/1.2 Arial,sans-serif;color:#fff}
.tw-preview div{display:flex;justify-content:center;gap:2.5cqw}
.tw-preview :is(.war-ico,.bag-ico){width:11cqw;aspect-ratio:1;padding:.6cqw;border:2px solid #b784ff;border-radius:.4em;background-color:#2a2f6a;background-origin:content-box;box-sizing:border-box}
.tw-sides{display:flex;justify-content:center;gap:3cqw;padding:1.2cqh 4% 0}
#stage #main .tw-sides button{flex:1 1 0;display:flex;align-items:center;justify-content:center;gap:.4em;padding:.4em 0;border-radius:2em;border:2px solid transparent;background:#141a3ad9;font:700 3.2cqw/1 Arial,sans-serif;color:#fff}
#stage #main .tw-sides button[aria-pressed=true]{border-color:var(--tone);box-shadow:0 0 10px var(--tone);background:color-mix(in srgb,var(--tone) 35%,#141a3a)}
.tw-sides .war-ico{width:2em}
.tw-enter{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:6cqw;padding:1.2cqh 8% 1.4cqh}
#stage #main .satchel .tw-shop{display:grid;justify-items:center;font:700 2.6cqw/1.05 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000}
.tw-shop .war-ico{width:8.5cqw}
#stage #main .tw-enter .den-gold{justify-self:center;display:grid;padding:.55em 3em;border:0;background:linear-gradient(#ffe89a,#f0b548 60%,#d9942e);color:#5a3a12;font:700 4.6cqw/1 Arial,sans-serif;clip-path:polygon(7% 0,93% 0,100% 50%,93% 100%,7% 100%,0 50%)}
.tw-enter .den-gold small{font:700 .55em/1.2 Arial,sans-serif!important;color:#7a4a12!important}
/* the fight */
.satchel.tw-fight{grid-template-rows:auto minmax(0,1fr) auto 8%;padding:0;background:#1b2550}
.tw-top{display:flex;align-items:center;gap:2cqw;padding:.8cqh 2cqw;background:#141a3a}
.tw-score{display:flex;align-items:center;gap:.3em;padding:.15em .7em .15em .2em;border-radius:2em;background:color-mix(in srgb,var(--tone) 30%,#141a3a);border:2px solid transparent;font:700 3.6cqw/1 Arial,sans-serif;color:#fff}
.tw-score.mine{border-color:var(--tone)}.tw-score .war-ico{width:1.7em}
.tw-clock{margin-left:auto;display:grid;justify-items:end}.tw-clock b{font:900 4.4cqw/1 Arial,sans-serif;color:#fff}.tw-clock small{font:700 2.4cqw/1.1 Arial,sans-serif!important;color:#8dff9a!important}
.tw-field{position:relative;min-height:0;background-size:100% 100%;overflow:hidden}
#stage #main .satchel .tw-totem{position:absolute;width:19%;aspect-ratio:1;transform:translate(-50%,-78%);display:grid;place-items:center;border-radius:50%;z-index:2}
.tw-totem .war-ico{width:100%;filter:drop-shadow(0 0 5px var(--tone)) drop-shadow(0 3px 3px #0008)}
.tw-hp{position:absolute;left:14%;right:14%;bottom:-6%;height:7%;min-height:4px;border-radius:1em;background:#101832d9;overflow:hidden}
.tw-hp::after{content:"";position:absolute;inset:0 auto 0 0;width:var(--hp,100%);background:var(--tone,#6fe07f)}
.tw-ring{display:none;position:absolute;left:4%;right:4%;bottom:-14%;height:30%;border:3px solid #fff;border-radius:50%;box-shadow:0 0 8px #fff,inset 0 0 6px #fff;animation:tw-pulse 1s ease-in-out infinite}
.tw-totem.aim .tw-ring{display:block}
@keyframes tw-pulse{50%{opacity:.45}}
#stage #main .satchel .tw-totem::before,#stage #main .satchel .tw-totem::after{display:none}
.tw-f{position:absolute;width:8.5%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;border:2px solid var(--tone);background:#141a3a;box-shadow:0 2px 4px #0008;transition:left .5s linear,top .5s linear,opacity .3s;z-index:3}
.tw-f .portrait-badge{position:absolute;inset:0;width:100%;height:100%;border-radius:50%;filter:none}
.tw-f.tw-me{width:11.5%;border-width:3px;border-color:#fff;box-shadow:0 0 0 2px var(--tone),0 0 10px var(--tone);z-index:5}
.tw-f b{position:absolute;left:50%;top:-58%;transform:translateX(-50%);padding:.1em .5em;border-radius:1em;background:#141a3ad9;font:700 2.4cqw/1.1 Arial,sans-serif;color:#fff;white-space:nowrap}
.tw-f .tw-hp{left:0;right:0;bottom:-22%;height:14%}
.tw-f.down{opacity:.18}
