/* Pathfinding between two defenders: Reina rides across the hall */
.cloud-path{position:absolute;inset:0;z-index:2;display:grid;place-items:end center;padding-bottom:6%;border-radius:12px;background:linear-gradient(#0d1a2c00 50%,#0d1a2c66);pointer-events:none}
