@keyframes cloud-ride{0%{left:-40%;transform:translateY(0)}25%{transform:translateY(-3%)}50%{transform:translateY(0)}75%{transform:translateY(-3%)}100%{left:100%;transform:translateY(0)}}
.cloud-path strong{position:absolute;top:14%;left:50%;transform:translateX(-50%);padding:.2em .8em;border-radius:1em;background:#302239dc;font:900 clamp(16px,4.4cqw,24px)/1.2 Arial,sans-serif;color:#ffb35a;text-shadow:0 2px 3px #000;white-space:nowrap}
