/* Chat sheet (2026-11-21, after the reference): channels in a column on the left, feed and input on the right.
   On the home screen it slides up over the lower part (.over); in the Social room it fills the Chat page (.in-room). */
.chat-sheet{display:grid;grid-template-columns:24% minmax(0,1fr);background:#262a42f2;color:#fff;border:2px solid #4a4f72;border-radius:1em 1em 0 0;overflow:hidden}
.chat-sheet.over{position:absolute;left:3%;right:3%;bottom:0;height:62%;z-index:40;box-shadow:0 -6px 24px #000a}
.chat-sheet.over.opening{animation:chat-up .25s ease-out}
@keyframes chat-up{from{transform:translateY(100%)}to{transform:none}}
.chat-sheet.in-room{min-height:0;margin:0 2%;grid-row:span 4;border-radius:1em}
.satchel.soc-p-chat{grid-template-rows:auto minmax(0,1fr) 8%}
#stage #main .chat-sheet button::before,#stage #main .chat-sheet button::after{display:none}
.chat-sheet .den-x{display:none}
#stage #main .chat-sheet .chat-fold{position:absolute;left:50%;top:0;transform:translate(-50%,-2%);z-index:2;width:16%;height:auto;padding:0 0 .2em;border-radius:0 0 .8em .8em;background:#1a1d33;border:1px solid #4a4f72;border-top:0;color:#ffcf5a;font:700 4.5cqw/1 Arial,sans-serif}
.chat-side{display:flex;flex-direction:column;gap:.4cqh;padding:3.5cqh 0 1cqh;background:#1a1d33;overflow:auto}
#stage #main .chat-side>button:not(.chat-tool){padding:1.1cqh 0;border-radius:0 .6em .6em 0;margin-right:6%;background:transparent;border:0;color:#cfd6ff;font:700 3.2cqw/1 Arial,sans-serif}
#stage #main .chat-side>button[aria-pressed=true]{background:linear-gradient(90deg,#3b8fd0,#2a6fb0);color:#fff}
.chat-side>span{flex:1}
#stage #main .chat-side .chat-tool{display:grid;justify-items:center;gap:.2em;padding:.4cqh 0;background:transparent;border:0;color:#fff;font:700 2.3cqw/1 Arial,sans-serif}
.chat-tool :is(.gpt-icon,.soc-ico){width:8cqw;height:8cqw}
.chat-main{display:grid;grid-template-rows:auto minmax(0,1fr) auto auto;min-height:0;padding:3cqh 2cqw 1cqh}
.chat-sheet .chat-feed{margin:0;border-radius:.6em;background:#2f3452;align-content:start}
.chat-note{padding:.4em .6em;border-radius:.4em;font:400 3cqw/1.35 Arial,sans-serif;color:#e9ecff}
.chat-note.sys{background:#3a3f63;color:#ffe9a0}
.chat-note.quiz{background:#3a5a3f;color:#b8ffb0;font-weight:700}
.chat-note.roll b{color:#7dff8a}.chat-note.roll i{font-style:normal;color:#ffcf5a;font-weight:700}.chat-note.roll u{text-decoration:none;color:#ffa94a;font-weight:700}
.chat-line .srv{color:#9fc8ff}.chat-line .fac{font-weight:700}
#stage #main .chat-sheet .chat-face{padding:0;background:transparent;border:0;border-radius:50%;flex:none}
.chat-sheet .chat-line .portrait-badge{width:9cqw;height:9cqw;border-radius:50%;filter:none}
.chat-block{display:flex;align-items:center;gap:2cqw;margin-bottom:1cqh;font:700 2.8cqw/1.2 Arial,sans-serif;color:#fff}
.chat-squad{display:flex;gap:1.5cqw;margin-bottom:1cqh;overflow-x:auto}
#stage #main .chat-squad button{display:grid;justify-items:center;gap:.2em;flex:none;width:15cqw;padding:.5cqh 0;border-radius:.5em;background:#33395c;border:2px solid #4a4f72;color:#ffe9a0;font:700 2.3cqw/1 Arial,sans-serif}
#stage #main .chat-squad button[aria-pressed=true]{border-color:#ffcf5a;background:#3f466e}
.chat-squad .portrait-badge{width:9cqw;height:9cqw;border-radius:50%;filter:none}.chat-squad .soc-ico{width:9cqw}
.chat-squad small{font:400 2cqw/1 Arial,sans-serif!important;color:#cfd6ff!important}
.chat-emoji{display:flex;flex-wrap:wrap;gap:1cqw;padding:.6cqh 0}
#stage #main .chat-emoji button{width:9cqw;height:9cqw;padding:0;border-radius:.4em;background:#3a3f63;border:0;font:400 5cqw/1 Arial,sans-serif}
.chat-sheet .chat-input{padding:1cqh 0 0;gap:1.5cqw}
.chat-sheet .chat-input input{background:#1a1d33;color:#fff;border-color:#4a4f72;font-size:2.9cqw}
.chat-sheet .chat-input input::placeholder{color:#9aa0c8}
#stage #main .chat-sheet .chat-smile{width:9cqw;padding:0;border-radius:50%;background:#3a3f63;border:0;color:#fff;font:400 5cqw/1 Arial,sans-serif}
#stage #main .chat-sheet .chat-input .den-gold{padding:.5em 1.2em;font-size:3cqw}
#stage #main .chat-sheet button:disabled{opacity:.5}
.chat-main{display:flex;flex-direction:column;gap:0}
.chat-sheet .chat-feed{flex:1 1 0;min-height:0}
.chat-sheet .chat-input{flex:none;align-items:center}
.chat-sheet .chat-input input{height:9cqw;box-sizing:border-box;padding:0 .8em}
#stage #main .chat-sheet .chat-smile{height:9cqw}
#stage #main .chat-sheet .chat-input .den-gold{height:9cqw;padding:0 1.2em}
#stage #main .chat-sheet .chat-line p{color:#3a2a1a}
#stage #main .chat-sheet .chat-line.me p{color:#1b2a40}
.chat-sheet .chat-block,.chat-sheet .chat-squad,.chat-sheet .chat-emoji{flex:none}
#stage #main .chat-sheet .soc-check{flex:none;width:6cqw;height:6cqw;padding:0;border-radius:.2em;border:2px solid #cfe0ff;background:#0d1a2c}
#stage #main .chat-sheet .soc-check[aria-pressed=true]{background:#5fbf6a;border-color:#eaffea;box-shadow:inset 0 0 0 2px #17401f}

/* Guild room (cityGuild, 2026-11-21) */
.gld-ico{display:inline-block;width:1.5em;aspect-ratio:1;background:var(--gld-icons) no-repeat;background-size:400% 200%;font-style:normal;flex:none;vertical-align:middle}
.satchel.gld{grid-template-rows:5.6% minmax(0,1fr) 8%;background-size:cover;background-position:50% 30%;background-color:#2a3a5a}
.satchel.gld.gld-tabbed,.satchel.gld-p-academy{grid-template-rows:5.6% minmax(0,1fr) auto 8%}
.satchel.gld-p-info.gld-t-info{background-position:50% 0}
#stage #main .satchel.gld button::before,#stage #main .satchel.gld button::after{display:none}
.gld .den-x{display:none}
.gld .satchel-top>span .gld-ico{width:1.45em}
.gld-head{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:3cqw;margin:1cqh 3%;padding:1.2cqh 3cqw;border-radius:.8em;background:#16233ee6;color:#fff}
.gld-head .gld-crest{width:16cqw}
.gld-head h2{margin:0;font:900 5.4cqw/1.1 Georgia,serif;font-style:italic;color:#ffe9a0}
.gld-head small{display:block;margin:.3cqh 0 .8cqh;font:700 2.8cqw/1.2 Arial,sans-serif!important;color:#cfe0ff!important}
.gld-bar{position:relative;display:block;height:3cqh;border-radius:2em;background:#0c1228;border:1px solid #8fa6d8;overflow:hidden}
.gld-bar u{position:absolute;inset:0 auto 0 0;background:linear-gradient(#a6f08a,#3fb64a)}
.gld-bar.boss u{background:linear-gradient(#ff8a8a,#d03a3a)}
.gld-bar em{position:absolute;inset:0;display:grid;place-items:center;font:700 2.5cqw/1 Arial,sans-serif;font-style:normal;color:#fff;text-shadow:0 1px 1px #000}
.gld-card{min-height:0;overflow:auto;margin:1cqh 3%;padding:1.4cqh 3cqw;border-radius:.8em;background:#16233ee6;color:#fff;display:grid;align-content:start;gap:1.2cqh}
.gld-card h2{margin:0;font:900 5cqw/1.1 Georgia,serif;font-style:italic;color:#ffe9a0}.gld-card h2 small{font:700 3cqw/1 Arial,sans-serif;color:#cfe0ff}
.gld-card>p{margin:0;font:400 2.9cqw/1.35 Arial,sans-serif;color:#dfe8ff}
.gld-act,.gld-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:2.5cqw;padding:1cqh 2.5cqw;border-radius:.6em;background:#ffffff14}
.gld-act .gld-ico{width:12cqw}.gld-row .gld-ico{width:12cqw}
.gld-act b,.gld-row b{display:block;font:700 3.3cqw/1.2 Arial,sans-serif;color:#fff}
.gld-act small,.gld-row small{font:400 2.6cqw/1.25 Arial,sans-serif!important;color:#cfe0ff!important}
.gld-row b small{font-size:2cqw!important;opacity:.75}
.gld-row .portrait-badge{width:11cqw;height:11cqw;border-radius:50%;filter:none}
.gld-row.me{background:#ffe27a2e;outline:1px solid #ffe27a}
.gld-row em{font:700 3.4cqw/1 Arial,sans-serif;font-style:normal;color:#ffe27a}
.gld-cols{display:flex;justify-content:space-between;font-size:2.6cqw!important;color:#9fb0d8!important}
#stage #main .gld .den-gold{padding:.55em 1.3em;border-radius:2em;border:0;background:linear-gradient(#ffe89a,#f0b548);color:#5a3a12;font:700 3.1cqw/1 Arial,sans-serif;white-space:nowrap}
#stage #main .gld .den-gold:disabled{filter:grayscale(.8);opacity:.6}
#stage #main .gld .gld-found{display:flex;align-items:center;justify-content:center;gap:.5em;justify-self:center;padding:.5em 2em;font-size:3.6cqw}
.gld-found .gld-ico{width:2em}
.gld-foot{display:flex;align-items:center;justify-content:space-between;margin:0 3%;font:400 2.5cqw/1.2 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000}
#stage #main .gld .gld-leave{padding:.4em 1em;border-radius:2em;background:#5a1d24cc;border:1px solid #ff8a8a;color:#fff;font:700 2.6cqw/1 Arial,sans-serif}
.gld-nav .gld-ico{width:7cqw}
#stage #main .gld-nav button:not([data-back]){width:16%;font-size:2.4cqw!important}
.gld-bossroom{justify-items:stretch}
.gld-boss-art{position:relative;justify-self:center;width:62%;aspect-ratio:1}
.gld-boss-art img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 6px 8px #000a)}
.gld-boss-art.hit img{animation:gld-shake .5s}
@keyframes gld-shake{20%{transform:translateX(-4%) rotate(-3deg)}40%{transform:translateX(4%) rotate(3deg)}60%{transform:translateX(-2%)}80%{transform:translateX(2%)}}
.gld-dmg{position:absolute;left:50%;top:20%;transform:translateX(-50%);font:900 7cqw/1 Arial,sans-serif;color:#ffd84a;text-shadow:0 2px 0 #7a2a00,0 0 8px #000;animation:gld-rise 1.2s ease-out forwards;pointer-events:none}
@keyframes gld-rise{to{transform:translate(-50%,-80%);opacity:0}}
.gld-board{display:grid;gap:.4cqh}
.gld-board>div{display:grid;grid-template-columns:7cqw minmax(0,1fr) auto;gap:2cqw;padding:.6cqh 2cqw;border-radius:.4em;background:#ffffff12;font:700 2.9cqw/1.2 Arial,sans-serif}
.gld-board>div.me{background:#ffe27a2e;outline:1px solid #ffe27a}.gld-board b{color:#ffe27a}.gld-board em{font-style:normal;color:#ff9a9a}.gld-board small{font-size:2cqw;opacity:.7}
.gld .mart-grid .shop-card .bag-ico{width:62%}
#stage #modal.den-pop .gld-name{width:100%;box-sizing:border-box;margin:6px 0;padding:8px 10px;border-radius:10px;border:2px solid #8fb3d8;font:400 15px/1.2 Arial,sans-serif}
.gld-crests{display:flex;justify-content:center;gap:10px;margin:6px 0 10px}
#stage #modal.den-pop .gld-crests button{width:60px;height:60px;min-height:0;padding:4px;border-radius:12px;background:#ffffff14;border:2px solid transparent}
#stage #modal.den-pop .gld-crests button[aria-pressed=true]{border-color:#ffe27a;background:#ffe27a33}
#stage #modal.den-pop .gld-crests .gld-ico{width:100%}
.chat-sheet .chat-feed{overflow-anchor:none;scroll-behavior:auto}

/* Guild second pass: Info / Member / Ranking / Red Envelope, Academy, Guild Beast (2026-11-21) */
.gi-body{min-height:0;overflow:auto;display:flex;flex-direction:column}
.gi-stage{position:relative;flex:none;height:36cqh}
.gi-banner{position:absolute;left:50%;top:1.5cqh;transform:translateX(-50%);display:flex;align-items:center;gap:2cqw;padding:.8cqh 6cqw;border-radius:.4em;background:linear-gradient(#8a2a2aee,#5a1616ee);border:2px solid #f3c86a;box-shadow:0 3px 8px #0008;white-space:nowrap}
.gi-banner .gld-crest{width:9cqw}.gi-banner b{font:900 5cqw/1 Georgia,serif;font-style:italic;color:#ffe9a0;text-shadow:0 2px 2px #000}
.gi-sign{position:absolute;right:2.5%;top:9cqh;display:grid;justify-items:center;gap:.6cqh;width:19cqw;padding:1cqh 1cqw;border-radius:.8em;background:#16233ed9}
#stage #main .gld .gi-signbtn{display:grid;justify-items:center;padding:.6cqh 1cqw;border:0;border-radius:.6em;background:linear-gradient(#ffe89a,#f0b548);color:#5a3a12;width:100%}
#stage #main .gld .gi-signbtn.done{filter:grayscale(.7);opacity:.75}
.gi-signbtn .gld-ico{width:9cqw}.gi-signbtn b{font:800 2.7cqw/1.1 Arial,sans-serif}
.gi-sign .gld-bar{width:100%;height:2.4cqh}
#stage #main .gld .gld-box{position:relative;display:grid;justify-items:center;width:100%;padding:0;border:0;background:none;color:#fff}
.gld-box .bag-ico{width:11cqw;filter:grayscale(.5) brightness(.8)}.gld-box.ready .bag-ico{filter:drop-shadow(0 0 6px #ffe27a);animation:gld-bob 1.2s ease-in-out infinite}.gld-box.open .bag-ico{opacity:.45}
.gld-box small{font:700 2.3cqw/1 Arial,sans-serif;color:#ffe9a0;text-shadow:0 1px 2px #000}
@keyframes gld-bob{50%{transform:translateY(-8%)}}
.gi-panel{flex:none;display:grid;gap:1cqh;margin:0 3% 1cqh;padding:1.2cqh 3cqw;border-radius:.8em;background:#16233ef0;color:#fff}
.gi-lead{display:flex;align-items:center;justify-content:space-between;gap:2cqw}
.gi-lead span{display:flex;align-items:center;gap:1.5cqw;font:700 3.3cqw/1.2 Arial,sans-serif}.gi-lead .war-ico{width:7cqw}.gi-lead small{font-size:2.2cqw;opacity:.75}
#stage #main .gld .gi-up{display:flex;align-items:center;gap:.4em;padding:.45em 1em;border-radius:2em;border:1px solid #f3c86a;background:#0c1228;color:#ffe9a0;font:700 3cqw/1 Arial,sans-serif}
.gi-up i{font-style:normal;color:#6dff7a;font-weight:900;font-size:1.2em}
.gi-note{padding:1cqh 2.5cqw;border-radius:.6em;background:#f6ead0;color:#4a3216}
.gi-note h3{display:flex;justify-content:space-between;align-items:center;margin:0 0 .5cqh;font:800 3.1cqw/1.1 Georgia,serif;color:#8a2a2a}
.gi-note p{margin:0;font:400 2.9cqw/1.35 Arial,sans-serif;color:#4a3216}
#stage #main .gld .gi-edit,#stage #main .gld .gi-rec{padding:.3em .8em;border-radius:2em;border:1px solid #c79a4a;background:#fff4dc;color:#7a4a12;font:700 2.6cqw/1 Arial,sans-serif}
.gi-cards{display:grid;grid-template-columns:1fr 1fr;gap:1cqh 2.5cqw}
.gi-card{display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto auto;column-gap:2cqw;align-items:center;padding:.9cqh 2.5cqw;border-radius:.6em;background:#ffffff14;border:1px solid #ffffff22}
.gi-card .gld-ico{grid-row:span 2;width:9cqw}.gi-card small{font:400 2.5cqw/1.1 Arial,sans-serif;color:#cfe0ff}.gi-card b{font:800 3.6cqw/1.1 Arial,sans-serif;color:#ffe27a}
.gi-speak{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:2cqw;padding:.8cqh 2.5cqw;border-radius:.6em;background:#0c1228}
.gi-speak span{font-size:4cqw}.gi-speak p{margin:0;font:italic 400 2.8cqw/1.3 Arial,sans-serif;color:#dfe8ff}
