#stage #main .cas-pad button{width:15cqw;height:15cqw;min-height:0;padding:0;border-radius:50%;border:2px solid #e8d8ff;background:radial-gradient(circle at 40% 30%,#c79aff,#6a2ad0 70%,#3a1280);color:#fff;font:900 6.4cqw/1 Arial,sans-serif;box-shadow:0 0 10px #9a6aff,0 4px 0 #2a0a60;touch-action:none}
#stage #main .cas-pad button:active{transform:translateY(3px);box-shadow:0 0 14px #d8b8ff,0 1px 0 #2a0a60}
#stage #main .cas-pad button[data-act=hard]{background:radial-gradient(circle at 40% 30%,#ffe89a,#f0a030 70%,#a05a10);border-color:#fff4c0}
/* pop-ups over the well */
.cas-pops{position:absolute;inset:0;pointer-events:none;display:grid;place-items:center;overflow:hidden}
.cas-pop{position:absolute;top:38%;display:grid;justify-items:center;padding:.3em .9em;border-radius:.6em;font:900 italic 7cqw/1.05 Georgia,serif;color:#fff;text-align:center;text-shadow:0 0 10px #ff9aff,0 3px 0 #5a1a9a,0 5px 8px #000;animation:cas-pop 1.6s cubic-bezier(.2,1.6,.4,1) forwards;white-space:nowrap}
.cas-pop small{font:700 3cqw/1.2 Arial,sans-serif;font-style:normal;color:#ffe9a0;text-shadow:0 1px 3px #000}
.cas-pop.burst.b2{color:#bfe8ff}.cas-pop.burst.b3{color:#ffe27a;font-size:8cqw}.cas-pop.burst.b4{font-size:9cqw;background:radial-gradient(#ffffff40,transparent 70%);animation-name:cas-pop-big}
.cas-pop.burst.b4 b{background:linear-gradient(90deg,#ff8a8a,#ffe27a,#8affc0,#8ac8ff,#e08aff);-webkit-background-clip:text;background-clip:text;color:transparent}
.cas-pop.combo{top:52%;font-size:5cqw;color:#8affd0;animation-delay:.12s}
.cas-pop.level{top:30%;font-size:6.4cqw;color:#ffe9a0}
.cas-pop.chest{top:46%;font-size:5cqw;color:#ffe27a;gap:.2em}.cas-pop.chest .cas-chest{width:22cqw;animation:cas-chest 1.6s ease-out}
@keyframes cas-pop{0%{transform:scale(.2) translateY(30px);opacity:0}18%{transform:scale(1.25);opacity:1}30%{transform:scale(1)}78%{opacity:1;transform:translateY(-14px)}100%{opacity:0;transform:translateY(-40px) scale(.9)}}
@keyframes cas-pop-big{0%{transform:scale(.2) rotate(-12deg);opacity:0}20%{transform:scale(1.45) rotate(4deg);opacity:1}34%{transform:scale(1) rotate(0)}80%{opacity:1}100%{opacity:0;transform:scale(1.15) translateY(-30px)}}
@keyframes cas-chest{0%{transform:scale(.3) rotate(-20deg)}25%{transform:scale(1.3) rotate(8deg);filter:drop-shadow(0 0 20px #fff6b0)}45%{transform:scale(1) rotate(0)}100%{filter:drop-shadow(0 0 8px #ffe27a)}}
/* result pop-up */
.cas-result{text-align:center}.cas-rhead{margin:0;font:800 13px/1 Arial,sans-serif;letter-spacing:.14em;color:#ffcf7a}
#stage #modal.den-pop .cas-rscore{margin:4px 0;font:900 40px/1 Georgia,serif;color:#fff;text-shadow:0 0 12px #c07aff,0 3px 0 #5a2aa0;animation:cas-pop 1s cubic-bezier(.2,1.6,.4,1) both;animation-duration:.7s}
.cas-rchests{display:flex;justify-content:center;gap:14px;margin:10px 0}
.cas-rchest{display:grid;justify-items:center;opacity:.45}.cas-rchest .cas-chest{width:70px}.cas-rchest small{font-size:11px;color:#ffe9a0}
.cas-rchest.won{opacity:1;animation:cas-chest 1.2s ease-out both;animation-delay:var(--d)}
.cas-rchest.won .cas-chest{filter:drop-shadow(0 0 10px #ffe27a)}
.cas-practice{color:#ffd36b}
.cas-confetti{position:absolute;top:30%;width:9px;height:14px;border-radius:2px;background:var(--hue);pointer-events:none;animation:cas-conf 1.6s ease-in forwards;z-index:5}
@keyframes cas-conf{0%{transform:translate(0,0) rotate(0);opacity:1}100%{transform:translate(var(--dx),320px) rotate(540deg);opacity:0}}
.cas-pop{white-space:normal;max-width:92%;line-height:1.05}
.cas-pop.burst.b4{font-size:8cqw}.cas-pop.burst.b3{font-size:7.4cqw}
#stage #modal.den-pop .cas-rscore{animation:cas-score .7s cubic-bezier(.2,1.6,.4,1) both}
@keyframes cas-score{0%{transform:scale(.2);opacity:0}60%{transform:scale(1.2);opacity:1}100%{transform:scale(1);opacity:1}}
.cas-pop.leave{animation:cas-leave .25s ease-in forwards!important}@keyframes cas-leave{to{opacity:0;transform:translateY(-30px) scale(.8)}}
/* Harvest Pairs effects (2026-11-22): energy bolt along the line, tile bursts, basket shower, finish panel */
.pairs-energy path{fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:1;animation:pairs-draw .17s linear forwards,pairs-fade .3s ease-in .3s forwards}
.pairs-energy .glow{stroke:#ffcf3a;stroke-width:.32;opacity:.55;filter:blur(.06px)}
.pairs-energy .core{stroke:#fffbe0;stroke-width:.1}
.pairs-energy .orb{fill:#fff;filter:drop-shadow(0 0 .12px #fff36b) drop-shadow(0 0 .25px #ff9a2e);animation:pairs-fade .15s ease-in .2s forwards}
@keyframes pairs-draw{to{stroke-dashoffset:0}}
@keyframes pairs-fade{to{opacity:0}}
.pairs-tile.matched{pointer-events:none;animation:pairs-pop .46s cubic-bezier(.3,1.6,.5,1) forwards!important}
@keyframes pairs-pop{0%{transform:scale(1)}30%{transform:scale(1.28);filter:brightness(1.8) drop-shadow(0 0 10px #fff6a0)}55%{opacity:1;transform:scale(1.1) rotate(6deg);filter:brightness(2.4) drop-shadow(0 0 16px #ffd36b)}100%{opacity:0;transform:scale(.2) rotate(-25deg);filter:brightness(3)}}
.pairs-burst{position:absolute;width:0;height:0;pointer-events:none;z-index:4}
.pairs-burst i{position:absolute;left:0;top:0;border-radius:50%;transform:translate(-50%,-50%)}
.pairs-burst .flash{width:calc(var(--cell)*1.3);height:calc(var(--cell)*1.3);background:radial-gradient(#fff 0,#fff8c0 25%,#ffd36b66 50%,transparent 70%);animation:pairs-flash .45s ease-out forwards}
.pairs-burst .ring{width:calc(var(--cell)*.4);height:calc(var(--cell)*.4);border:3px solid #fff6b0;box-shadow:0 0 10px #ffd36b,inset 0 0 8px #ffd36b;animation:pairs-ring .55s ease-out forwards}
.pairs-burst .spark{width:calc(var(--cell)*.16);height:calc(var(--cell)*.16);background:radial-gradient(#fff,#ffe27a 50%,#ff9a2e00 75%);animation:pairs-spark .6s cubic-bezier(.1,.7,.3,1) forwards}
@keyframes pairs-flash{0%{transform:translate(-50%,-50%) scale(.3);opacity:1}100%{transform:translate(-50%,-50%) scale(1.4);opacity:0}}
@keyframes pairs-ring{0%{transform:translate(-50%,-50%) scale(.4);opacity:1}100%{transform:translate(-50%,-50%) scale(3.6);opacity:0;border-width:1px}}
@keyframes pairs-spark{0%{transform:translate(-50%,-50%) rotate(var(--a)) translateX(0) scale(1.3);opacity:1}100%{transform:translate(-50%,-50%) rotate(var(--a)) translateX(calc(var(--cell)*var(--d))) scale(.2);opacity:0}}
.pairs-shower{position:absolute;inset:0;pointer-events:none;z-index:5;display:grid;place-items:center}
.pairs-shower i{position:absolute;left:50%;top:50%}
.pairs-shower .wave{width:20%;aspect-ratio:1;border-radius:50%;border:4px solid #fff6b0;box-shadow:0 0 24px #ffd36b,inset 0 0 18px #ffd36b;transform:translate(-50%,-50%);animation:pairs-wave .9s ease-out forwards}
.pairs-shower .star{width:calc(var(--cell)*.32);aspect-ratio:1;background:#fff6b0;clip-path:polygon(50% 0,61% 39%,100% 50%,61% 61%,50% 100%,39% 61%,0 50%,39% 39%);filter:drop-shadow(0 0 4px #ffd36b);animation:pairs-star 1s cubic-bezier(.1,.7,.3,1) var(--t) both}
.pairs-shower b{position:relative;font:900 italic clamp(1.4rem,7cqw,2.6rem)/1 Georgia,serif;color:#fff8d0;text-shadow:0 0 12px #ffb32e,0 3px 0 #8a4a10,0 6px 10px #000a;animation:pairs-banner 1.25s cubic-bezier(.2,1.6,.4,1) forwards}
@keyframes pairs-wave{to{transform:translate(-50%,-50%) scale(7);opacity:0}}
@keyframes pairs-star{0%{transform:translate(-50%,-50%) rotate(var(--a)) translateX(0) scale(.3);opacity:1}100%{transform:translate(-50%,-50%) rotate(var(--a)) translateX(calc(var(--cell)*3*var(--d))) rotate(180deg) scale(1);opacity:0}}
@keyframes pairs-banner{0%{transform:scale(.2);opacity:0}25%{transform:scale(1.2);opacity:1}40%{transform:scale(1)}80%{opacity:1}100%{opacity:0;transform:translateY(-20px)}}
.pairs-panel.pairs-done{overflow:visible;animation:pairs-done .7s cubic-bezier(.2,1.5,.4,1) both;box-shadow:0 0 0 3px #ffe27a,0 0 40px #ffd36b88,0 10px 30px #0009}
@keyframes pairs-done{0%{transform:translateY(-58%) scale(.3);opacity:0}60%{transform:translateY(-58%) scale(1.08);opacity:1}100%{transform:translateY(-58%) scale(1)}}
.pairs-done .pairs-rays{position:absolute;left:50%;top:30%;width:240%;aspect-ratio:1;transform:translate(-50%,-50%);background:repeating-conic-gradient(#fff6b033 0 8deg,transparent 8deg 22deg);mask:radial-gradient(closest-side,#000 30%,transparent);-webkit-mask:radial-gradient(closest-side,#000 30%,transparent);animation:pairs-rays 9s linear infinite;pointer-events:none;z-index:-1}
@keyframes pairs-rays{to{transform:translate(-50%,-50%) rotate(360deg)}}
.pairs-done h2{animation:pairs-banner-in .8s cubic-bezier(.2,1.6,.4,1) .2s both;text-shadow:0 0 14px #ffb32e}
.pairs-done .pairs-prize{animation:pairs-banner-in .7s cubic-bezier(.2,1.6,.4,1) .55s both}
@keyframes pairs-banner-in{0%{transform:scale(.3);opacity:0}60%{transform:scale(1.2);opacity:1}100%{transform:scale(1)}}
.pairs-confetti{position:absolute;top:35%;width:8px;height:13px;border-radius:2px;background:var(--hue);pointer-events:none;animation:pairs-conf 1.9s cubic-bezier(.2,.6,.4,1) forwards;z-index:3}
@keyframes pairs-conf{0%{transform:translate(0,0) rotate(0);opacity:1}35%{transform:translate(calc(var(--dx)*.6),var(--dy)) rotate(200deg)}100%{transform:translate(var(--dx),260px) rotate(620deg);opacity:0}}
@media (prefers-reduced-motion:reduce){.pairs-burst,.pairs-shower,.pairs-confetti{display:none}}
.pairs-shower b{white-space:nowrap;text-align:center}
.pairs-done h2{font-size:2.8rem!important}.pairs-confetti{z-index:6}
/* Mini Games list: compact 2 x 2 cards (user 2026-11-22: "the cards are huge") */
body[data-screen=games] #stage .game-portals{grid-template-columns:repeat(2,minmax(0,1fr))!important;grid-template-rows:none!important;grid-auto-rows:auto!important;align-content:start;gap:12px!important;padding:6px 10px 10px!important;overflow-y:auto;min-height:0}
body[data-screen=games] #stage .game-portal{height:auto!important;aspect-ratio:1/1.08;border-radius:16px;box-shadow:0 5px 14px #48311966}
body[data-screen=games] #stage .game-portal .portal-illustration{border-radius:16px}
body[data-screen=games] #stage .portal-emblem{transform:scale(.6);transform-origin:top left}
