/* Hub in a narrow centred column (user: "not across the full width"): three tiles a row, at most 560 px wide. */
body[data-screen=games] #stage #main>.mg-hub{width:min(560px,100%)!important;margin:0 auto;flex:0 1 auto}
body[data-screen=games] .mg-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:10px!important}
