/* Crystal Cascade third pass (user 2026-11-24): painted pad buttons and stat icons, no text selection while held */
.cas-screen,.cas-screen *{-webkit-user-select:none!important;user-select:none!important;-webkit-touch-callout:none!important}
.cas-well,.cas-well canvas,.cas-pad,.cas-pad button{touch-action:none!important}
#stage #main .cas-pad{align-items:center}
#stage #main .cas-pad button,#stage #main .cas-screen .cas-pause{background:var(--cas-pad) var(--bp,0 0)/400% 200% no-repeat!important;border:0!important;border-radius:50%!important;box-shadow:0 6px 12px #0009!important;color:transparent!important;font-size:0!important;transition:transform .08s,filter .08s}
#stage #main .cas-pad button::before,#stage #main .cas-pad button::after,#stage #main .cas-screen .cas-pause::before,#stage #main .cas-screen .cas-pause::after{display:none!important;content:none!important}
