.cas-stat{grid-template-columns:auto 1fr;grid-template-rows:auto auto;justify-items:start;align-items:center;column-gap:.8cqw;padding:1cqh 1cqw 1cqh .6cqw!important;border-radius:16px!important;background:linear-gradient(160deg,#4a2f9ae6,#22165aee 55%,#170e3ef2)!important;border:2px solid transparent!important;background-clip:padding-box!important;box-shadow:0 0 0 2px #d9a94a,0 0 0 4px #3a1a7a,0 0 16px #9a6aff66,0 6px 14px #000a,inset 0 1px 0 #ffffff33,inset 0 -10px 18px #0004!important;position:relative;overflow:hidden}
.cas-stat::after{content:"";position:absolute;inset:0;background:linear-gradient(105deg,transparent 40%,#ffffff26 50%,transparent 60%) -200% 0/300% 100% no-repeat;animation:cas-shine 4.5s ease-in-out infinite;pointer-events:none}
@keyframes cas-shine{0%,60%{background-position:-200% 0}100%{background-position:200% 0}}
.cas-sico{grid-row:1/3;width:clamp(28px,5.4cqh,56px);aspect-ratio:1;background:var(--cas-stats) calc(var(--n)*100%/3) 0/400% 100% no-repeat;filter:drop-shadow(0 2px 3px #0008)}
