.wr-card{position:relative;width:min(440px,94vw);max-height:94vh;display:flex;flex-direction:column;align-items:center;gap:8px;padding:106px 20px 20px;margin-top:44px;border-radius:26px;background:linear-gradient(170deg,#3b2a86f2,#1e1650f7 60%,#160f3cfa);box-shadow:0 0 0 3px #d9a94a,0 0 0 6px #3a1a7a,0 0 40px #9a6affaa,0 20px 40px #000c,inset 0 1px 0 #ffffff40;animation:wr-pop .55s cubic-bezier(.2,1.5,.4,1) both;color:#fff;text-align:center}
