@keyframes wr-pop{from{transform:scale(.6) translateY(30px);opacity:0}}
.wr-burst{position:absolute;left:50%;top:-30px;width:400px;height:400px;margin-left:-200px;margin-top:-200px;-webkit-mask-image:linear-gradient(#000 52%,transparent 68%);mask-image:linear-gradient(#000 52%,transparent 68%);animation:wr-burstin .8s ease-out both;pointer-events:none;z-index:0}
