.vw-board{position:absolute;left:41cqw;right:14cqw;top:27cqh;bottom:29.5cqh;z-index:2;display:flex;flex-direction:column;border-radius:2cqw;background:#fff1f6ee;box-shadow:0 0 0 2px #f3c86a,0 0 0 4px #a2386a,0 6px 16px #6a103066;overflow:hidden}
