.vp-head{position:relative;margin:-2px -14px 2px;padding:14px 40px 12px;border-radius:20px 20px 0 0;background:linear-gradient(#e2578f,#a92a62);box-shadow:inset 0 -3px 0 #f0c46a,inset 0 2px 0 #ff9cc4;text-align:center}
.vp-head h2{margin:0!important;font:900 22px/1 Georgia,serif!important;color:#fff8e6!important;text-shadow:0 2px 0 #6a1238,0 0 12px #ffcf6a!important;letter-spacing:.02em}
.vp-petal{position:absolute;top:50%;width:26px;height:26px;margin-top:-13px;background:radial-gradient(circle at 35% 35%,#fff,#ffb3cf 45%,#e0457f);border-radius:70% 0 70% 0;box-shadow:0 2px 4px #6a123866}
.vp-petal.l{left:12px;transform:rotate(-20deg)}.vp-petal.r{right:12px;transform:rotate(110deg)}
.vp-lead{margin:0;text-align:center;color:#8a2a52;font:700 13px/1.35 Arial,sans-serif}
.vp-pair{display:grid;grid-template-columns:auto auto auto 1fr;align-items:center;gap:8px;padding:8px 12px;border-radius:16px;background:linear-gradient(90deg,#fff,#ffeef4);box-shadow:inset 0 0 0 1.5px #f3c86a}
.vp-pair>i{font:normal 22px/1 Arial,sans-serif;color:#e8326a;animation:vpbeat 1.2s ease-in-out infinite;text-shadow:0 0 8px #ff8ab8}
@keyframes vpbeat{50%{transform:scale(1.25)}}
.vp-pair p{margin:0 0 0 4px;display:grid;gap:2px}.vp-pair p b{font:900 15px/1.15 Georgia,serif;color:#8a1a48}.vp-pair p small{color:#b0507a;font-weight:700}
.vp-face{display:inline-grid;place-items:center;width:52px;height:52px;border-radius:50%;overflow:hidden;background:#fff;box-shadow:0 0 0 2.5px #f3c86a,0 0 0 4px #b03a6e,0 3px 6px #6a123855;flex:none}
.vp-face .portrait-badge{width:100%!important;height:100%!important;margin:0!important;border:0!important;box-shadow:none!important}
.vp-face.me{box-shadow:0 0 0 2.5px #f3c86a,0 0 0 4px #4a9a5a,0 3px 6px #6a123855}
.vp-q{font:900 26px/1 Georgia,serif;color:#d8487a}
#stage #modal .vp-tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;padding:4px;border-radius:14px;background:#f8cadb}
#stage #modal .vp-tabs button{min-height:34px;padding:4px 2px;border:0;border-radius:10px;background:none;box-shadow:none;color:#8a2a52;font:800 12px/1.1 Arial,sans-serif}
#stage #modal .vp-tabs button.on{background:linear-gradient(#ff8ab8,#d8487a);color:#fff;box-shadow:0 2px 6px #a92a6266}
.vp-list{display:grid;gap:8px;max-height:min(46vh,360px);overflow:auto;padding:2px 2px 4px}
.vp-card{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;padding:8px 10px;border-radius:16px;background:linear-gradient(90deg,#fff,#fff4f8);box-shadow:inset 0 0 0 1.5px #f6c7d8,0 2px 6px #b03a6e22}
.vp-card.is{box-shadow:inset 0 0 0 2px #f0b548,0 0 12px #ffcf6a88}
.vp-info{display:grid;gap:2px;min-width:0}
.vp-info b{display:flex;align-items:baseline;gap:6px;font:900 15px/1.1 Georgia,serif;color:#6a1a3a}
.vp-info b small{padding:1px 5px;border-radius:6px;background:#ffd6e4;color:#b0507a;font:800 9px/1.3 Arial,sans-serif}
.vp-info b em{margin-left:auto;font:800 11px/1 Arial,sans-serif;font-style:normal;color:#9a5a72}
.vp-hearts i{font-style:normal;font-size:13px;color:#f3c8d6}.vp-hearts i.on{color:#e8326a}.vp-hearts i.half{color:#f08aaa}
.vp-tag{font:600 11px/1.2 Arial,sans-serif;color:#9a5a72;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vp-bonded{padding:6px 10px;border-radius:12px;background:linear-gradient(#ff8ab8,#d8487a);color:#fff;font:900 12px/1 Arial,sans-serif;white-space:nowrap}
.vp-empty{margin:8px 0;padding:18px 10px;border-radius:14px;background:#fff6f9;text-align:center;color:#9a5a72;box-shadow:inset 0 0 0 1.5px #f6c7d8}
#stage #modal .vp :is(.vp-invite,.vp-send){border:0;border-radius:2em;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat;box-shadow:none;color:#5a2a06;text-shadow:0 1px 0 #fff6c8;cursor:pointer}
#stage #modal .vp .vp-invite{min-width:84px;min-height:40px;padding:0 12px 3px;font:900 14px/1 Georgia,serif}
#stage #modal .vp :is(.vp-invite,.vp-send):disabled{filter:grayscale(.8) brightness(.95);opacity:.65}
#stage #modal .vp button::before,#stage #modal .vp button::after{display:none!important}
#stage #modal .vp .vp-who{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}
#stage #modal .vp .vp-who button{display:grid;justify-items:center;gap:2px;padding:0;border:0;background:none;box-shadow:none;color:#8a2a52;font:800 10px/1 Arial,sans-serif;opacity:.6}
#stage #modal .vp .vp-who button .portrait-badge{width:38px!important;height:38px!important;border-radius:50%;box-shadow:0 0 0 2px #f3c8d6}
#stage #modal .vp .vp-who button.on{opacity:1}#stage #modal .vp .vp-who button.on .portrait-badge{box-shadow:0 0 0 2.5px #f0b548,0 0 8px #ffcf6a}
.vp-gifts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
#stage #modal .vp .vp-gift{position:relative;display:grid;justify-items:center;gap:2px;padding:12px 4px 8px;border:0;border-radius:16px;color:#fff;box-shadow:inset 0 0 0 2px #ffffff66,0 4px 10px #6a123844;text-shadow:0 1px 2px #0006;transition:transform .12s}
#stage #modal .vp .vp-gift.c-b{background:linear-gradient(170deg,#7ec3ff,#2a6ad0)}#stage #modal .vp .vp-gift.c-p{background:linear-gradient(170deg,#c99aff,#7a3ae0)}#stage #modal .vp .vp-gift.c-o{background:linear-gradient(170deg,#ffc07a,#e0661a)}
#stage #modal .vp .vp-gift.on{transform:translateY(-3px) scale(1.03);box-shadow:0 0 0 3px #ffe27a,0 0 18px #ffcf6a,0 8px 14px #6a123855}
#stage #modal .vp .vp-gift.on::after{content:"✓"!important;display:grid!important;place-items:center;position:absolute;left:6px;top:6px;width:20px;height:20px;border-radius:50%;background:#3fbf6a;color:#fff;font:900 12px/1 Arial,sans-serif;box-shadow:0 0 0 2px #fff}
.vp-gift .vw-ico.big{width:56px!important;height:56px!important;filter:drop-shadow(0 3px 4px #0005)}
.vp-gift b{font:900 13px/1.1 Georgia,serif}.vp-gift small{font:800 10.5px/1.15 Arial,sans-serif;opacity:.95}
.vp-gift em{position:absolute;right:6px;top:5px;padding:1px 6px;border-radius:8px;background:#0005;font:900 11px/1.3 Arial,sans-serif;font-style:normal}
.vp-i{position:absolute;right:6px;bottom:6px;width:18px;height:18px;border-radius:50%;background:#fff;color:#a92a62;font:900 italic 11px/18px Georgia,serif;text-align:center;text-shadow:none}
.vp-note{display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:14px;background:repeating-linear-gradient(#fff 0 22px,#ffe0ea 22px 23px);box-shadow:inset 0 0 0 1.5px #f6c7d8}
.vp-note span{color:#d8487a;font-size:16px}.vp-note input{flex:1;min-width:0;border:0!important;background:none!important;box-shadow:none!important;padding:4px 0!important;font:italic 600 14px/1.2 Georgia,serif!important;color:#6a1a3a!important;outline:0}
.vp-note small{color:#b0507a;font-weight:800}
.vp-foot{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:center}
.vp-step{display:flex;align-items:center;gap:4px;padding:4px;border-radius:2em;background:#ffd6e4;box-shadow:inset 0 0 0 1.5px #f3a6c2}
#stage #modal .vp .vp-step button{width:34px;height:34px;min-height:0;padding:0;border:0;border-radius:50%;background:linear-gradient(#ff8ab8,#d8487a);box-shadow:0 2px 0 #8a1a48;color:#fff;font:900 18px/1 Arial,sans-serif}
.vp-step b{min-width:28px;text-align:center;font:900 18px/1 Georgia,serif;color:#6a1a3a}
#stage #modal .vp .vp-send{display:grid;place-items:center;align-content:center;gap:1px;min-height:58px;padding:0 10px 4px}
.vp-send span{font:900 20px/1 Georgia,serif}.vp-send small{font:800 11px/1 Arial,sans-serif;color:#7a3a06}
.vp-note{min-height:0!important;height:auto!important}
#stage #modal .vp .vp-note input{height:28px!important;min-height:0!important;margin:0!important}
#stage #modal .vp .vp-send{outline:0!important}
#stage #modal.den-pop:has(.vp)>.dialog-dismiss{top:6px!important;right:6px!important;z-index:3}
.vp-petal.r{right:56px}
#stage #modal .vp .vp-who button small{margin-top:3px}
#stage #modal .vp .vp-pair p small{font:700 12px/1.25 Arial,sans-serif!important;color:#b0507a!important}
#stage #modal .vp .vp-pair p b{font:900 15px/1.15 Georgia,serif!important}
@media (min-width:800px){#stage #modal.den-pop:has(.vp){max-width:520px!important;width:520px!important}.vp{font-size:14px}.vp-face{width:60px;height:60px}}
/* Blossom Vow sub-tab pop-ups (Partner Bond, Bond Transfer, Bond Gift, Bond Reward): same .vp card family */
#stage #modal .vp :is(.vp-wide,.vp-pay){display:grid;place-items:center;gap:1px;width:100%;min-height:54px;padding:0 10px 4px;border:0;border-radius:2em;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat;box-shadow:none;color:#5a2a06;text-shadow:0 1px 0 #fff6c8;font:900 18px/1 Georgia,serif}
#stage #modal .vp .vp-pay.alt{background-image:url(assets/generated/ui-btn-violet.webp);color:#fff;text-shadow:0 2px 0 #3a0a4a}
#stage #modal .vp .vp-pay span{display:inline-flex;align-items:center;gap:6px}#stage #modal .vp .vp-pay small{font:800 10.5px/1 Arial,sans-serif;opacity:.9}
#stage #modal .vp .vp-pay :is(img,.vw-ico){width:22px!important;height:22px!important}
.vp-two{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.vp-row{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-radius:14px;background:#fff;box-shadow:inset 0 0 0 1.5px #f6c7d8;font:800 13px/1 Arial,sans-serif;color:#8a2a52}
.vp-hearts.big i{font-size:20px;margin-left:2px}
.vp-lock{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;padding:10px 12px;border-radius:16px;background:linear-gradient(90deg,#fff,#ffeef4);box-shadow:inset 0 0 0 1.5px #f3c86a}
.vp-lock .vw-ico.big{width:52px!important;height:52px!important}
.vp-lock b{display:block;font:900 15px/1.1 Georgia,serif;color:#8a1a48}.vp-lock small{font:700 11px/1.2 Arial,sans-serif;color:#9a5a72}
.vp-bar{display:block;height:9px;margin:5px 0 3px;border-radius:6px;background:#f8cadb;overflow:hidden;box-shadow:inset 0 1px 2px #8a1a4844}.vp-bar u{display:block;height:100%;background:linear-gradient(90deg,#ff8ab8,#e8326a)}
.vp-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.vp-stats span{display:grid;justify-items:center;gap:2px;padding:8px 4px;border-radius:14px;background:#fff;box-shadow:inset 0 0 0 1.5px #f6c7d8}
.vp-stats small{font:800 10px/1 Arial,sans-serif;letter-spacing:.1em;color:#b0507a}.vp-stats b{font:900 18px/1 Georgia,serif;color:#6a1a3a}.vp-stats em{font:800 11px/1 Arial,sans-serif;font-style:normal;color:#2a9a5a}
.vp-own{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
.vp-own span{display:inline-flex;align-items:center;gap:4px;padding:4px 10px 4px 4px;border-radius:2em;background:#fff;box-shadow:inset 0 0 0 1.5px #f3c86a;font:900 13px/1 Arial,sans-serif;color:#6a1a3a}
.vp-own .vw-ico{width:26px!important;height:26px!important}
.vp-gico{display:grid;place-items:center;width:52px;height:52px;border-radius:14px;box-shadow:inset 0 0 0 2px #fff8}
.vp-gico.c-b{background:linear-gradient(170deg,#7ec3ff,#2a6ad0)}.vp-gico.c-p{background:linear-gradient(170deg,#c99aff,#7a3ae0)}.vp-gico.c-o{background:linear-gradient(170deg,#ffc07a,#e0661a)}
.vp-gico .vw-ico.big{width:42px!important;height:42px!important}
#stage #modal .vp .vp-price span{display:inline-flex;align-items:center;gap:4px}#stage #modal .vp .vp-price :is(img,.vw-ico,.gpt-icon){width:18px!important;height:18px!important}
.vp-pair.one{grid-template-columns:1fr;text-align:center}.vp-pair.one p{margin:0}
.vp-card.rw{grid-template-columns:86px 1fr}
.vp-card.rw.top.t1{background:linear-gradient(90deg,#fff1c2,#fff)}.vp-card.rw.top.t2{background:linear-gradient(90deg,#e4ecff,#fff)}.vp-card.rw.top.t3{background:linear-gradient(90deg,#ffe2cf,#fff)}
.vp-rank{display:grid;justify-items:center;gap:2px;font:900 13px/1 Georgia,serif;color:#8a1a48}.vp-rank .vw-badge{width:46px!important}
.vp-card.rw .vw-tiles{display:flex;flex-wrap:wrap;gap:5px}
#stage #modal .vp .vp-who button:disabled{opacity:.35}
#stage #modal .vp .vp-who button small{font:800 11px/1.1 Arial,sans-serif!important;color:#8a2a52!important;text-shadow:none!important}
#stage #modal .vp .vp-who button{min-height:0!important;border:0!important;background:none!important;box-shadow:none!important;padding:0!important}
#stage #modal .vp .vp-rank b,#stage #modal .vp .vp-row>span:first-child{color:#8a1a48!important;font:900 13px/1.1 Georgia,serif!important}
#stage #modal .vp .vp-pay small{color:inherit!important}
#stage #modal .vp .vw-tile{width:46px!important;height:46px!important;min-width:0!important;flex:none}
#stage #modal .vp .vw-tile .vw-ico,#stage #modal .vp .vw-tile img,#stage #modal .vp .vw-tile .gpt-icon{width:34px!important;height:34px!important}
#stage #modal .vp .vp-own b{display:inline!important;font:900 13px/1 Arial,sans-serif!important;color:#6a1a3a!important}
#stage #modal .vp .vw-tile b{position:absolute;right:-3px;bottom:-3px;min-width:16px;padding:1px 4px;border-radius:8px;background:#6a1a3a;color:#fff;font:900 10px/1.3 Arial,sans-serif!important;text-align:center}
#stage #modal .vp .vp-list{outline:0!important}
.vw-pair .portrait-badge{border-radius:50%!important;box-shadow:0 0 0 2.5px #f3c86a,0 0 0 4px #b03a6e,0 3px 6px #6a123855!important;border:0!important}

/* ===== Full-width screens (2026-11-24, user: "some sections are narrow, Blossom Vow opens to the full width and looks
   much better; make ALL sections open to the full width"). Every room fills the window up to 86dvh (full width in the
   chat pane 590 x 690 and on iPad portrait; no absurd stretching on a landscape desktop). Only the Mini Games hub stays a
   deliberate narrow column (.mg-hub). Self-contained block: per-screen fixes for the wider rooms follow below. ===== */
body:is([data-screen=home],[data-screen=character],[data-screen=fashion],[data-screen=isleArena],[data-screen=cityBag],[data-screen=cityCraft],[data-screen=cityVault],[data-screen=cityDevour],[data-screen=cityPet],[data-screen=cityCompanion],[data-screen=citySkin],[data-screen=cityForge],[data-screen=cityDaily],[data-screen=cityGameplay],[data-screen=cityExplore],[data-screen=cloudWar],[data-screen=eliteSale],[data-screen=cityBounty],[data-screen=cityHunting],[data-screen=citySummon],[data-screen=cityContest],[data-screen=citySocial],[data-screen=cityGuild],[data-screen=citySupreme]) #stage{width:min(100%,86dvh)!important;margin-inline:auto}

/* Elite Sale: the figure row takes what is left (no figures over the title); painted gold / violet buttons. */
#stage #main .elite-sale .el-title{font-size:min(8.4cqw,6.4cqh)}
#stage #main .elite-sale .el-time{font-size:min(2.7cqw,2.1cqh)}
#stage #main .elite-sale .el-cols{align-items:stretch;min-height:0}
#stage #main .elite-sale .el-col{grid-template-rows:minmax(0,1fr) auto auto auto;align-content:stretch;min-height:0}
html body #stage #main .elite-sale .el-fig{height:100%!important;width:100%;min-height:0;object-fit:contain;object-position:center bottom}
html body #stage #main .elite-sale :is(.el-bow,.el-deco){height:100%!important;min-height:0;width:100%}
html body #stage #main .elite-sale .el-bow img{height:min(62cqw,100%)!important}
#stage #main .elite-sale .el-tag{margin-top:-3cqh}
#stage #main .elite-sale .el-cp{font-size:min(5cqw,3.6cqh);margin:.4cqh 0}
#stage #main .elite-sale .el-card h3{font-size:min(3.3cqw,2.5cqh)}
#stage #main .elite-sale .el-items{padding:1cqh 0 .5cqh}
#stage #main .elite-sale .el-old{font-size:min(3cqw,2.3cqh)}
html body #stage #main .elite-sale button.el-buy{display:inline-flex;align-items:center;justify-content:center;gap:.3em;width:min(78%,15em);min-height:0;margin:.2cqh 0 1.2cqh;padding:.5em 1em .62em;border:0;outline:0!important;border-radius:2em;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat;box-shadow:none;color:#5a2a06;text-shadow:0 1px 0 #fff6c8;font:900 min(4.4cqw,3.3cqh)/1 Georgia,serif;cursor:pointer;transition:transform .08s,filter .08s}
html body #stage #main .elite-sale button.el-buy:active{transform:scale(.96);filter:brightness(1.08)}
html body #stage #main .elite-sale button.el-buy:disabled{filter:grayscale(.8);opacity:.6}
html body #stage #main .elite-sale :is(.el-buy,.el-nav button)::before,html body #stage #main .elite-sale :is(.el-buy,.el-nav button)::after{display:none!important;content:none!important}
html body #stage #main .elite-sale .el-nav{gap:1.4cqw;padding:1cqh 2cqw calc(1cqh + env(safe-area-inset-bottom,0px));background:linear-gradient(#2d2463ee,#1d1640)!important;border-top:1px solid #c9a8ff66}
html body #stage #main .elite-sale .el-nav button:not([data-back]){flex:1;width:auto;min-height:min(10cqw,7cqh);margin:0!important;padding:0 .5em .2em!important;border:0!important;border-radius:2em!important;outline:0!important;background:url(assets/generated/ui-btn-violet.webp) center/100% 100% no-repeat!important;box-shadow:none!important;color:#fff!important;text-shadow:0 2px 0 #3a0a6a,0 0 6px #c07aff;font:800 min(2.7cqw,2cqh)/1.05 Georgia,serif!important;white-space:normal}
html body #stage #main .elite-sale .el-nav button[aria-current]{background-image:url(assets/generated/ui-btn-gold.webp)!important;color:#5a2a06!important;text-shadow:0 1px 0 #fff6c8}

/* Supreme Set room: piece tiles, Wear button and set cards are capped by the height so the stage keeps its room. */
#stage #main .sup-room .sup-side .sup-tile{width:min(15cqw,8cqh)}
#stage #main .sup-room .sup-side{gap:min(1.2cqh,2cqw);align-content:start;align-self:start;padding-top:.6cqh}
#stage #main .sup-room .sup-stage{grid-template-rows:minmax(0,1fr)}
#stage #main .sup-room .sup-center{grid-template-rows:minmax(0,100%)}
#stage #main .sup-room .sup-center img{max-height:100%;min-height:0}
#stage #main .sup-room h1{font-size:min(5cqw,4.4cqh)}
#stage #main .sup-room .sup-stars{font-size:min(4.2cqw,3.4cqh)}
#stage #main .sup-room .sup-rows>div{font-size:min(3cqw,2.3cqh)}
#stage #main .sup-room .sup-wear{width:min(20cqw,12cqh);font-size:min(3.6cqw,2cqh);line-height:1.05;padding:0 .3em}
#stage #main .sup-room .sup-sets button{flex:0 0 min(22cqw,14cqh)}
#stage #main .sup-room .sup-sets b{font-size:min(2.4cqw,1.9cqh)}
#stage #main .sup-room .sup-sets small{font-size:min(2.1cqw,1.6cqh)}
#stage #main .sup-room .sup-ribbon{font-size:min(3.4cqw,2.6cqh)}
#stage #main .sup-room .sup-center .sup-cp{font-size:min(5cqw,3.8cqh)}
#stage #main .sup-room .sup-round{width:min(14cqw,10cqh);font-size:min(7cqw,5cqh);outline:0!important;box-shadow:none!important}
#stage #main .sup-room .sup-round small{font-size:min(2.3cqw,1.8cqh)}
html body #stage #main .sup-room .sup-nav{gap:1.4cqw;padding:1cqh 2cqw;background:linear-gradient(#1e2a6aee,#140c30)!important}
html body #stage #main .sup-room .sup-nav button:not([data-back]){flex:1;width:auto;min-height:min(10cqw,7cqh);margin:0!important;padding:0 .5em .2em!important;border:0!important;border-radius:2em!important;outline:0!important;background:url(assets/generated/ui-btn-violet.webp) center/100% 100% no-repeat!important;box-shadow:none!important;color:#fff!important;text-shadow:0 2px 0 #3a0a6a,0 0 6px #c07aff;font:800 min(2.7cqw,2cqh)/1.05 Georgia,serif!important}
html body #stage #main .sup-room .sup-nav button[aria-current]{background-image:url(assets/generated/ui-btn-gold.webp)!important;color:#5a2a06!important;text-shadow:0 1px 0 #fff6c8}
html body #stage #main .sup-room .sup-nav button::before,html body #stage #main .sup-room .sup-nav button::after{display:none!important;content:none!important}

/* City rooms (Bag family, Pets, Companion, Skin, Forge, Daily, Gameplay, Bounty, Hunting): their bottom bar is a <nav>,
   and the global app-nav rules made it an absolute 94 px slab that covered the row above it. Keep it in its grid row
   and size its captions by the height as well as the width. */
html body #stage #main .spirit-room>nav.spirit-nav{position:relative;inset:auto;height:auto;min-height:0;padding:0;display:flex;grid-template-columns:none;grid-template-rows:none;box-shadow:none;backdrop-filter:none}
html body #stage #main .spirit-room>nav.spirit-nav button:not([data-back]){font-size:min(2.8cqw,1.9cqh);white-space:nowrap;min-height:0;height:auto}
html body #stage #main .spirit-room>nav.spirit-nav button[data-back]{flex:0 0 min(17%,12cqh)!important;min-height:0!important;height:auto}
html body #stage #main .satchel-nav button:not([data-back]){font-size:min(2.7cqw,1.85cqh)!important;white-space:nowrap}
/* Gear Crafting: input places and slot tiles stay tile-sized on a wide window. */
#stage #main .loom .loom-row>*{width:min(17.5%,10.5cqh)}
#stage #main .loom .loom-slots{width:min(100%,62cqh);margin-inline:auto}
#stage #main .loom .loom-work :is(h2,p,.loom-rate){font-size:min(3.9cqw,2.7cqh)}
#stage #main .loom .loom-work p{font-size:min(2.7cqw,1.95cqh)}
#stage #main .loom .loom-orbit{width:min(60%,17cqh)}
#stage #main .loom-body aside button{font-size:min(2.75cqw,1.9cqh)}
#stage #main .loom-buttons button{font-size:min(3cqw,2.1cqh)}
/* Forge: the item rail had 21%-wide cards with the full-size font of the global buttons. */
html body #stage #main .smith-rail button{flex:0 0 min(21%,15cqh);font:700 min(2.5cqw,1.8cqh)/1.15 Arial,sans-serif;padding:.4em .2em;overflow:hidden}
html body #stage #main .smith-rail button>small{font-size:1em;line-height:1.15}
#stage #main .smith-room .smith-scene>.smith-item{width:min(17cqw,11cqh)}
html body #stage #main .smith-rail .smith-item{width:min(13cqw,7.3cqh)}
#stage #main .smith-room .smith-rune{width:min(55%,30cqh)}
#stage #main .smith-room .smith-scene>strong{font-size:min(4.5cqw,3.2cqh)}
#stage #main .smith-room .smith-panel h3{font-size:min(3.5cqw,2.5cqh)}

/* Skin room (Wings, Soulforge ...): its title row is a <header>, which the global app-header rules took out of the grid
   (absolute, 88 px), so every later row slid up one place and the wings covered the stats. Put it back in its row. */
html body #stage #main .skin-room>header{position:relative;inset:auto;width:auto;height:auto;min-height:0;padding:0 2%;display:flex;align-items:center;justify-content:space-between;z-index:auto}
#stage #main .skin-room>header h2{margin:0;font-size:min(4cqw,3.4cqh)}
#stage #main .skin-room .spirit-value{font-size:min(4.5cqw,3.6cqh)}
#stage #main .skin-room .companion-show{min-height:0;overflow:hidden;grid-template-rows:minmax(0,100%)}
#stage #main .skin-room .companion-show label{display:flex;align-items:center;gap:.4em;font-size:min(2.8cqw,2cqh)}
#stage #main .skin-room .skin-skills img{width:min(9%,7cqh)}
#stage #main .skin-room .skin-scroll button{font-size:min(2.7cqw,1.9cqh)}
#stage #main .skin-room .companion-stats{overflow:auto;min-height:0}
#stage #main .skin-room .companion-stats :is(small,strong){font-size:min(2.6cqw,1.9cqh)}
#stage #main .skin-room .companion-stats>div:first-child>div{font-size:min(2.75cqw,1.95cqh)}
/* Skin room, Appearance mode (old wardrobe layout .fashion-showcase, capped at 600-800 px): fill the room as well. */
html body[data-screen=citySkin] #stage #main .fashion-showcase{width:100%;max-width:none}

#stage #main .skin-room .companion-show input{width:1.3em!important;height:1.3em!important;min-width:0!important;min-height:0!important;margin:0}
/* Mode pills (Upgrade / Morphing / Appearance, Enhance / Upgrade / Identify ...): the stock icon was taller than the pill. */
#stage #main .spirit-room .companion-modes button{display:flex;align-items:center;justify-content:center;gap:.35em;min-height:0}
#stage #main .spirit-room .companion-modes button>.gpt-icon{flex:none;width:min(1.6em,3cqh);height:min(1.6em,3cqh)}

/* Fashion room: the room is now full width, but every cqw size is capped at what it was on the old 58dvh-wide room
   (X cqw -> min(X cqw, 0.58 X cqh)), so the top bar, panel, tabs and bottom bar keep their height and Reina keeps her
   big stage; the card grid shows more columns instead of bigger cards. */
html body #stage #main .fx-room .fx-top strong{font-size:min(4cqw,2.3cqh)}
html body #stage #main .fx-room .fx-wallet{font-size:min(3cqw,1.75cqh)}
html body #stage #main .fx-room .fx-stage{margin-top:max(-6cqw,-3.5cqh)}
html body #stage #main .fx-room .fx-stage .fashion-model{inset:0 0 min(6.2cqw,3.6cqh)!important}
html body #stage #main .fx-room .fx-stage .fashion-stage h2{top:min(7.5cqw,4.35cqh)!important;font-size:min(4cqw,2.3cqh)}
html body #stage #main .fx-room .fx-cp{font-size:min(5cqw,2.9cqh)!important}
html body #stage #main .fx-room .fx-round{width:min(13cqw,7.5cqh)!important;bottom:min(1cqw,.6cqh)!important}
html body #stage #main .fx-room .fx-round i{width:min(8.5cqw,4.9cqh)!important;font-size:min(4cqw,2.3cqh)!important}
html body #stage #main .fx-room .fx-round small{font-size:min(2.1cqw,1.25cqh)!important}
html body #stage #main .fx-room .fx-stats>div{font-size:min(3.1cqw,1.8cqh)}
html body #stage #main .fx-room .fx-pick .fx-ptile{width:min(13cqw,7.5cqh)}
html body #stage #main .fx-room .fx-pick>b{font-size:min(3cqw,1.75cqh)}
html body #stage #main .fx-room .fx-pick small{font-size:min(2.4cqw,1.4cqh)}
html body #stage #main .fx-room .fx-btn{font-size:min(3.2cqw,1.86cqh)}
html body #stage #main .fx-room .fx-tabs button{height:min(8.6cqw,5cqh);margin-top:min(1.2cqw,.7cqh)!important;font-size:min(2.15cqw,1.25cqh)!important}
html body #stage #main .fx-room .fx-tabs button[aria-pressed=true]{height:min(9.8cqw,5.7cqh);margin-top:0!important}
html body #stage #main .fx-room .fx-tabs img,html body #stage #main .fx-room .fx-tabs .fx-tabico{width:min(4.6cqw,2.7cqh);height:min(4.6cqw,2.7cqh)}
html body #stage #main .fx-room .fx-tabs .fx-tabico{font-size:min(3.2cqw,1.86cqh)}
html body #stage #main .fx-room .fx-grid{grid-template-columns:repeat(auto-fill,minmax(min(22%,13cqh),1fr))!important}
html body #stage #main .fx-room.fashion-showcase{width:100%;max-width:none}
html body #stage #main .fx-room .fx-card>span{font-size:min(2.2cqw,1.3cqh)}
html body #stage #main .fx-room .fx-rar{font-size:min(3cqw,1.75cqh)}
html body #stage #main .fx-room .fx-card.r-ssr .fx-rar{font-size:min(2.6cqw,1.5cqh)}
html body #stage #main .fx-room .fx-tick{width:min(5cqw,2.9cqh);font-size:min(3cqw,1.75cqh)}
html body #stage #main .fx-room .fx-lock{font-size:min(3.6cqw,2.1cqh)}
html body #stage #main .fx-room .fx-nav button{font-size:min(2.8cqw,1.62cqh)}
html body #stage #main .fx-room .fx-nav b{font-size:min(5.5cqw,3.2cqh)}
html body #stage #main .fx-room .fx-theme>b,html body #stage #main .fx-room .fx-theme button{font-size:min(2.3cqw,1.33cqh)}
html body #stage #main .fx-room .fx-bigdeco .sup-frame.pf{width:min(44cqw,25.5cqh)}
html body #stage #main .fx-room .fx-bigdeco .pb{width:min(58cqw,33.6cqh);font-size:min(6.5cqw,3.77cqh)}

/* Explore (chapter map): the right-hand tool buttons took the global 24 px button font and padding and stuck out of
   their 15% column ("Clear Battle Pas", "Assignmen"); fit them to the column. */
html body #stage #main .explore-map .trail-tools button{box-sizing:border-box;width:100%;min-width:0;min-height:0;padding:.35em .15em;font-size:min(2.5cqw,1.8cqh);line-height:1.1;overflow:hidden}
html body #stage #main .explore-map .trail-tools button :is(img,.gpt-icon){max-width:70%}
html body #stage #main .explore-map .trail-tools{bottom:max(11%,120px)}
html body #stage #main .explore-map .trail-tools button>img{height:min(6.5cqw,4.6cqh);width:auto}

/* ===== Burrow Blitz (2026-11-25, user photos of the reference's whack-a-critter "Max Combo"): lobby, run, pop-ups.
   The room is a size container; the field is one too (holes sized by min(cqw,cqh)). Strong selectors: the global
   #main button rules set position, borders and ::before. ===== */
body[data-screen=burrow] #stage{width:min(100%,86dvh)!important;max-width:none!important}
body[data-screen=burrow] #stage>:is(header,nav,footer),body[data-screen=burrow] .return-to-menu{display:none!important}
body[data-screen=burrow] #stage>#main{inset:0!important;width:100%;height:100%;padding:0!important;display:block;overflow:hidden}
.bb-room{position:absolute;inset:0;overflow:hidden;container-type:size;background:var(--bb-bg) center top/cover no-repeat,#5aa04a;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;font-family:Arial,sans-serif;color:#fff}
.bb-room *{-webkit-tap-highlight-color:transparent}
.bb-crit{display:block;aspect-ratio:256/288;background:var(--bb-crit) calc(var(--cx,0)*100%/3) calc(var(--cy,0)*100%)/400% 200% no-repeat}
html body #stage #main .bb-room button{position:absolute;min-height:0;margin:0;padding:0;border:0;background:none;box-shadow:none;color:#fff;outline:0;cursor:pointer;font:inherit;text-transform:none;letter-spacing:0}
html body #stage #main .bb-room button::before,html body #stage #main .bb-room button::after{display:none!important}
html body #stage #main .bb-room button>svg:first-child{display:none}
html body #stage #main .bb-room button.bb-back{left:2.5cqw;bottom:2.2cqh;width:min(13cqw,8cqh);height:min(13cqw,8cqh);z-index:30}
/* Lobby: a flex column; the scene takes what the panels leave, the rankings board sits on its lower left. */
.bb-lobby{display:flex;flex-direction:column;align-items:stretch;gap:min(1.4cqh,10px);padding:1.2cqh 3cqw 1.4cqh;box-sizing:border-box}
.bb-lobby::after{content:'';position:absolute;inset:auto 0 0;height:55cqh;background:linear-gradient(#0d2a1400,#0d2a14aa 40%,#081a0ddd);pointer-events:none}
.bb-lobby>*{position:relative;z-index:2}
.bb-title{flex:none;margin:0;text-align:center;font:900 min(10.5cqw,6.6cqh)/1.05 Georgia,serif;letter-spacing:.01em}
.bb-title span{background:linear-gradient(#fffbe0,#ffe27a 45%,#f0a12a 70%,#fff0a8);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-stroke:1.5px #6b3206;filter:drop-shadow(0 3px 0 #4a1e02) drop-shadow(0 0 14px #fff4b0aa);font-style:italic;padding:0 .1em}
.bb-title::before,.bb-title::after{content:'◆';display:inline-block;margin:0 2cqw;color:#ffd54a;font-size:.5em;vertical-align:.35em;text-shadow:0 0 8px #fff3a0,0 2px 0 #6b3206}
.bb-scene{flex:1 1 0;min-height:0;container-type:size;margin:0 -3cqw}
.bb-light{position:absolute;left:28%;top:-10%;width:44%;height:110%;background:radial-gradient(ellipse at 50% 30%,#fffbe0cc,#fff5c000 65%);filter:blur(6px);animation:bbGlow 3s ease-in-out infinite alternate}
@keyframes bbGlow{to{opacity:.55}}
.bb-deco{position:absolute}
.bb-deco img{display:block;width:100%;filter:drop-shadow(0 6px 6px #0004)}
.bb-deco .bb-crit{position:absolute;left:8%;width:84%;bottom:42%;clip-path:inset(0 0 2% 0);animation:bbBob 2.4s ease-in-out infinite;transform-origin:50% 100%}
.bb-deco.d1{left:7cqw;top:24cqh;width:min(25cqw,36cqh)}.bb-deco.d1 .bb-crit{animation-delay:-.8s}
.bb-deco.d2{left:30cqw;top:52cqh;width:min(28cqw,40cqh)}
.bb-deco.d3{left:4cqw;top:68cqh;width:min(20cqw,28cqh);opacity:.95}.bb-deco.d3 .bb-crit{animation-delay:-1.6s}
@keyframes bbBob{0%,100%{transform:translateY(6%) scaleY(.97)}50%{transform:translateY(-4%) scaleY(1.03)}}
.bb-host{position:absolute;right:4cqw;bottom:-1cqh;height:104cqh;max-width:46cqw;object-fit:contain;object-position:right bottom;filter:drop-shadow(0 0 12px #fff8) drop-shadow(0 10px 12px #0007)}
.bb-ranks,.bb-rules{border-radius:14px;background:linear-gradient(#2d5a2ee8,#1d4220f0);box-shadow:inset 0 0 0 1px #9ed08a66,0 6px 16px #0006}
.bb-mid{flex:none;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:2.4cqw;height:clamp(120px,22cqh,250px)}
.bb-ranks{display:flex;flex-direction:column;overflow:hidden;min-height:0}
.bb-ranks h2{margin:0;padding:5px 0 4px;text-align:center;background:#173a18;font:800 clamp(14px,4.2cqw,22px)/1.1 Georgia,serif;color:#ffe680}
.bb-ranks ol{flex:1;margin:0;padding:0 10px;list-style:none;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#9ed08a #0000}
.bb-ranks li{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px;padding:4px 0;border-bottom:1px solid #ffffff1c;font:700 clamp(12px,3.3cqw,17px)/1.2 Arial,sans-serif}
.bb-ranks li small{font-size:.72em;color:#a8d89a;font-weight:800}
.bb-ranks li b{color:#7dff7a}
.bb-rk{display:inline-grid;place-items:center;min-width:1.5em;height:1.5em;border-radius:4px;font-weight:900;color:#fff}
.bb-rk.r1{background:linear-gradient(#ffe27a,#e0a020);color:#5a2a00}.bb-rk.r2{background:linear-gradient(#bfe2ff,#5a9be0);color:#0c2a55}.bb-rk.r3{background:linear-gradient(#ffb0a0,#d0503a);color:#4a0c00}
.bb-ranks>p{display:flex;justify-content:space-between;margin:0;padding:5px 10px;background:#173a18;font:700 clamp(12px,3.2cqw,16px)/1.2 Arial,sans-serif}
.bb-ranks>p b{color:#7dff7a;margin-left:6px}
.bb-rules{display:flex;flex-direction:column;justify-content:center;padding:2px 12px 6px;min-height:0}
.bb-rules h2{display:flex;align-items:center;gap:10px;margin:0;font:800 clamp(14px,3.6cqw,24px)/1.2 Georgia,serif;color:#fff}
.bb-rules h2::before,.bb-rules h2::after{content:'';flex:1;height:2px;background:linear-gradient(90deg,#9ed08a00,#9ed08a)}.bb-rules h2::after{transform:scaleX(-1)}
.bb-rules p{display:flex;align-items:center;gap:8px;margin:2px 0;font:500 clamp(12px,2.9cqw,19px)/1.2 Arial,sans-serif;color:#f2ffe8}
.bb-rules p b{color:#ffe680}
.bb-crit.mini{flex:none;width:clamp(24px,5.6cqw,40px);border-radius:50%;background-color:#ffffff30;box-shadow:inset 0 0 0 2px #ffffff55}
.bb-x{display:inline-grid;place-items:center;flex:none;width:clamp(24px,5.6cqw,40px);aspect-ratio:1;border-radius:50%;background:radial-gradient(#ffe27a,#e07a1a);color:#5a1e00;font:900 clamp(11px,3cqw,16px)/1 Arial,sans-serif;font-style:normal;box-shadow:inset 0 0 0 2px #fff6}
.bb-play{flex:none;display:flex;flex-direction:column;align-items:center;gap:6px}
.bb-tries{position:relative;display:flex;align-items:center;gap:8px;margin:0;padding:3px 4px 3px 16px;border-radius:99px;background:#0b1f10cc;box-shadow:inset 0 0 0 1px #ffffff2a;font:700 clamp(14px,3.8cqw,20px)/1 Arial,sans-serif}
.bb-tries b{color:#7dff7a}
html body #stage #main .bb-room button.bb-plus{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:radial-gradient(circle at 40% 35%,#fff,#cfe9ff 55%,#7aa8d8);color:#1d3a6a;font:900 22px/1 Arial,sans-serif;box-shadow:inset 0 0 0 2px #fff,0 2px 4px #0006}
html body #stage #main .bb-room button.bb-go{position:relative;width:min(56cqw,240px);height:min(15cqw,64px);padding-bottom:3px;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat;color:#5a2a06;font:900 min(7cqw,28px)/1 Georgia,serif;text-shadow:0 1px 0 #fff6;filter:drop-shadow(0 4px 6px #0007);animation:bbPulse 1.6s ease-in-out infinite}
html body #stage #main .bb-room button.bb-go:active{transform:scale(.95)}
@keyframes bbPulse{50%{transform:scale(1.04)}}
.bb-prac{font:600 12px/1 Arial,sans-serif;color:#d8f5c8}
.bb-tools{flex:none;display:flex;justify-content:flex-end;gap:10px;min-height:min(13cqw,64px)}
html body #stage #main .bb-room .bb-tools button{position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;width:min(19cqw,92px)}
.bb-tool{display:grid;place-items:center;width:min(11cqw,50px);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 40% 35%,#4f8a9e,#1d4a5e);box-shadow:inset 0 0 0 2px #bfe8f0aa,0 3px 6px #0007;overflow:hidden}
.bb-tool .bb-crit{width:88%}
.bb-tool img{width:78%;height:78%;object-fit:contain}
.bb-tool .bag-ico{width:80%;height:80%}
.bb-tools span:last-child{font:800 clamp(10.5px,2.8cqw,14px)/1.05 Arial,sans-serif;text-align:center;text-shadow:0 1px 2px #000,0 0 4px #000}
html body #stage #main .bb-lobby button.bb-back{position:absolute;left:3cqw;bottom:1.4cqh;width:min(13cqw,60px);height:min(13cqw,60px)}
/* Run */
.bb-run{background-position:center 0}
.bb-top{position:absolute;top:1.2cqh;left:4cqw;right:4cqw;z-index:6;text-align:center}
.bb-plate{display:inline-block;margin:0 0 .8cqh;padding:.6cqh 9cqw;background:linear-gradient(90deg,#1d5a7000,#1d5a70dd 18%,#1d5a70dd 82%,#1d5a7000);border-top:1px solid #bfe8f0aa;border-bottom:1px solid #bfe8f0aa;font:800 min(6.4cqw,4.2cqh)/1.1 Georgia,serif;color:#fff;text-shadow:0 2px 0 #0a2a38,0 0 10px #8fdcff}
.bb-bar{position:relative;height:min(4.6cqw,2.9cqh);border-radius:6px;background:#1a3a3add;box-shadow:inset 0 0 0 2px #0a2a2a,0 2px 4px #0005;overflow:hidden}
.bb-bar i{position:absolute;inset:0 auto 0 0;background:repeating-linear-gradient(115deg,#9cf05a 0 14px,#b8f86a 14px 28px);box-shadow:inset 0 2px 0 #ffffff66;transition:width .2s linear}
.bb-bar.low i{background:repeating-linear-gradient(115deg,#ff7a4a 0 14px,#ffa05a 14px 28px);animation:bbBlink .5s steps(2) infinite}
@keyframes bbBlink{50%{opacity:.6}}
.bb-bar b{position:relative;display:block;font:800 min(3.8cqw,2.4cqh)/min(4.6cqw,2.9cqh) Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #000}
.bb-hud{position:absolute;top:13cqh;left:4cqw;right:4cqw;z-index:7;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}
.bb-hud>*{pointer-events:auto}
.bb-left{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:.8cqh}
.bb-pts{min-width:min(34cqw,22cqh);padding:.6cqh 3cqw;border-radius:12px;background:linear-gradient(#3a6a86,#1d4058);box-shadow:inset 0 0 0 2px #bfe8f0,inset 0 0 0 4px #1d4058,0 3px 8px #0006;text-align:center}
.bb-pts small{display:block;font:700 min(3.6cqw,2.3cqh)/1.1 Arial,sans-serif;color:#fff}
.bb-pts b{display:block;font:900 min(6.5cqw,4.2cqh)/1.05 Georgia,serif;color:#ffcf5a;text-shadow:0 2px 0 #6b3206}
.bb-combo{position:absolute;left:44%;top:1cqh;transform:translateX(-50%);z-index:2;white-space:nowrap;font:900 min(4.6cqw,3.2cqh)/1 Georgia,serif;color:#ffe680;-webkit-text-stroke:1px #6b3206;text-shadow:0 2px 0 #6b3206,0 0 10px #fff3a0}
.bb-combo b{font-size:1.25em}.bb-combo i{color:#ff9a3a;font-style:normal}
.bb-combo.pop{animation:bbComboPop .35s cubic-bezier(.3,1.8,.5,1)}
@keyframes bbComboPop{from{transform:translateX(-50%) scale(1.5)}}
html body #stage #main .bb-room button.bb-sr{position:relative;padding:.6cqh 3cqw;border-radius:99px;background:#183044e6;box-shadow:inset 0 0 0 1px #bfe8f066;font:800 min(3.6cqw,2.3cqh)/1.1 Arial,sans-serif}
.bb-sr i{display:inline-block;font-style:normal;color:#8fdcff;transition:transform .2s}.bb-left.open .bb-sr i{transform:rotate(180deg)}
.bb-srl{display:none;padding:1cqh 2.5cqw;border-radius:12px;background:#152a3ae8;box-shadow:0 4px 10px #0007}
.bb-left.open .bb-srl{display:block}
.bb-srl p{display:flex;align-items:center;gap:1.5cqw;margin:.5cqh 0;font:800 min(3.6cqw,2.3cqh)/1.1 Arial,sans-serif;color:#7dff7a}
.bb-srl p.bad{color:#ff7a7a}.bb-srl .bb-crit.mini{width:min(8cqw,5cqh)}
.bb-srl p .bb-crit.mini+.bb-crit.mini{margin-left:-3cqw}
.bb-top3{padding:.6cqh 2.6cqw;border-radius:10px;background:#18262ee6;box-shadow:inset 0 0 0 1px #ffffff22,0 3px 8px #0006}
