.bb-top3 p:last-child{border:0}.bb-top3 b{color:#7dff7a}
.bb-field{position:absolute;z-index:1;left:2cqw;right:2cqw;top:31cqh;bottom:.5cqh;container-type:size;touch-action:none}
.bb-field.shake{animation:bbShake .38s}
@keyframes bbShake{20%{transform:translate(-8px,3px)}40%{transform:translate(7px,-3px)}60%{transform:translate(-5px,2px)}80%{transform:translate(3px,-1px)}}
.bb-hole{position:absolute;left:calc(var(--x)*1%);top:calc(var(--y)*1%);width:min(30cqw,26cqh);transform:translate(-50%,-50%);aspect-ratio:320/195;cursor:pointer}
.bb-hole img{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;-webkit-user-drag:none}
.bb-hole .bb-back{filter:drop-shadow(0 5px 4px #0003)}
.bb-hole .bb-front{z-index:2}
/* The critter shows above the opening's centre line and inside the opening's lower half-ellipse (burrow-hole:
   opening x 14.7-82.5 %, y 13.8-78.5 %); the front lip (burrow-rim) is drawn over it. */
.bb-pit{position:absolute;left:-20%;width:140%;bottom:21.5%;height:300%;z-index:1;-webkit-mask:linear-gradient(#000,#000) top/100% 89.2% no-repeat,radial-gradient(closest-side,#000 97%,#0000) 48.1% 100%/48.4% 21.6% no-repeat;mask:linear-gradient(#000,#000) top/100% 89.2% no-repeat,radial-gradient(closest-side,#000 97%,#0000) 48.1% 100%/48.4% 21.6% no-repeat;pointer-events:none}
.bb-pit .bb-crit{position:absolute;left:19.7%;width:58.6%;bottom:0;transform:translateY(104%);transition:transform .14s ease-in;will-change:transform}
.bb-pit .bb-crit.up{transform:translateY(14%);transition:transform .18s cubic-bezier(.3,1.6,.55,1)}
.bb-pit .bb-crit.tapped{animation:bbTap .3s ease-out forwards}
.bb-pit .bb-crit.struck{animation:bbStruck .3s ease-out forwards}
@keyframes bbTap{0%{transform:translateY(14%) scale(1.12,.86);filter:brightness(2.2)}60%{transform:translateY(17%) scale(.92,1.08);filter:brightness(1.3)}100%{transform:translateY(104%) scale(.9);filter:none}}
@keyframes bbStruck{0%{transform:translateY(14%) scale(1.1);filter:brightness(2) hue-rotate(-30deg)}100%{transform:translateY(104%);filter:none}}
.bb-fx{position:absolute;left:50%;top:-30%;width:150%;aspect-ratio:1;transform:translate(-50%,-50%) scale(.3);background:var(--bb-fx) 0 0/200% 200% no-repeat;pointer-events:none;z-index:4;animation:bbFx .55s ease-out forwards}
.bb-fx.f1{background-position:100% 0}.bb-fx.f2{background-position:0 100%}.bb-fx.f3{background-position:100% 100%}
.bb-fx.big{width:230%;animation-duration:.75s}
.bb-fx.ice{filter:hue-rotate(160deg) saturate(1.4)}
@keyframes bbFx{0%{opacity:1;transform:translate(-50%,-50%) scale(.3)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.25)}}
.bb-float{position:absolute;left:50%;top:-40%;z-index:6;pointer-events:none;white-space:nowrap;font:900 min(7.5cqw,5cqh)/1 Georgia,serif;color:#fff;-webkit-text-stroke:1.5px #2a6a1a;text-shadow:0 3px 0 #1e4a12,0 0 12px #c8ff9a;animation:bbFloat .9s ease-out forwards}
.bb-float.gold{color:#ffe27a;-webkit-text-stroke-color:#7a3a06;text-shadow:0 3px 0 #5a2a00,0 0 16px #ffd76a;font-size:min(10cqw,6.6cqh)}
.bb-float.time{color:#9ff0ff;-webkit-text-stroke-color:#0a4a6a;text-shadow:0 3px 0 #063048,0 0 12px #8fdcff}
.bb-float.bad{color:#d8f6ff;-webkit-text-stroke-color:#1a4a8a;text-shadow:0 3px 0 #0a2a5a,0 0 14px #8fdcff}
@keyframes bbFloat{0%{opacity:0;transform:translate(-50%,10%) scale(.4)}18%{opacity:1;transform:translate(-50%,-20%) scale(1.15)}30%{transform:translate(-50%,-30%) scale(1)}100%{opacity:0;transform:translate(-50%,-140%)}}
.bb-banner{position:absolute;left:0;right:0;top:34cqh;z-index:12;display:grid;place-items:center;pointer-events:none;opacity:0;transform:scale(.6);transition:opacity .2s,transform .25s cubic-bezier(.3,1.6,.5,1)}
.bb-banner.show{opacity:1;transform:none}
.bb-banner span{padding:1.4cqh 12cqw;background:linear-gradient(90deg,#c03a1200,#d24a18ee 20%,#e8682a 50%,#d24a18ee 80%,#c03a1200);border-top:2px solid #ffd27a;border-bottom:2px solid #ffd27a;font:900 min(7cqw,4.6cqh)/1 Georgia,serif;color:#ffe680;-webkit-text-stroke:1px #6b1e02;text-shadow:0 3px 0 #6b1e02,0 0 14px #ffd27a}
.bb-banner.up span{background:linear-gradient(90deg,#2a8a1200,#2a9a2aee 20%,#46b83a 50%,#2a9a2aee 80%,#2a8a1200)}
.bb-banner.lost span{background:linear-gradient(90deg,#2a4a9a00,#2a5aaaee 20%,#4a7ad0 50%,#2a5aaaee 80%,#2a4a9a00);color:#e0f4ff}
.bb-cd{display:grid;place-items:center;width:min(30cqw,19cqh);aspect-ratio:1;border-radius:50%;background:radial-gradient(#ffe27a,#e8682a 70%,#a02a08);box-shadow:0 0 0 4px #fff3,0 0 30px #ffd27a;font:900 min(18cqw,12cqh)/1 Georgia,serif;color:#fff;-webkit-text-stroke:2px #6b1e02;text-shadow:0 4px 0 #6b1e02;animation:bbCd .65s ease-out}
@keyframes bbCd{from{transform:scale(1.6);opacity:0}}
.bb-frost{position:absolute;inset:0;z-index:10;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1cqh;pointer-events:none;opacity:0;transition:opacity .25s;background:var(--bb-frost) center/100% 100% no-repeat,radial-gradient(ellipse at center,#bfefff33,#7ad0f088 70%)}
.bb-frost.on{opacity:1;pointer-events:auto}
.bb-frost b{font:900 min(11cqw,7cqh)/1 Georgia,serif;color:#e8fbff;-webkit-text-stroke:1.5px #1a5a9a;text-shadow:0 4px 0 #0a3a6a,0 0 20px #8fdcff}
.bb-frost small{font:800 min(5cqw,3.2cqh)/1 Arial,sans-serif;color:#fff;text-shadow:0 2px 3px #0a3a6a}
.bb-practice{position:absolute;right:4cqw;bottom:2cqh;z-index:8;margin:0;padding:.5cqh 3cqw;border-radius:99px;background:#0008;font:800 min(3.4cqw,2.2cqh)/1 Arial,sans-serif;color:#ffe680}
/* Pop-ups */
#stage #modal.den-pop:has(.bb-pop){padding:0!important;background:#f8f1e2!important;border:0!important;border-radius:16px!important;box-shadow:0 0 0 3px #d8b47a,0 20px 50px #0009!important;overflow:hidden!important;max-width:min(440px,94vw)!important}
#stage #modal.den-pop:has(.bb-pop)>.dialog-dismiss{display:none!important}
.bb-pop{display:flex;flex-direction:column;max-height:min(74dvh,640px);color:#4a3a2a;text-align:left}
