html body #stage #main .tl-room button>svg:first-child{display:none}
.tl-top{flex:none;position:relative;z-index:5;display:flex;align-items:center;gap:2cqw;padding:max(8px,env(safe-area-inset-top)) 3cqw 4px}
html body #stage #main .tl-room button.tl-back{width:min(12cqw,54px);height:min(12cqw,54px);flex:none}
.tl-ribbon{display:flex;align-items:center;gap:6px;padding:5px 22px 5px 14px;background:linear-gradient(90deg,#2a8ad8,#1a5aa8 70%,#1a5aa800);clip-path:polygon(0 0,100% 0,88% 100%,0 100%);font:800 min(6cqw,26px)/1 Georgia,serif;text-shadow:0 2px 0 #0a2a5a}
