.tl-bar p b{color:#ffe27a}.tl-bar p b.on{color:#7dff7a}
html body #stage #main .tl-room button.tl-reset{position:absolute;right:3cqw;display:flex;flex-direction:column;align-items:center;font:700 min(2.8cqw,12px)/1 Arial,sans-serif;text-shadow:0 1px 2px #000}
.tl-reset i{display:grid;place-items:center;width:min(8cqw,34px);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 40% 35%,#fff,#bfd8ff 60%,#6a8ad8);color:#1a3a8a;font:900 min(5cqw,22px)/1 Arial,sans-serif;font-style:normal;margin-bottom:2px}
/* Overview */
.tl-over{position:relative;flex:1;min-height:0}
.tl-rule{position:absolute;top:1cqh;left:6cqw;right:6cqw;margin:0;text-align:center;font:700 min(3.6cqw,16px)/1.3 Arial,sans-serif;text-shadow:0 1px 3px #000}
