.tl-card{position:absolute;left:50%;transform:translateX(-50%);z-index:10;width:min(84cqw,440px);padding:12px 14px 12px;border-radius:14px;background:linear-gradient(#1a2a5aee,#0e1840f4);box-shadow:inset 0 0 0 1.5px #8fb8ff88,0 10px 30px #000c;animation:tlCard .18s ease-out}
.tl-card.down{bottom:3%}.tl-card.up{top:2%}
