.tt-plate::before{content:'';position:absolute;left:4%;right:4%;bottom:-.05em;height:.62em;border-radius:50%;background:radial-gradient(ellipse,var(--tglow),transparent 70%);opacity:.7}
.tt-plate.big{font-size:min(7.4cqw,34px);flex:none}
.tt-flame{--tg:linear-gradient(#fff6b0,#ffc23a 45%,#ff6a1a);--tglow:#ff7a2a}
.tt-rose{--tg:linear-gradient(#fff0f6,#ff9ccf 50%,#e0408a);--tglow:#ff6ab0}
.tt-tide{--tg:linear-gradient(#f0ffff,#7fe6ff 50%,#1b9bd8);--tglow:#4fd0ff}
.tt-gold{--tg:linear-gradient(#fffbe0,#ffe066 45%,#d99a1a);--tglow:#ffd24a}
.tt-star{--tg:linear-gradient(#ffffff,#d8c4ff 45%,#8a5cff);--tglow:#a98bff}
.tt-frost{--tg:linear-gradient(#ffffff,#bfe9ff 45%,#5aa8ff);--tglow:#7fc8ff}
.tt-leaf{--tg:linear-gradient(#fbffe6,#bff27a 45%,#4fb43a);--tglow:#8fe36a}
.tt-frost b,.tt-tide b,.tt-star b{-webkit-text-stroke-color:#0b2a5a}.tt-leaf b{-webkit-text-stroke-color:#1c3a0a}.tt-rose b{-webkit-text-stroke-color:#4a0a2a}
