/* ===== Challenge chapter map (2026-11-27, user photos of the reference's stage map) ===== */
body[data-screen=cityExplore] #stage{width:min(100%,86dvh)!important;max-width:none!important}
body[data-screen=cityExplore] #stage>:is(header,nav,footer),body[data-screen=cityExplore] .return-to-menu{display:none!important}
body[data-screen=cityExplore] #stage>#main{inset:0!important;width:100%;height:100%;padding:0!important;display:block;overflow:hidden}
#stage .ch-room{position:relative;width:100%;height:100%;overflow:hidden;container-type:size;background:#cfe6f4;color:#3a3020;font-family:Arial,sans-serif}
#stage .ch-scroll{position:absolute;inset:0;overflow-y:auto;overflow-x:hidden;scrollbar-width:none;-webkit-overflow-scrolling:touch}
#stage .ch-scroll::-webkit-scrollbar{display:none}
#stage .ch-map{position:relative;width:100%;aspect-ratio:2/3;min-height:100%;background:var(--chbg) center/100% 100% no-repeat}
#stage #main .ch-mark{position:absolute;transform:translate(-50%,-86%);width:min(13cqw,92px);min-width:0;min-height:0;margin:0;padding:0;border:0!important;background:none!important;box-shadow:none!important;display:grid;justify-items:center;cursor:pointer}
#stage #main .ch-mark::before,#stage #main .ch-mark::after{content:none!important}
#stage .ch-mark img{width:62%;height:auto;filter:drop-shadow(0 4px 4px #0004)}
#stage .ch-mark.boss img{width:78%}#stage .ch-mark.gate img{width:96%}
#stage .ch-mark b{margin-top:-4px;padding:2px 10px;border-radius:999px;background:linear-gradient(#fffaf0,#f3e1b8);border:1.5px solid #d8b064;font:900 min(3.2cqw,15px)/1.2 Georgia,serif;color:#7a4a0e;white-space:nowrap;box-shadow:0 2px 4px #0003;text-shadow:none}
#stage .ch-mark.done b{background:linear-gradient(#f4fff0,#d6f0c8);border-color:#8cc47a;color:#2e7a3a}
#stage .ch-mark.done img{filter:saturate(.6) brightness(1.05) drop-shadow(0 3px 3px #0003)}
#stage .ch-mark.now img{animation:ch-bob 1.6s ease-in-out infinite}
#stage .ch-mark.now b{background:linear-gradient(#fff3b0,#ffc94a);border-color:#f0a020;color:#5a2a06}
@keyframes ch-bob{50%{transform:translateY(-6%)}}
#stage .ch-hero{position:absolute;width:min(13cqw,96px);transform:translate(-50%,-92%);filter:drop-shadow(0 6px 4px #0004);pointer-events:none;animation:ch-hop 2.2s ease-in-out infinite}
@keyframes ch-hop{50%{transform:translate(-50%,-97%)}}
#stage .ch-title{position:absolute;left:50%;top:max(8px,1.2cqh);transform:translateX(-50%);display:grid;justify-items:center;padding:4px 18px;border-radius:999px;background:#fffbf0d9;border:1px solid #e8cf94;box-shadow:0 2px 8px #0002;pointer-events:none}
#stage .ch-title b{font:900 min(4.4cqw,20px)/1.1 Georgia,serif;color:#7a4a0e}#stage .ch-title small{font:700 min(2.8cqw,12px)/1.2 Arial,sans-serif;color:#6a5a40}
#stage .ch-benefit{position:absolute;left:2cqw;top:52cqh;display:grid;gap:2px;padding:7px 10px;border-radius:12px;background:#fffbf0e0;border:1px solid #e8cf94;box-shadow:0 3px 10px #0002;font:700 min(2.9cqw,13px)/1.25 Arial,sans-serif;color:#4a3a2a;max-width:34cqw}
#stage .ch-benefit>b{font:900 min(3.2cqw,14px)/1.2 Georgia,serif;color:#b0611b}
#stage .ch-benefit span{display:flex;align-items:center;gap:5px;color:#2e7a3a}
#stage .ch-benefit span :is(img,.gpt-icon){width:18px;height:18px}
#stage .ch-benefit span i,#stage .ch-exp i{font:900 9px/1 Arial,sans-serif;font-style:normal;padding:3px 4px;border-radius:5px;background:linear-gradient(#5ac8f0,#2a7ab0);color:#fff}
#stage .ch-benefit small{font-size:min(2.5cqw,11px);color:#7a6a50}
#stage .ch-left{position:absolute;left:1.5cqw;bottom:calc(14cqh + 10px);display:grid;justify-items:center;gap:4px}
#stage .ch-exp{display:flex;align-items:center;gap:4px;padding:2px 8px 2px 3px;border-radius:999px;background:#fffbf0e0;border:1px solid #9fd0e8;font:900 12px/1 Arial,sans-serif;color:#2a7ab0}
#stage .ch-tools{position:absolute;right:1.5cqw;top:34cqh;display:grid;gap:min(1.4cqh,10px);justify-items:center}
#stage #main button.ch-tool{position:relative;display:grid;justify-items:center;gap:1px;width:min(17cqw,92px);min-width:0;min-height:0;margin:0;padding:0;border:0!important;background:none!important;box-shadow:none!important;cursor:pointer}
#stage #main button.ch-tool::before,#stage #main button.ch-tool::after{content:none!important}
#stage .ch-tool img{width:min(11cqw,60px);height:min(11cqw,60px);object-fit:contain;filter:drop-shadow(0 3px 4px #0004)}
#stage .ch-tool.ch-chest img{width:min(14cqw,76px);height:min(14cqw,76px)}
#stage .ch-tool small{font:800 min(2.7cqw,12px)/1.1 Arial,sans-serif;color:#fff;text-align:center;text-shadow:0 1px 2px #3a2a50,0 0 3px #3a2a50,0 0 1px #000}
#stage .ch-tool em{position:absolute;top:2px;right:14%;width:12px;height:12px;border-radius:50%;background:#ff3a3a;box-shadow:0 0 0 2px #fff}
#stage .ch-foot{position:absolute;left:0;right:0;bottom:0;display:grid;grid-template-columns:auto 1fr auto;align-items:end;gap:8px;padding:30px 2.5cqw max(10px,env(safe-area-inset-bottom));background:linear-gradient(#fff0,#fffaf0d0 45%,#fff8eaf0)}
#stage .ch-go{display:grid;justify-items:center;gap:4px}
#stage #main button.ch-explore{position:relative;width:min(48cqw,250px);height:min(15cqw,74px);min-height:0;margin:0;padding:0 0 3px;border:0!important;border-radius:40px;box-shadow:none!important;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat!important;color:#5a2a06!important;text-shadow:0 1px 0 #fff6c8!important;font:900 min(6cqw,28px)/1 Georgia,serif;cursor:pointer}
#stage #main button.ch-explore::before,#stage #main button.ch-explore::after{content:none!important}
#stage .ch-explore i{position:absolute;right:-4%;top:-28%;padding:3px 10px;border-radius:10px 10px 10px 2px;background:linear-gradient(#8ee07a,#3fae5a);color:#fff;font:italic 900 min(2.8cqw,13px)/1.2 Arial,sans-serif;text-shadow:0 1px 1px #1a5a2a;transform:rotate(-6deg)}
#stage .ch-go small{font:700 min(3cqw,14px)/1.2 Arial,sans-serif;color:#4a3a2a}
#stage .ch-go small.low b{color:#d0402a}#stage .ch-go small.ok{color:#2e7a3a}
#stage .ch-right{display:grid;justify-items:center;gap:4px}
#stage .ch-skip{display:flex;align-items:center;gap:5px;font:800 13px/1 Arial,sans-serif;color:#4a3a2a}
#stage .ch-skip input{width:18px;height:18px;accent-color:#3fae5a}
/* fight */
#stage .ch-fight{background:var(--chbg) center/cover}
#stage .ch-fight::before{content:'';position:absolute;inset:0;background:linear-gradient(#fff6,#fff0 40%,#fff3);backdrop-filter:blur(2px)}
#stage .ch-hp{position:absolute;left:50%;top:11cqh;transform:translateX(-50%);width:60%;height:14px;border-radius:8px;background:#fff8;border:2px solid #fff;box-shadow:0 2px 6px #0003;overflow:hidden}
#stage .ch-hp i{display:block;height:100%;background:linear-gradient(90deg,#ff8a5c,#e2374a);transition:width .16s linear}
#stage .ch-foe{position:absolute;right:4%;top:22cqh;width:min(56cqw,420px);filter:drop-shadow(0 8px 8px #0004)}
#stage .ch-foe.hit{animation:ch-hit .22s}
@keyframes ch-hit{40%{transform:translateX(3%) scale(.97);filter:brightness(1.8) drop-shadow(0 8px 8px #0004)}}
#stage .ch-me{position:absolute;left:4%;bottom:6cqh;height:min(62cqh,560px);filter:drop-shadow(0 8px 8px #0004)}
#stage .ch-nums b{position:absolute;font:900 min(6cqw,30px)/1 Georgia,serif;color:#fff;-webkit-text-stroke:1.5px #a8301a;text-shadow:0 2px 4px #0005;animation:ch-num .9s ease-out forwards;pointer-events:none}
@keyframes ch-num{from{transform:scale(.6);opacity:0}20%{transform:scale(1.15);opacity:1}to{transform:translateY(-40px);opacity:0}}
/* pop-ups */
#stage #modal.bw-pop .ch-pop{font:500 14px/1.4 Arial,sans-serif;text-align:left}
#stage #modal.bw-pop .ch-pop h2{margin:0 36px 6px 0;color:#7a4a0e;font:900 20px/1.1 Georgia,serif}
#stage #modal.bw-pop .ch-pop p{font:500 13px/1.4 Arial,sans-serif!important;color:#4a4030!important;margin:4px 0 8px}
#stage #modal.bw-pop .ch-pop b{color:#2e7a3a}
#stage #modal.bw-pop .ch-pop .ch-sub{font-weight:800!important;color:#7a4a0e!important}
#stage #modal.bw-pop .ch-pop .bag-gains{display:flex;flex-wrap:wrap;gap:6px}
#stage #modal.bw-pop button.ch-btn{display:block;margin:10px auto 0;min-height:0;height:52px;padding:0 26px 3px;border:0!important;border-radius:28px;box-shadow:none!important;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat!important;color:#5a2a06!important;text-shadow:0 1px 0 #fff6c8!important;font:900 17px/1 Georgia,serif}
#stage #modal.bw-pop button.ch-btn:disabled{filter:saturate(.3);opacity:.7}
#stage #modal.bw-pop :is(button.ch-btn,button.ch-mini)::before,#stage #modal.bw-pop :is(button.ch-btn,button.ch-mini)::after{content:none!important}
#stage #modal.bw-pop button.ch-mini{min-height:0;height:32px;margin:0;padding:0 14px;border-radius:10px;border:1px solid #6aa8e0!important;background:linear-gradient(#e6f4ff,#a9d6ff)!important;color:#1f4f88!important;font:800 14px/1 Arial,sans-serif;box-shadow:0 2px 4px #4a80b040!important;text-shadow:none!important}
#stage #modal.bw-pop .ch-task{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:6px 0;padding:8px 10px;border-radius:12px;background:#fffdf6;border:1px solid #ecd9a6}
#stage #modal.bw-pop .ch-task span{display:grid}#stage #modal.bw-pop .ch-task small{color:#7a6a50;font-size:12px}
#stage #modal.bw-pop .ch-task b{color:#4a3a2a}
#stage #modal.bw-pop .ch-task em{font-style:normal;font-size:12px;color:#9a8a6a}
#stage #modal.bw-pop .ch-got{font-style:normal;font-weight:900;color:#2e8a3a;font-size:18px}
#stage #modal.bw-pop .ch-lock{font-style:normal;opacity:.6}
#stage #modal.bw-pop .ch-pop.wide{min-width:min(400px,80vw)}
#stage #modal.bw-pop .ch-phead,#stage #modal.bw-pop .ch-prow{display:grid;grid-template-columns:76px 1fr 1fr;gap:6px;align-items:center}
#stage #modal.bw-pop .ch-phead span{font:800 12px/1 Arial,sans-serif;color:#7a4a0e;text-align:center}
#stage #modal.bw-pop .ch-plist{display:grid;gap:6px;max-height:46dvh;overflow:auto}
#stage #modal.bw-pop .ch-prow{padding:6px;border-radius:12px;background:#f6f2ea;border:1px solid #e6dcc8;opacity:.75}
#stage #modal.bw-pop .ch-prow.open{background:#fffdf6;border-color:#ecd9a6;opacity:1}
#stage #modal.bw-pop .ch-prow>b{font:800 12px/1.2 Arial,sans-serif;color:#4a3a2a}
#stage #modal.bw-pop .ch-cell{display:flex;flex-wrap:wrap;gap:4px;align-items:center;justify-content:center}
#stage #modal.bw-pop .ch-cell.pass{background:#f6eefe;border-radius:10px;padding:3px}
#stage #modal.bw-pop .ch-cell .bag-gain{transform:scale(.8);margin:-4px}
#stage #main :is(.ch-mark,button.ch-tool,button.ch-explore,.ch-foot button){outline:0!important}
#stage .ch-scroll{padding-bottom:17cqh;box-sizing:border-box}
#stage .ch-map{min-height:0}
#stage .ch-exp b{color:#2a7ab0}
#stage .ch-tools{top:30cqh;gap:min(1cqh,8px)}
#stage .ch-tool img{width:min(11cqw,7cqh);height:min(11cqw,7cqh)}
#stage .ch-tool.ch-chest img{width:min(14cqw,9cqh);height:min(14cqw,9cqh)}
#stage .ch-tool small{font-size:min(2.7cqw,1.7cqh,12px)}
#stage .ch-left{bottom:calc(16cqh + 8px)}
#stage .ch-left .ch-tool img{width:min(11cqw,7cqh);height:min(11cqw,7cqh)}
#stage .ch-right .ch-tool img{width:min(10cqw,6.5cqh);height:min(10cqw,6.5cqh)}
#stage .ch-benefit{top:auto;bottom:calc(30cqh + 8px)}
#stage .ch-tools{top:20cqh}
#stage .ch-tool img{width:min(11cqw,6.2cqh);height:min(11cqw,6.2cqh)}
#stage .ch-tool.ch-chest img{width:min(14cqw,8.5cqh);height:min(14cqw,8.5cqh)}
#stage .ch-benefit{top:calc(max(8px,1.2cqh) + 50px);bottom:auto;max-width:30cqw}
#stage #modal.bw-pop .ch-cell .bag-gain{transform:none;margin:0;width:50px;min-width:0;min-height:0;padding:3px 2px;gap:0}
#stage #modal.bw-pop .ch-cell .bag-gain small{display:none}
#stage #modal.bw-pop .ch-cell .bag-gain :is(img,i.bag-ico,.gpt-icon){width:32px!important;height:32px!important}
#stage #modal.bw-pop .ch-cell .bag-gain b{font-size:11px}
#stage #modal.bw-pop .ch-cell{flex-wrap:nowrap;gap:3px}
#stage #modal.bw-pop .ch-phead,#stage #modal.bw-pop .ch-prow{grid-template-columns:62px auto 1fr}
/* no white band at the bottom of the Challenge map (user: "why this white field") */
#stage .ch-foot{background:none;padding-top:10px}
#stage .ch-go small{padding:3px 12px;border-radius:999px;background:#fffbf0d9;border:1px solid #e8cf94;box-shadow:0 2px 6px #0002}
#stage .ch-skip{padding:4px 10px;border-radius:999px;background:#fffbf0d9;border:1px solid #e8cf94}
#stage .ch-right .ch-tool small,#stage .ch-left .ch-tool small{text-shadow:0 1px 2px #3a2a50,0 0 3px #3a2a50,0 0 1px #000}
#stage .ch-scroll{padding-bottom:0}
#stage label.ch-skip{width:auto;height:auto;min-width:0;min-height:0;padding:5px 12px;border-radius:999px;aspect-ratio:auto}
#stage .ch-scroll{padding-bottom:15cqh}
#stage .ch-map::after{content:'';position:absolute;top:100%;left:0;right:0;height:15cqh;background:var(--chbg) center bottom/100% calc(100cqw * 1.5) no-repeat;transform:scaleY(-1);pointer-events:none}
#stage #main .ch-skip input{width:18px!important;height:18px!important;min-height:0!important;padding:0!important;margin:0!important;background:#fff!important;border:1px solid #b8a070!important;appearance:auto;-webkit-appearance:checkbox;flex:none}
/* the map ends at its own bottom edge: no extra strip under it (user: "this field") */
#stage .ch-scroll{padding-bottom:0!important}
#stage .ch-map::after{content:none!important}
#stage .ch-room{background:none}
/* profile plate: name, power and XP bar stacked, nothing crosses (user photo 2026-11-27) */
html body #stage .city-hud .pf2 .pf2-band{top:31%;height:38%;justify-content:center;gap:1px;padding:0 5% 0 4%}
html body #stage .city-hud .pf2 .pf2-band b{font-size:clamp(9px,2cqw,18px)}
html body #stage .city-hud .pf2 .pf2-band>span{font-size:clamp(8px,1.75cqw,15px);line-height:1}
html body #stage .city-hud .pf2 .pf2-band>span i{font-family:"Segoe UI Symbol","Apple Symbols",Arial,sans-serif;color:#ffd24a}
html body #stage .city-hud .pf2 .pf2-xp{position:static;display:block;width:88%;height:clamp(3px,.5cqw,5px);margin-top:2px;border-radius:3px;background:#ffffff30;box-shadow:inset 0 0 0 1px #0004}
html body #stage .city-hud .pf2 .pf2-band{top:33%;height:35%}
/* Prize tiles everywhere: light, no dark box (user: "no black frames") */
.bag-gain{--rarity:#e2c47a;border:1.5px solid color-mix(in srgb,var(--rarity) 70%,#fff)!important;background:radial-gradient(circle at 50% 32%,#fff,color-mix(in srgb,var(--rarity) 22%,#fffaf0))!important;box-shadow:0 2px 6px #8a6a4a22}
.bag-gain b{color:#2e7a3a!important;text-shadow:none!important}
.bag-gain small{color:#5a4a30!important;text-shadow:none!important}
/* Shared result window: light card instead of the dark violet box (user: "no black frames") */
.wr-end{background:radial-gradient(ellipse at 50% 40%,#fff8e8cc,#3a2a5a99 75%)}
.wr-card{background:linear-gradient(170deg,#fffdf6,#fbf3ff 55%,#f3e8ff)!important;box-shadow:0 0 0 2.5px #e2c47a,0 0 40px #ffd76a88,0 18px 40px #3a2a5a55!important;color:#3a2a20}
.wr-kicker{color:#9a5a12;text-shadow:none}
.wr-score small{color:#8a6ab0}
.wr-score b{filter:drop-shadow(0 2px 0 #b0702a)}
#resultCard .wr-body .wr-note,#resultCard .wr-body p{color:#5a4a30;text-shadow:none}
#resultCard .wr-body{color:#3a2a20}
/* Home Claim / Power Up pop-overs (user photos 2026-11-27); light cards, no dark frame */
.hm-pop{position:absolute;z-index:40;width:min(46cqw,300px);padding:8px 8px 10px;border-radius:16px;background:linear-gradient(#fffdf6f5,#f6ecd8f5);border:1.5px solid #e2c47a;box-shadow:0 10px 30px #3a2a5a55;animation:hm-in .16s ease-out}
@keyframes hm-in{from{opacity:0;transform:translateY(8px) scale(.96)}}
.hm-head{display:block;text-align:center;margin:0 0 6px;font:900 min(4.2cqw,20px)/1.2 Georgia,serif;color:#7a4a0e}
.hm-list{display:grid;gap:5px;max-height:44cqh;overflow:auto}
html body #stage .hm-pop button.hm-row{position:relative;display:block;width:100%;min-height:0;height:auto;margin:0;padding:8px 10px;border-radius:10px;border:1px solid #e6d3a6!important;background:linear-gradient(#fffaf0,#f1e4c6)!important;box-shadow:0 1px 3px #8a6a4a26!important;color:#6a4520!important;text-shadow:none!important;font:800 min(3.2cqw,15px)/1.2 Arial,sans-serif;text-align:center;cursor:pointer}
html body #stage .hm-pop button.hm-row::before,html body #stage .hm-pop button.hm-row::after{content:none!important}
html body #stage .hm-pop button.hm-row:active{filter:brightness(.95);transform:scale(.98)}
.hm-row i{position:absolute;right:8px;top:50%;width:9px;height:9px;margin-top:-5px;border-radius:50%;background:#ff3a3a;box-shadow:0 0 0 2px #fff}
.hm-none{margin:6px 0;text-align:center;font:600 13px/1.3 Arial,sans-serif;color:#7a6a50}
html body #stage .hm-pop button.hm-boss{position:relative;display:flex;align-items:center;justify-content:space-between;width:100%;height:min(12cqw,58px);min-height:0;margin:8px 0 0;padding:0 6px 0 14px;border-radius:12px;border:1.5px solid #fff!important;background:linear-gradient(90deg,#5a8ef0,#8ec4ff)!important;box-shadow:0 3px 8px #2a5ab055!important;color:#fff!important;font:900 min(4cqw,19px)/1 Georgia,serif;text-shadow:0 1px 2px #1a3a80!important;overflow:hidden;cursor:pointer}
html body #stage .hm-pop button.hm-boss::before,html body #stage .hm-pop button.hm-boss::after{content:none!important}
.hm-boss img{height:140%;width:auto;margin-right:-4px;filter:drop-shadow(0 2px 3px #0004)}
/* Profile plate, festive look (2026-11-27, user: "ours is somehow boring"): painted ring with wings and blossoms, a
   flame along the banner, Reina's real face, big gold power, live glow and shine. Positions from build-profile-plate.py */
html body #stage .city-hud button.city-status.pf2{width:34%;top:.4%;left:.6%;aspect-ratio:1024/494}
html body #stage .city-hud .pf2 .pf2-face{left:7.3%;top:29.4%;width:22.4%;transform:none;background:radial-gradient(#ffe8f2,#c9a6e8)}
html body #stage .city-hud .pf2 .pf-city{left:18.5%;top:52.5%;height:58%}
html body #stage .city-hud .pf2 .pf2-band{left:35.5%;top:39.5%;width:55%;height:20.5%;padding:0 3%;gap:0;justify-content:center}
html body #stage .city-hud .pf2 .pf2-band b{font:900 clamp(8px,1.6cqw,14px)/1 Georgia,serif;letter-spacing:1px;color:#ffe9b8;opacity:.95}
html body #stage .city-hud .pf2 .pf2-band>span{gap:4px;font:900 clamp(12px,2.9cqw,26px)/1 Georgia,serif;color:transparent;background:linear-gradient(#fffbe0,#ffd25a 50%,#ff9a2a);-webkit-background-clip:text;background-clip:text;text-shadow:none;filter:drop-shadow(0 1px 0 #6a2a00) drop-shadow(0 0 6px #ff8a2a99)}
html body #stage .city-hud .pf2 .pf2-band>span i{font-size:.8em;color:#ffd24a;-webkit-text-fill-color:#ffd24a;filter:none}
html body #stage .city-hud .pf2 .pf2-xp{position:absolute;display:block;left:37.6%;width:49.6%;top:61.6%;height:2.6%;margin:0;border-radius:6px;background:#06143a;box-shadow:none;overflow:hidden}
html body #stage .city-hud .pf2 .pf2-xp u{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,#5ad04a,#c6ff7a);box-shadow:0 0 6px #9aff6a}
html body #stage .city-hud .pf2 .pf2-lv{left:18.6%;top:83.4%;font:900 clamp(9px,2cqw,18px)/1 Georgia,serif;color:#fff;text-shadow:0 1px 2px #000,0 0 6px #6aa8ff}
html body #stage .city-hud .pf2 .pf2-flame{position:absolute;left:40%;top:12%;width:58%;height:30%;border-radius:50%;background:radial-gradient(ellipse at 70% 60%,#ffb24a88,#ff6a1a33 45%,transparent 70%);mix-blend-mode:screen;pointer-events:none;animation:pf2-flame 1.6s ease-in-out infinite alternate}
@keyframes pf2-flame{from{opacity:.45;transform:scaleY(.9)}to{opacity:1;transform:scaleY(1.08) translateY(-4%)}}
