/* the run */
#stage .rl-run{display:block;background:var(--rlbg) center/cover;overflow:hidden}
#stage .rl-run::before{content:'';position:absolute;inset:0;background:linear-gradient(#ffffff70,#ffffff10 40%,#ffffff40 75%,#eaf5ffd0)}
#stage .rl-arena{position:absolute;inset:0}
#stage .rl-blist{position:absolute;left:3cqw;top:min(15cqw,64px);width:min(44cqw,230px);padding:10px 10px 8px;border-radius:16px;background:#ffffffd8;border:1.5px solid #f0d58a;box-shadow:0 4px 14px #3a5a8a26;z-index:3}
#stage .rl-blist h4{margin:8px 0 4px;font:900 14px/1 Georgia,serif;color:#2c4a7a;text-align:center}
#stage .rl-rage span{font:900 13px/1 Arial,sans-serif;color:#a8401a}#stage .rl-rage span b{color:#a8401a!important;-webkit-text-fill-color:currentColor;-webkit-text-stroke:0;text-shadow:none}
#stage .rl-rage i{display:block;height:9px;margin-top:4px;border-radius:5px;background:#fbe3d2;overflow:hidden}
#stage .rl-rage i b{display:block;width:0;height:100%;background:linear-gradient(90deg,#ffb84a,#e2443a);transition:width .5s}
#stage .rl-row{display:flex;justify-content:space-between;gap:6px;padding:6px 8px;border-radius:9px;font:800 min(2.8cqw,12.5px)/1.1 Arial,sans-serif;color:#2c3a58;border:1.5px solid transparent}
#stage .rl-row b{color:#2c3a58!important;-webkit-text-fill-color:currentColor;-webkit-text-stroke:0;text-shadow:none;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#stage .rl-row.on{border-color:#f0b030;background:#fff6d8}
#stage .rl-row em{font-style:normal;font-weight:900;white-space:nowrap;color:#24963a}
#stage .rl-row em.wait{color:#d0402a}#stage .rl-row em.fight{color:#e08a10}
#stage .rl-run .rl-me{position:absolute;left:2cqw;bottom:13cqh;height:38cqh;filter:drop-shadow(0 8px 8px #2a3a6a44);z-index:2}
#stage .rl-foe{position:absolute;right:2cqw;bottom:16cqh;width:60cqw;height:46cqh;display:grid;place-items:end center}
#stage .rl-foe img{max-width:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 10px 10px #2a3a6a44);transition:opacity .35s,transform .35s}
#stage .rl-foe img.hit{animation:ch-hit .22s}
#stage .rl-foe img.gone{opacity:0;transform:scale(.85)}
#stage .rl-run .rl-hp{position:absolute;left:20%;right:20%;top:-6px;height:12px;border-radius:7px;background:#ffffffaa;border:2px solid #fff;overflow:hidden;transform:none;width:auto}
#stage .rl-run .rl-hp i{display:block;height:100%;background:linear-gradient(90deg,#ff8a5c,#e2374a)}
#stage .rl-run .rl-nums b{position:absolute;font:900 min(6cqw,30px)/1 Georgia,serif;color:#fff;-webkit-text-stroke:1.5px #a8301a;paint-order:stroke;animation:ch-num .9s ease-out forwards;pointer-events:none;z-index:4}
#stage .rl-obtain{position:absolute;left:50%;top:12cqh;transform:translateX(-30%);display:grid;justify-items:center;gap:5px;z-index:4;pointer-events:none}
#stage .rl-ob{display:flex;align-items:center;gap:5px;padding:4px 14px 4px 10px;border-radius:999px;background:linear-gradient(90deg,#fffdf4f0,#fff6dcf0);border:1.5px solid #f0d58a;font:800 min(3.1cqw,14px)/1 Arial,sans-serif;color:#5a4320;box-shadow:0 2px 8px #3a5a8a22;animation:rl-ob .45s ease-out}
#stage .rl-ob :is(svg,img,.ui-icon,i.bag-ico){width:22px;height:22px;object-fit:contain}
#stage .rl-ob b{color:#b05a06}#stage .rl-ob i{font-style:normal;font-size:11px;color:#24963a}
@keyframes rl-ob{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
#stage .rl-auto{position:absolute;left:0;right:0;bottom:7cqh;text-align:center;font:900 min(5cqw,24px)/1 Georgia,serif;color:#ffe6a0;-webkit-text-stroke:1.5px #8a4a0e;paint-order:stroke;text-shadow:0 2px 6px #0003;animation:rl-pulse 1.4s ease-in-out infinite}
@keyframes rl-pulse{50%{opacity:.65}}
#stage .rl-banner{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%) scale(.8);padding:12px 26px;border-radius:18px;background:#fffdf4f2;border:2px solid #f0b030;font:900 min(4.4cqw,20px)/1.2 Georgia,serif;color:#a8401a;text-align:center;opacity:0;transition:.35s;z-index:6;box-shadow:0 6px 20px #3a5a8a33}
#stage .rl-banner.on{opacity:1;transform:translate(-50%,-50%) scale(1)}
/* Guardian Hunt = the dungeon lobby in the realm-hall layout (2026-11-27, user photos of the reference's boss halls) */
body[data-screen=dungeons] #stage{width:min(100%,86dvh)!important;max-width:none!important}
body[data-screen=dungeons] #stage>:is(header,nav,footer),body[data-screen=dungeons] .return-to-menu{display:none!important}
body[data-screen=dungeons] #stage>#main{inset:0!important;width:100%;height:100%;padding:0!important;display:block;overflow:hidden}
#stage .rl-dg .rl-stage{background:radial-gradient(ellipse 50% 40% at 50% 62%,color-mix(in srgb,var(--boss-glow) 45%,#fff0),#fff0 70%),var(--rlbg) center 40%/cover}
#stage .rl-dg .rl-boss{cursor:pointer;height:60%;bottom:9%}
#stage .rl-dg .rl-side{gap:min(1.2cqh,8px)}
#stage .rl-dg .rl-ic i{width:min(9.5cqw,44px,6.4cqh)}
#stage .rl-ic{position:relative}
#stage .rl-badge{position:absolute;top:-3px;right:8px;display:grid;place-items:center;min-width:18px;height:18px;padding:0 4px;border-radius:9px;background:#e2443a;color:#fff!important;font:900 11px/1 Arial,sans-serif;-webkit-text-fill-color:#fff}
#stage .rl-rscroll{display:grid;gap:6px;justify-items:center;max-height:min(42cqh,300px);overflow-y:auto;scrollbar-width:none;padding:2px 0}
#stage .rl-rscroll::-webkit-scrollbar{display:none}
#stage .rl-dg .rl-rt{width:min(11.5cqw,52px)}
#stage #main button.rl-rare{padding:4px 8px;border-radius:999px;border:1.5px solid #c9a8f0!important;background:#f6efff!important;color:#6a3ab0!important;font:900 11px/1 Arial,sans-serif}
#stage .rl-place{position:absolute;left:0;right:0;bottom:1.5%;margin:0;text-align:center;font:800 min(3cqw,13px)/1 Arial,sans-serif;color:#3a4a6a;pointer-events:none}
#stage .rl-place::before{content:'';position:absolute;inset:-4px calc(50% - 130px);border-radius:999px;background:#ffffffb8;z-index:-1}
#stage .rl-cards.five{grid-template-columns:repeat(5,1fr);gap:min(1.5cqw,8px)}
#stage .rl-cards.five .rl-dia{width:min(12cqw,58px,8.5cqh)}
#stage .rl-cards.five em{font-size:min(2.4cqw,12px)}
#stage .rl-top .en-chip{margin-left:0;background:#ffffffd8;border:1.5px solid #f0d58a;border-radius:999px}
@container (max-height:820px){#stage .rl-dg .rl-side{grid-template-columns:repeat(2,min(14cqw,66px));gap:6px 2px}#stage .rl-dg .rl-ic i{width:min(9cqw,40px)}#stage .rl-dg .rl-ic span{font-size:min(2.4cqw,11px)}}
#stage .rl-obtain{left:auto;right:3cqw;transform:none;justify-items:end}
#modal .rl-pop h3{margin:10px 0 6px;color:#7a4a0e!important;-webkit-text-fill-color:currentColor;font:900 16px/1.2 Georgia,serif}
#modal .rl-key b{color:#fff!important;-webkit-text-fill-color:#fff}
#stage .rl-line small.rl-price{display:flex;align-items:center;gap:2px;margin-left:4px;padding:2px 7px 2px 3px;border-radius:999px;background:#fff6d8;border:1px solid #f0d58a;color:#7a4a0e;font:900 11.5px/1 Arial,sans-serif}#stage .rl-line small.rl-price :is(svg,.gpt-icon){width:15px;height:15px}
/* Mark Shop: spare marks -> Star Orb (2026-11-27) */
#stage .mart-trade{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:6px 8px;margin:6px 0 2px;padding:8px 10px;border-radius:14px;background:#fffaf0e8;border:1px solid #f0d58a;font:800 13px/1.2 Arial,sans-serif;color:#6a4520}
#stage #main .mart-trade button{display:flex;align-items:center;gap:4px;min-height:0;margin:0;padding:4px 10px;border-radius:999px;border:1.5px solid #e2c47a!important;background:#fff!important;color:#5a3a10!important;font:800 13px/1 Arial,sans-serif;box-shadow:none}
#stage #main .mart-trade button::before,#stage #main .mart-trade button::after{content:none!important}
#stage #main .mart-trade button:disabled{opacity:.5}
#stage .mart-trade :is(i,span,img){max-width:22px;max-height:22px}
#stage .mart-trade>span{max-width:none;max-height:none}
/* Shop specialities and weekly limits (2026-11-27) */
#stage .shop-card.sig{box-shadow:0 0 0 2px #ffd56a,0 4px 12px #c08a2033}
#stage .shop-card.sig small{color:#a85a06;font-weight:900}
#modal .cloud-wares button .cloud-left{display:block;font:800 10.5px/1.2 Arial,sans-serif;color:#6a7a9a}
#modal .cloud-wares button.sig{box-shadow:0 0 0 2px #ffd56a}
#modal .cloud-wares button.sig .cloud-left{color:#a85a06}
/* Cloud Shop: light card (no dark frames) */
#stage #modal.cl-shop h2{color:#7a4a0e;font:900 22px/1.1 Georgia,serif}
#stage #modal.cl-shop .cloud-wallet{color:#5a4320}
#stage #modal.den-pop.cl-shop .cloud-wares button{background:linear-gradient(#ffffff,color-mix(in srgb,var(--rarity) 14%,#fff8ec));color:#3a2a10;border:2px solid color-mix(in srgb,var(--rarity) 70%,#fff)}
#stage #modal.cl-shop .cloud-wares span{color:#8a5a10}
#stage #modal.cl-shop .cloud-wares .shut{filter:saturate(.5);opacity:.7}
#stage #modal.cl-shop .cloud-wares .cloud-left{color:#7a8aa0}
#stage #modal.cl-shop .cloud-wares b,#stage #modal.cl-shop .cloud-wallet b{color:#3a2a10!important;-webkit-text-fill-color:currentColor;text-shadow:none}
/* ===== Prism Bazaar: top-up store (2026-11-27) ===== */
body[data-screen=topup] #stage{width:min(100%,86dvh)!important;max-width:none!important}
body[data-screen=topup] #stage>:is(header,nav,footer),body[data-screen=topup] .return-to-menu{display:none!important}
body[data-screen=topup] #stage>#main{inset:0!important;width:100%;height:100%;padding:0!important;display:block;overflow:hidden}
.pearl-ico,.prism-ico{width:1.25em;height:1.25em;object-fit:contain;vertical-align:-.28em}
#gold .pearl-ico,#pearls .pearl-ico{width:22px;height:22px}
#stage .tp-room{position:relative;width:100%;height:100%;container-type:size;display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:linear-gradient(#eaf4ff,#f7f1e6);font-family:Arial,sans-serif;color:#3a2f22}
#stage #main .tp-room button{min-height:0;margin:0;box-shadow:none;text-shadow:none;outline:0!important;letter-spacing:0;text-transform:none}
#stage #main .tp-room button::before,#stage #main .tp-room button::after{content:none!important}
#stage .tp-top{position:absolute;z-index:5;top:0;left:0;right:0;display:flex;align-items:center;gap:6px;padding:8px 3cqw 0;pointer-events:none}
#stage .tp-top>*{pointer-events:auto}
#stage .tp-ribbon{padding:6px 22px 6px 16px;clip-path:polygon(0 0,100% 0,92% 50%,100% 100%,0 100%);background:linear-gradient(90deg,#ffffffee,#e4f3ffdd);border-left:3px solid #e8b84a;font:900 min(4.4cqw,20px)/1.1 Georgia,serif;color:#2c4a7a;white-space:nowrap}
#stage .tp-chip{display:flex;align-items:center;gap:4px;padding:4px 10px 4px 5px;border-radius:999px;background:#ffffffde;border:1.5px solid #f0d58a;font:900 min(3cqw,13px)/1 Arial,sans-serif;color:#5a4320}
#stage .tp-chip:first-of-type{margin-left:auto}
#stage .tp-chip :is(svg,img,.gpt-icon){width:20px;height:20px;object-fit:contain}
#stage .tp-banner{height:min(30cqh,46cqw);background:var(--tpb) right 30%/cover;display:flex;align-items:center;padding:min(9cqh,60px) 0 0 5cqw;border-radius:0 0 22px 22px;box-shadow:0 6px 16px #3a5a8a22}
#stage .tp-banner h1{margin:0;font:900 min(8cqw,40px)/1.05 Georgia,serif;color:#fff4cf;-webkit-text-stroke:1.5px #9a6612;paint-order:stroke;text-shadow:0 3px 10px #8a5a1288;max-width:50%}
#stage .tp-body{overflow-y:auto;scrollbar-width:none;padding:12px 3cqw 14px;display:grid;gap:10px;align-content:start}
#stage .tp-body::-webkit-scrollbar{display:none}
#stage .tp-note{margin:0;text-align:center;font:800 13px/1.2 Arial,sans-serif;color:#5a6a8a}
#stage .tp-note b{color:#2e8a3a}
/* prism packs */
#stage .tp-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:min(2.4cqw,12px)}
#stage #main button.tp-card{position:relative;display:grid;justify-items:center;gap:2px;padding:10px 6px 0;border-radius:16px;border:2px solid #f0dca8!important;background:linear-gradient(#ffffff,#fbf6ea)!important;color:#5a4320!important;overflow:hidden}
#stage .tp-amt{display:flex;align-items:center;gap:4px;font:900 min(4.2cqw,20px)/1 Georgia,serif;color:#6a3ab0}
#stage .tp-pile{width:78%;aspect-ratio:1;object-fit:contain;filter:drop-shadow(0 6px 6px #5a3a9a33)}
#stage .tp-gift{display:flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:#fff3c8;font:800 min(2.7cqw,12px)/1.3 Arial,sans-serif;color:#2e8a3a}
#stage .tp-price{justify-self:stretch;margin:6px -6px 0;text-align:center;padding:min(1.6cqh,10px) 0;background:linear-gradient(#ffe9a0,#f6c652);font:900 min(4.2cqw,19px)/1 Georgia,serif;color:#5a2a06}
#stage .tp-x2{position:absolute;top:6px;left:6px;padding:2px 7px;border-radius:8px;background:linear-gradient(#ff7a6a,#e2443a);color:#fff;font:900 10px/1.2 Arial,sans-serif;font-style:normal;text-align:center}
/* weekly packs */
#stage .tp-week{display:flex;gap:10px;overflow-x:auto;scrollbar-width:none;padding:4px 2px 8px}
#stage .tp-week::-webkit-scrollbar{display:none}
#stage .tp-wk{position:relative;flex:0 0 min(31cqw,150px);display:grid;justify-items:center;align-content:start;gap:6px;padding:10px 8px 12px;border-radius:18px 18px 40% 40%/18px 18px 22px 22px;background:linear-gradient(var(--wk1),#fffaf0 62%);border:2px solid var(--wk2);box-shadow:0 4px 12px #3a5a8a22}
#stage .tp-wk1,#stage .tp-wk2{--wk1:#d9ccff;--wk2:#b9a4f4}#stage .tp-wk3{--wk1:#ffd9a8;--wk2:#f0b060}#stage .tp-wk4{--wk1:#ffc4b0;--wk2:#ec8a6a}#stage .tp-wk5{--wk1:#ffc4dc;--wk2:#ec7aa8}
#stage .tp-wk.out{filter:saturate(.4);opacity:.75}
#stage .tp-val{margin:0;padding:3px 10px;border-radius:999px;background:#ffffffcc;font:900 12.5px/1.2 Arial,sans-serif;color:#5a3a9a;white-space:nowrap}
#stage .tp-wk .tp-x2{top:30px;left:4px}
#stage .tp-wtiles{display:grid;gap:6px;justify-items:center}
#stage .tp-tile{position:relative;display:grid;place-items:center;width:min(15cqw,64px);aspect-ratio:1;border-radius:12px;background:linear-gradient(#ffffff,#fff2d8);border:2px solid #f0c060}
#stage .tp-tile :is(img,svg,i,.gpt-icon,span:not(.tp-tile)){width:68%;height:68%;object-fit:contain}
#stage .tp-tile b{position:absolute;right:3px;bottom:1px;font:900 min(2.6cqw,12px)/1 Arial,sans-serif;color:#3a2a10;-webkit-text-stroke:2.5px #fff;paint-order:stroke}
#stage .tp-wk s{font:700 12px/1 Arial,sans-serif;color:#b0402a}
#stage #main .tp-room button.tp-buy{display:inline-flex;align-items:center;gap:4px;padding:8px 22px 10px;border:0!important;border-radius:22px;background:url(assets/generated/ui-btn-gold.webp) center/100% 100% no-repeat!important;color:#5a2a06!important;font:900 min(3.8cqw,17px)/1 Georgia,serif;white-space:nowrap}
#stage #main .tp-room button.tp-buy:disabled{filter:saturate(.3);opacity:.6}
#stage .tp-wk>small{font:800 12px/1 Arial,sans-serif;color:#2e8a3a}
/* triple treat */
#stage .tp-cache{display:grid;grid-template-columns:min(30cqw,150px) 1fr;gap:10px;align-items:center;padding:10px;border-radius:18px;background:linear-gradient(100deg,var(--c1),#fffaf0 70%);border:2px solid var(--c2);box-shadow:0 4px 12px #3a5a8a1c}
#stage .tp-c1{--c1:#ecd9ff;--c2:#c9a8f0}#stage .tp-c2{--c1:#ffe6b0;--c2:#ecbe60}#stage .tp-c3{--c1:#ffd0c4;--c2:#ec8a72}
#stage .tp-cache.out{filter:saturate(.4);opacity:.75}
#stage .tp-cbox{display:grid;justify-items:center;text-align:center}
#stage .tp-cbox img{width:80%;aspect-ratio:1;object-fit:contain;filter:drop-shadow(0 6px 6px #5a3a2a33)}
#stage .tp-cbox b{font:900 min(3.6cqw,16px)/1.1 Georgia,serif;color:#5a2a3a}
#stage .tp-cbox small{font:700 11px/1.2 Arial,sans-serif;color:#7a6a5a}
#stage .tp-cright{position:relative;display:grid;justify-items:center;gap:6px}
#stage .tp-ctiles{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
#stage .tp-cright p{margin:0;font:700 12px/1 Arial,sans-serif;color:#b0402a}
#stage .tp-rebate{position:absolute;right:-4px;bottom:-6px;display:grid;place-items:center;width:46px;height:46px;clip-path:polygon(50% 0,61% 18%,82% 10%,80% 32%,100% 40%,85% 56%,96% 76%,74% 78%,68% 100%,50% 86%,32% 100%,26% 78%,4% 76%,15% 56%,0 40%,20% 32%,18% 10%,39% 18%);background:#e2443a;color:#fff;font:900 8.5px/1.05 Arial,sans-serif;font-style:normal;text-align:center}
#stage .tp-grand{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:10px;padding:10px;border-radius:16px;background:#fffaf0;border:2px dashed #e8c070}
#stage .tp-grand>div:first-child{display:grid;font:900 14px/1.2 Georgia,serif;color:#7a4a0e}#stage .tp-grand small{font:700 11.5px/1.2 Arial,sans-serif;color:#7a6a5a}
#stage #main .tp-room button.tp-all{position:relative;justify-self:center;padding:12px 30px;border:0!important;border-radius:999px;background:linear-gradient(#bfe6ff,#7cc0f0)!important;color:#123a6a!important;font:900 min(4cqw,17px)/1 Georgia,serif}
#stage .tp-all i{position:absolute;top:-14px;right:-14px;padding:6px 6px;border-radius:50%;background:#e2443a;color:#fff;font:900 10px/1 Arial,sans-serif;font-style:normal}
#stage #main .tp-room button.tp-all:disabled{opacity:.55}
/* tickets */
#stage .tp-swap{display:grid;gap:10px;padding:14px;border-radius:18px;background:#fffdf6;border:1.5px solid #ecd9a6;text-align:center}
#stage .tp-swap h3{margin:0;font:900 18px/1.2 Georgia,serif;color:#7a4a0e}
#stage .tp-swap p{margin:0;font:600 14px/1.45 Arial,sans-serif;color:#4a3a2a}
#stage .tp-swaprow{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}
#stage .tp-small{font-size:12.5px!important;color:#7a6a5a!important}
#stage #main .tp-room button.tp-link{justify-self:center;padding:8px 16px;border-radius:999px;border:1.5px solid #c9a8f0!important;background:#f6efff!important;color:#5a2a9a!important;font:900 13px/1 Arial,sans-serif}
/* bottom tabs */
#stage .tp-nav{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;padding:6px 3cqw max(10px,env(safe-area-inset-bottom));background:linear-gradient(#ffffff00,#fffaf0 30%)}
#stage #main .tp-nav button{position:relative;display:grid;justify-items:center;gap:2px;padding:6px 2px;border-radius:14px;border:1.5px solid #ecd9a6!important;background:#ffffffcc!important;color:#6a5a40!important;font:800 min(2.8cqw,12.5px)/1.1 Arial,sans-serif}
#stage #main .tp-nav button.on{background:linear-gradient(#fff3c8,#ffd56a)!important;border-color:#e8a830!important;color:#5a2a06!important}
#stage .tp-nav :is(svg,.gpt-icon){width:min(8cqw,34px);height:min(8cqw,34px)}
#stage .tp-badge{position:absolute;top:-6px;right:8px;padding:1px 6px;border-radius:6px;background:#e2443a;color:#fff;font:900 10px/1.3 Arial,sans-serif;font-style:normal}
#modal .tp-pop{display:grid;gap:10px;text-align:center}
#modal .tp-pop h2{margin:0 30px 0;color:#7a4a0e;font:900 20px/1.2 Georgia,serif}
#modal .tp-pop .tp-ctiles{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
#modal .tp-pop .tp-tile{position:relative;display:grid;place-items:center;width:58px;height:58px;border-radius:12px;background:linear-gradient(#ffffff,#fff2d8);border:2px solid #f0c060}
#modal .tp-pop .tp-tile :is(img,svg,i){width:70%;height:70%;object-fit:contain}
#modal .tp-pop .tp-tile b{position:absolute;right:3px;bottom:1px;font:900 12px/1 Arial,sans-serif;color:#3a2a10;-webkit-text-stroke:2.5px #fff;paint-order:stroke}
#modal .tp-pop .tp-small{font-size:13px;color:#7a6a5a}
#stage #main .tp-nav button{height:min(11cqh,68px);align-content:center;grid-auto-rows:auto}
#stage .tp-nav .den-x{display:none}
