#stage .pt-card li em{margin-left:6px;padding:0 5px;border-radius:4px;background:#e2443a;color:#fff;font:900 9px/1.5 Arial,sans-serif;font-style:normal;vertical-align:2px}
/* SVIP emblem in the Rank spot of the home screen */
html body #stage .city-hud .city-rank.pt-home{display:grid;justify-items:center;gap:0;font:900 min(2.6cqw,13px)/1.1 Arial,sans-serif;color:#fff;text-shadow:0 1px 2px #4a2a7a,0 0 4px #4a2a7a}
#stage .pt-hemb{position:relative;display:block;width:min(11cqw,54px);aspect-ratio:1;filter:drop-shadow(0 2px 4px #0005)}
#stage .pt-hemb img{width:100%!important;height:100%!important;object-fit:contain}
#stage .pt-hemb b{position:absolute;inset:0;display:grid;place-items:center;font:900 min(4.4cqw,22px)/1 Georgia,serif;color:#fff6c8;text-shadow:0 1px 0 #6a3aa0,0 0 6px #ffe9a0}
#stage .city-rank.pt-home.zero .pt-hemb{filter:grayscale(.35) drop-shadow(0 2px 4px #0005)}
#stage .city-rank.pt-home .tp-dot{top:0;right:0}
/* No running light / shimmer on the buttons of the VIP room and the Prism Bazaar (user: "what is this vibration") */
#stage #main :is(.pt-room,.tp-room) button::before,#stage #main :is(.pt-room,.tp-room) button::after{content:none!important;animation:none!important}
#stage .pt-daily.on i{animation:none!important;box-shadow:0 0 0 2px #ffd860,0 0 10px #ffd86099}
#stage #main .pt-room .pt-strip button.on{transform:none}
html body #stage .city-hud .city-rank.pt-home::before,html body #stage .city-hud .city-rank.pt-home::after{content:none!important;animation:none!important}
/* User 2026-11-27: "the bottom icons flicker" - the running light around every button and the sheen across it read as
   shaking on the iPad. Both keyframes now keep the effect invisible everywhere (the animation names stay so every rule
   that uses them simply shows nothing). */
@keyframes button-edge-light { from, to { opacity: 0; } }
@keyframes button-face-light { from, to { opacity: 0; } }

/* Cloud War fight: the hall softer behind the figures (user: "Reina and the boss blend into the background"). */
#stage .cf2 .cloud-battlefield{position:relative;isolation:isolate}
#stage .cf2 .cloud-battlefield::before{content:'';position:absolute;inset:-8px;z-index:-1;background:var(--arena-art) center/100% 100% no-repeat;filter:blur(2px) saturate(.72) brightness(1.08)}
#stage .cf2 .cloud-battlefield canvas{background:linear-gradient(#fffaf02e,#fffaf04a)!important}

/* Mounts a little smaller (user: "make all mounts a bit smaller"): the rider on the home screen (wings scaled with her,
   both about her feet) and on the Cloud War ride between defenders. */
.city-hud .city-hero.riding{left:35.1%;top:44.6%;width:29.8%;height:20.4%}
.city-hud .city-wings.riding{left:28.75%;top:41.2%;width:42.5%;height:17%}
#stage .cf2 .cloud-path img{width:34%}

/* Home pets animated (petAnimSvg): the SVG fills the pet box like the picture did (contain, feet on the bottom);
   the 15% pad around the pet's square may show past the box. */
.city-hud .city-pet svg.pet-anim{display:block;width:100%;height:100%;overflow:visible;pointer-events:none}

/* Home Reina breathes and her wings beat (heroLiveLayers): both layers are the same picture size, stacked exactly where
   the single winged portrait was (same 1.125 scale from the feet). Slow and small: a living figure, not a bounce. */
.city-hud .city-hero .hero-live{position:relative;width:100%;flex:1;min-height:0;transform:scale(1.125);transform-origin:50% 100%}
.city-hud .city-hero .hero-live img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:50% 100%}
.city-hud .city-hero .hl-body{transform-origin:50% 100%;animation:hero-breathe 3.6s ease-in-out infinite}
.city-hud .city-hero .hl-wings{transform-origin:50% 36%;animation:hero-wings 3.6s ease-in-out infinite}
@keyframes hero-breathe{0%,100%{transform:scale(1,1)}50%{transform:scale(1.006,1.014)}}
@keyframes hero-wings{0%,100%{transform:scale(1,1) translateY(0)}50%{transform:scale(.9,1.03) translateY(-1.2%)}}
.city-hud .city-wings.riding img{transform-origin:50% 60%;animation:hero-wings 3s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.city-hud .city-hero .hl-body,.city-hud .city-hero .hl-wings,.city-hud .city-wings.riding img{animation:none}}
.city-hud .city-hero .hero-live{animation:hero-sway 5.4s ease-in-out infinite}
@keyframes hero-sway{0%,100%{transform:scale(1.125) rotate(0deg)}50%{transform:scale(1.125) rotate(.7deg)}}
@media (prefers-reduced-motion:reduce){.city-hud .city-hero .hero-live{animation:none}}

/* Supreme Set: title and power under the figure, not over it (user circled the ribbon over the dress and the power over
   the ribbon; reference: a small red title badge under the feet, the power on its own line below). */
#stage #main .sup-room .sup-center{display:flex!important;flex-direction:column;align-items:center;justify-content:flex-end;gap:.4cqh}
#stage #main .sup-room .sup-center>:first-child{flex:1 1 auto;min-height:0;max-height:none}
#stage #main .sup-room .sup-center>img:first-child{height:auto;width:auto;max-width:100%;object-fit:contain}
#stage #main .sup-room .sup-center .sup-ribbon{position:static;flex:none;display:inline-flex;align-items:center;gap:.35em;
 padding:.18em 1.1em .18em .8em;border-radius:999px;font:800 min(2.7cqw,2.1cqh)/1.25 Georgia,serif;letter-spacing:.02em;
 color:#fff7e0;text-shadow:0 1px 2px #5a0a0a;background:linear-gradient(90deg,#9a1a22,#d8443a 50%,#9a1a22)!important;
 border:1px solid #ffd98a;box-shadow:0 2px 6px #0006,inset 0 1px 0 #ffffff55}
#stage #main .sup-room .sup-center .sup-ribbon::before{content:"✦";color:#ffe27a;font-size:.9em}
#stage #main .sup-room .sup-center .sup-cp{position:static;transform:none;flex:none;padding:0 1.2em;background:none;
 font:900 min(4.2cqw,3.2cqh)/1.1 Georgia,serif;color:#ffe27a;letter-spacing:.03em;
 background:radial-gradient(closest-side,#1a1450aa,transparent);text-shadow:0 0 8px #ffcf5a88,0 2px 2px #2a1a00}
#stage #main .sup-room .sup-center::before{inset:4% 15% 18%}

/* Reina alive outside the home screen too (user: "add animation to Reina as well"): Fashion stage, Supreme Set figure and
   the Character page breathe and sway from the feet; the Character page wings (a separate picture) beat. Uses the
   individual `scale` / `rotate` properties, so existing transforms on these pictures stay as they are. */
@keyframes reina-alive{0%,100%{scale:1 1;rotate:0deg}50%{scale:1.006 1.014;rotate:.5deg}}
@keyframes reina-wingbeat{0%,100%{scale:1 1;translate:0 0}50%{scale:.9 1.03;translate:0 -1.2%}}
.fx-room:not([data-category=Hair]) .fx-stage .fashion-model img,
#stage #main .sup-room .sup-center>img:first-child,
.reina-display .reina-figure{transform-origin:50% 100%;animation:reina-alive 4.2s ease-in-out infinite}
.reina-display .reina-sheet-wings img{transform-origin:50% 60%;animation:reina-wingbeat 3.6s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.fx-room .fx-stage .fashion-model img,#stage #main .sup-room .sup-center>img:first-child,.reina-display .reina-figure,.reina-display .reina-sheet-wings img{animation:none}}

/* Elite Sale shows only what the pack sells (user: "hair: only the head with the hair; wings: only the wings, not the
   whole Reina"): the wings picture alone, and a head-and-shoulders close-up of the look without wings. */
#stage #main .elite-sale .el-wings{height:34cqh;width:100%;display:grid;place-items:center}
#stage #main .elite-sale .el-wings img{height:100%!important;width:auto!important;max-width:100%!important;object-fit:contain;filter:drop-shadow(0 0 14px #c8b4ff) drop-shadow(0 10px 8px #2a1a5a66)}
#stage #main .elite-sale .el-head{position:relative;height:30cqh;aspect-ratio:1;max-width:100%;overflow:hidden;border-radius:50%;
 background:radial-gradient(#fff8 0,#c9b8ff66 45%,transparent 70%);
 -webkit-mask-image:radial-gradient(closest-side,#000 82%,transparent);mask-image:radial-gradient(closest-side,#000 82%,transparent)}
#stage #main .elite-sale .el-head img{position:absolute;width:208%!important;height:auto!important;max-width:none!important;max-height:none!important;left:-54%;top:-6%;filter:drop-shadow(0 6px 8px #2a1a5a55)}
/* The bow of the Weapon Pack covered its power line: smaller, and the power always on top. */
#stage #main .elite-sale .el-t1 .el-bow img,#stage #main .elite-sale .el-bow img{height:min(40cqw,30cqh)!important}
#stage #main .elite-sale .el-cp{position:relative;z-index:3}

/* The bow glows and shimmers (bowGlow / heroLiveHtml): a halo of the bow's own colour that pulses, and a band of light
   that runs along the bow (masked to the bow's shape). Both breathe with her. */
.city-hud .city-hero .hl-bow{transform-origin:50% 100%;animation:hero-breathe 3.6s ease-in-out infinite}
.city-hud .city-hero .hl-glow{transform-origin:50% 100%;mix-blend-mode:screen;animation:hero-breathe 3.6s ease-in-out infinite,bow-glow 2.4s ease-in-out infinite}
.city-hud .city-hero .hl-sweep{position:absolute;inset:0;overflow:hidden;pointer-events:none;transform-origin:50% 100%;
 -webkit-mask-size:contain;mask-size:contain;-webkit-mask-position:50% 100%;mask-position:50% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
 animation:hero-breathe 3.6s ease-in-out infinite;mix-blend-mode:screen}
.city-hud .city-hero .hl-sweep::before{content:"";position:absolute;left:0;right:0;top:-40%;height:40%;
 background:linear-gradient(transparent,#ffffff00 20%,#fffbe6cc 50%,#ffffff00 80%,transparent);animation:bow-sweep 2.8s linear infinite}
@keyframes bow-glow{0%,100%{opacity:.45}50%{opacity:1}}
@keyframes bow-sweep{0%{transform:translateY(0)}70%,100%{transform:translateY(350%)}}
@media (prefers-reduced-motion:reduce){.city-hud .city-hero .hl-glow,.city-hud .city-hero .hl-sweep::before,.city-hud .city-hero .hl-bow{animation:none}}
@keyframes bow-glow{0%,100%{opacity:.7}50%{opacity:1}}
.city-hud .city-hero .hl-sweep::before{background:linear-gradient(transparent,#ffffff00 15%,#ffffffee 50%,#ffffff00 85%,transparent)}
.city-hud .city-hero .hl-glow{mix-blend-mode:normal}
